CREATE OR REPLACE FUNCTION app_private.add_exchange_listing_comment(p_listing_id uuid, p_body text, p_operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();c public.exchange_listing_comments;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_body is null or char_length(btrim(p_body)) not between 1 and 500 or p_body!~'[^[:space:]]' then raise exception 'INVALID_EXCHANGE_COMMENT';end if;
 perform 1 from public.exchange_listings where id=p_listing_id and side='sell' and status in ('active','completed') for share;
 if not found then raise exception 'EXCHANGE_UNAVAILABLE';end if;
 insert into public.exchange_listing_comments(listing_id,user_id,operation_id,body)
 values(p_listing_id,u,p_operation_id,btrim(p_body)) on conflict(user_id,operation_id) do nothing;
 select * into strict c from public.exchange_listing_comments where user_id=u and operation_id=p_operation_id;
 if c.listing_id<>p_listing_id or c.body<>btrim(p_body) then raise exception 'OPERATION_CONFLICT';end if;
 return c.id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.adopt_suggestion(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_post public.suggestion_posts;v_rewards jsonb;v_count bigint;
begin
 if auth.uid() is null or not app_private.notice_is_operator() then raise exception 'SUGGESTION_OPERATOR_REQUIRED';end if;
 select * into v_post from public.suggestion_posts where id=p_id for update;
 if not found then raise exception 'SUGGESTION_NOT_FOUND';end if;
 if v_post.adopted_at is not null then return to_jsonb(v_post);end if;
 if not exists(select 1 from public.fishing_baits where id='bait_special') then raise exception 'REWARD_UNAVAILABLE';end if;
 insert into public.player_wallets(user_id) values(v_post.author_id) on conflict do nothing;
 select coalesce((inventory->>'bait_special')::bigint,0) into v_count from public.player_wallets where user_id=v_post.author_id for update;
 if v_count>2147483645 then raise exception 'INVENTORY_LIMIT';end if;
 update public.player_wallets set inventory=jsonb_set(inventory,'{bait_special}',to_jsonb((v_count+2)::integer)),updated_at=now() where user_id=v_post.author_id;
 v_rewards:=jsonb_build_object('bait_special',2);
 update public.suggestion_posts set adopted_at=now(),adopted_by=auth.uid(),reward=v_rewards where id=p_id returning * into v_post;
 insert into public.notifications(recipient_id,actor_id,category,kind,title,body)
 values(v_post.author_id,auth.uid(),'general','reward','[운영팀] 아이디어가 채택됐어요!',
  '「'||v_post.title||'」 건의가 채택되어 달빛 진주새우 2개를 지급했어요. 미끼통에서 확인해주세요.');
 return to_jsonb(v_post);
end $function$

CREATE OR REPLACE FUNCTION app_private.aquarium_background(p_id text, p_action text, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_item public.aquarium_backgrounds; v_wallet public.player_wallets; v_old public.gold_transactions;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_action is null or p_action not in ('buy','equip') then raise exception 'INVALID_TRADE'; end if;
 select * into v_item from public.aquarium_backgrounds where id=p_id;
 if not found then raise exception 'INVALID_ITEM'; end if;
 perform app_private.get_gold_wallet();
 select * into v_wallet from public.player_wallets where user_id=v_uid for update;
 if p_action='equip' then raise exception 'TANK_REQUIRED'; end if;
 if p_operation_id is null then raise exception 'INVALID_TRADE'; end if;
 select * into v_old from public.gold_transactions where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if v_old.action<>'buy' or v_old.item_id is distinct from ('background:'||p_id) then raise exception 'OPERATION_CONFLICT'; end if;
  return app_private.get_gold_wallet() || jsonb_build_object('delta',0);
 end if;
 if p_id='default' or exists(select 1 from public.owned_aquarium_backgrounds where user_id=v_uid and background_id=p_id) then raise exception 'BACKGROUND_ALREADY_OWNED'; end if;
 if v_wallet.gold<v_item.price then raise exception 'INSUFFICIENT_GOLD'; end if;
 update public.player_wallets set gold=gold-v_item.price,updated_at=now() where user_id=v_uid;
 insert into public.owned_aquarium_backgrounds(user_id,background_id) values(v_uid,p_id);
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','background:'||p_id,-v_item.price);
 return app_private.get_gold_wallet() || jsonb_build_object('delta',-v_item.price);
end $function$

CREATE OR REPLACE FUNCTION app_private.arcade_weekly_leaderboard(p_game text, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 uid uuid:=auth.uid();
 week_start date:=date_trunc('week',clock_timestamp() at time zone 'Asia/Seoul')::date;
 rows jsonb;total bigint;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_game is null or p_game not in('shadow','memory') or p_offset is null or p_offset<0 then raise exception 'INVALID_OFFSET';end if;
 select count(*) into total from app_private.arcade_weekly_rankings(p_game,week_start);
 select coalesce(jsonb_agg(jsonb_build_object('rank',r.rank,'id',r.run_id,'nickname',coalesce(p.nickname,'섬 여행자'),
 'avatarPath',p.avatar_path,'level',app_private.player_level(r.user_id),'levelProgress',app_private.player_level_progress(r.user_id),'mine',r.user_id=uid,'userId',r.user_id,'friendCode',p.friend_code,'friendStatus',(select f.status from public.friend_requests f where f.status in ('pending','accepted') and ((f.sender_id=uid and f.recipient_id=r.user_id) or (f.recipient_id=uid and f.sender_id=r.user_id)) order by f.created_at desc limit 1),'score',r.score,'elapsedMs',r.elapsed_ms,'moves',r.moves,'finishedAt',r.finished_at,
 'rewardGold',app_private.arcade_weekly_gold(r.rank)) order by r.rank),'[]'::jsonb) into rows
 from (select * from app_private.arcade_weekly_rankings(p_game,week_start) order by rank limit 20 offset p_offset) r
 left join public.player_profiles p on p.id=r.user_id;
 return jsonb_build_object('rows',rows,'total',total,'offset',p_offset,'pageSize',20,
 'weekStart',week_start::timestamp at time zone 'Asia/Seoul','weekEnd',(week_start+7)::timestamp at time zone 'Asia/Seoul',
 'rewards',jsonb_build_array(2000,1500,1000,650,400,200));
end $function$

CREATE OR REPLACE FUNCTION app_private.arrange_collectible_with_lock(p_collectible_id uuid, p_tank_id uuid, p_x numeric, p_y numeric, p_rotation numeric, p_scale numeric, p_flipped boolean, p_position_locked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();item public.player_collectibles;item_kind text;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_x is null or p_y is null or not(p_x between 0 and 1) or not(p_y between 0 and 1) then raise exception 'INVALID_POSITION';end if;
 if p_rotation is null or not(p_rotation between 0 and 360) or p_scale is null or not(p_scale between .5 and 2) or p_position_locked is null then raise exception 'INVALID_TRANSFORM';end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=u) then raise exception 'TANK_NOT_FOUND';end if;
 select * into item from public.player_collectibles where id=p_collectible_id and user_id=u and sold_at is null and escrow_gift_id is null for update;
 if not found or item.tank_id is distinct from p_tank_id then raise exception 'COLLECTIBLE_NOT_FOUND';end if;
 select kind::text into item_kind from public.collectible_species where id=item.species_id and (kind in ('decoration','trash') or (kind='fish' and movement_type='fixed'));
 if item_kind is null or (p_position_locked and item_kind<>'trash') then raise exception 'INVALID_ITEM';end if;
 update public.player_collectibles set position_x=p_x,position_y=p_y,rotation=mod(p_rotation,360),scale=p_scale,flipped=coalesce(p_flipped,false),position_locked=p_position_locked where id=item.id;
 return jsonb_build_object('id',item.id,'position_x',p_x,'position_y',p_y,'rotation',mod(p_rotation,360),'scale',p_scale,'flipped',coalesce(p_flipped,false),'position_locked',p_position_locked);
end $function$

CREATE OR REPLACE FUNCTION app_private.arrange_decoration(p_collectible_id uuid, p_tank_id uuid, p_x numeric, p_y numeric, p_rotation numeric, p_scale numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_item public.player_collectibles;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_x is null or p_y is null or not(p_x between 0 and 1) or not(p_y between 0 and 1) then raise exception 'INVALID_POSITION'; end if;
 if p_rotation is null or not(p_rotation between 0 and 360) or p_scale is null or not(p_scale between 0.5 and 2) then raise exception 'INVALID_TRANSFORM'; end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=v_uid) then raise exception 'TANK_NOT_FOUND'; end if;
 select * into v_item from public.player_collectibles
 where id=p_collectible_id and user_id=v_uid and sold_at is null and escrow_gift_id is null for update;
 if not found or v_item.tank_id is distinct from p_tank_id then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 if not exists(select 1 from public.collectible_species where id=v_item.species_id and kind='decoration') then raise exception 'INVALID_ITEM'; end if;
 update public.player_collectibles set position_x=p_x,position_y=p_y,rotation=mod(p_rotation,360),scale=p_scale where id=v_item.id;
 return jsonb_build_object('id',v_item.id,'position_x',p_x,'position_y',p_y,'rotation',mod(p_rotation,360),'scale',p_scale);
end $function$

CREATE OR REPLACE FUNCTION app_private.attendance_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_today date:=(transaction_timestamp() at time zone 'Asia/Seoul')::date;
 a public.player_attendance;v_checked boolean;v_streak integer;v_day integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into a from public.player_attendance where user_id=v_uid;
 v_checked:=coalesce(a.last_claim_date=v_today,false);
 v_streak:=case when a.last_claim_date between v_today-1 and v_today then a.streak else 0 end;
 if v_streak=0 then a.sheet_streak_offset:=0; end if;
 v_day:=case when v_checked then (v_streak-coalesce(a.sheet_streak_offset,0)-1)%28+1 else (v_streak-coalesce(a.sheet_streak_offset,0))%28+1 end;
 return jsonb_build_object('today',v_today,'checkedIn',v_checked,'streak',v_streak,
  'currentDay',v_day,'completedDays',case when v_checked then v_day else v_day-1 end,
  'sheetNumber',coalesce(a.completed_sheets,0)+case when v_checked and v_day=28 then 0 else 1 end,
  'completedSheets',coalesce(a.completed_sheets,0),'reset',coalesce(a.last_claim_date<v_today-1,false));
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_bid(p_id uuid, p_amount integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();a public.auction_listings;b public.auction_bids;v_gift uuid;v_delta integer;v_asset jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_amount is null or p_amount not between 1 and 1000000000 then raise exception 'INVALID_AUCTION_BID';end if;
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=v_uid for update;
 select * into b from public.auction_bids where bidder_id=v_uid and operation_id=p_operation_id;
 if found then
  if b.auction_id<>p_id or b.amount<>p_amount then raise exception 'OPERATION_CONFLICT';end if;
  return (select to_jsonb(q) from public.auction_listings q where id=p_id);
 end if;
 select * into a from public.auction_listings where id=p_id for update;
 if not found then raise exception 'AUCTION_NOT_FOUND';end if;
 if a.status<>'active' or a.ends_at<=clock_timestamp() then raise exception 'AUCTION_ENDED';end if;
 if a.owner_id is null then raise exception 'AUCTION_UNAVAILABLE';end if;
 if a.owner_id=v_uid then raise exception 'AUCTION_SELF_BID';end if;
 if p_amount<a.minimum_price or p_amount<=a.highest_amount then raise exception 'AUCTION_BID_TOO_LOW';end if;
 if a.highest_bidder=v_uid then
  v_delta:=p_amount-a.highest_amount;
  update public.player_wallets set gold=gold-v_delta,updated_at=now() where user_id=v_uid and gold>=v_delta;
  if not found then raise exception 'INSUFFICIENT_GOLD';end if;
  update public.collectible_gifts set quantity=p_amount,species=jsonb_set(species,'{quantity}',to_jsonb(p_amount))
   where id=a.highest_gift_id and exchange_hold;
  if not found then raise exception 'AUCTION_UNAVAILABLE';end if;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','auction:raise:'||a.id,-v_delta);
  v_gift:=a.highest_gift_id;
 else
  v_asset:=app_private.exchange_asset('gold','gold',p_amount);
  v_gift:=app_private.exchange_reserve(v_uid,v_asset);
  if a.highest_bidder is not null then
   perform app_private.exchange_deliver(a.highest_gift_id,a.highest_bidder,'더 높은 입찰이 들어와 입찰금 전액을 돌려보냈어요.');
   update public.notifications set title='입찰금이 반환됐어요' where gift_id=a.highest_gift_id and kind='gift_received';
  end if;
 end if;
 update public.auction_listings set highest_amount=p_amount,highest_bidder=v_uid,highest_gift_id=v_gift where id=a.id returning * into a;
 insert into public.auction_bids(auction_id,bidder_id,operation_id,amount) values(a.id,v_uid,p_operation_id,p_amount);
 return to_jsonb(a);
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_cancel(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();a public.auction_listings;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 select * into a from public.auction_listings where id=p_id for update;
 if not found then raise exception 'AUCTION_NOT_FOUND';end if;
 if a.owner_id is distinct from v_uid then raise exception 'AUCTION_FORBIDDEN';end if;
 if a.status='cancelled' then return to_jsonb(a);end if;
 if a.status<>'active' or a.ends_at<=clock_timestamp() then raise exception 'AUCTION_ENDED';end if;
 if a.highest_amount>0 then raise exception 'AUCTION_HAS_BIDS';end if;
 update public.auction_listings set status='cancelled',closed_at=clock_timestamp() where id=a.id returning * into a;
 perform app_private.exchange_deliver(a.escrow_gift_id,v_uid,'경매를 취소하여 맡긴 물품을 돌려보냈어요.');
 return to_jsonb(a);
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_post(p_kind text, p_item_id text, p_quantity integer, p_title text, p_description text, p_minimum_price integer, p_days integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_offer jsonb;a public.auction_listings;v_gift uuid;
 v_title text:=btrim(p_title);v_description text:=btrim(coalesce(p_description,''));
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_kind is null or p_kind not in('collectible','bait') or v_title is null or char_length(v_title) not between 2 and 60
 or char_length(v_description)>1000 or p_minimum_price is null or p_minimum_price not between 1 and 1000000000 or p_days is null or p_days not in(1,3,7) then raise exception 'INVALID_AUCTION';end if;
 v_offer:=app_private.exchange_asset(p_kind,p_item_id,p_quantity);
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=v_uid for update;
 select * into a from public.auction_listings where owner_id=v_uid and operation_id=p_operation_id;
 if found then
  if a.offer<>v_offer or a.title<>v_title or a.description<>v_description or a.minimum_price<>p_minimum_price or a.duration_days<>p_days then raise exception 'OPERATION_CONFLICT';end if;
  return to_jsonb(a);
 end if;
 if(select count(*) from public.auction_listings where owner_id=v_uid and status='active')>=10 then raise exception 'AUCTION_LIMIT';end if;
 v_gift:=app_private.exchange_reserve(v_uid,v_offer);
 insert into public.auction_listings(owner_id,owner_name,operation_id,title,description,offer,escrow_gift_id,minimum_price,duration_days,ends_at)
 values(v_uid,(select nickname from public.player_profiles where id=v_uid),p_operation_id,v_title,v_description,v_offer,v_gift,p_minimum_price,p_days,clock_timestamp()+make_interval(days=>p_days)) returning * into a;
 return to_jsonb(a);
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_settle(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.auction_listings;
begin
 select * into a from public.auction_listings where id=p_id for update;
 if not found or a.status<>'active' or a.ends_at>clock_timestamp() then return;end if;
 if a.owner_id is not null and a.highest_bidder is not null then
  update public.auction_listings set status='sold',closed_at=clock_timestamp() where id=a.id;
  perform app_private.exchange_deliver(a.escrow_gift_id,a.highest_bidder,'경매에 낙찰된 물품을 보냈어요.');
  perform app_private.exchange_deliver(a.highest_gift_id,a.owner_id,'경매가 마감되어 낙찰 대금을 보냈어요.');
  update public.notifications set title='경매에 낙찰됐어요' where gift_id=a.escrow_gift_id and kind='gift_received';
  update public.notifications set title='경매 판매가 완료됐어요' where gift_id=a.highest_gift_id and kind='gift_received';
 else
  update public.auction_listings set status='unsold',closed_at=clock_timestamp() where id=a.id;
  if a.owner_id is not null then
   perform app_private.exchange_deliver(a.escrow_gift_id,a.owner_id,'낙찰자 없이 경매가 끝나 맡긴 물품을 돌려보냈어요.');
   update public.notifications set title='경매 물품이 반환됐어요' where gift_id=a.escrow_gift_id and kind='gift_received';
  end if;
  if a.highest_bidder is not null and a.highest_gift_id is not null then
   perform app_private.exchange_deliver(a.highest_gift_id,a.highest_bidder,'판매자 계정이 없어 입찰금을 전액 돌려보냈어요.');
   update public.notifications set title='경매 입찰금이 반환됐어요' where gift_id=a.highest_gift_id and kind='gift_received';
  end if;
 end if;
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_settle_due()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;n integer:=0;
begin
 for r in select id from public.auction_listings where status='active' and ends_at<=clock_timestamp()
  order by ends_at,id limit 100 for update skip locked loop
  perform app_private.auction_settle(r.id);n:=n+1;
 end loop;
 return n;
end $function$

CREATE OR REPLACE FUNCTION app_private.auction_state(p_tab text DEFAULT 'all'::text, p_query text DEFAULT ''::text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_total integer;v_items jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_tab is null or p_tab not in('all','mine','bids') or p_query is null or char_length(p_query)>80 or p_offset is null or p_offset<0 then raise exception 'INVALID_AUCTION';end if;
 perform app_private.auction_settle_due();
 select count(*) into v_total from public.auction_listings a where
 (case p_tab when 'mine' then a.owner_id=v_uid when 'bids' then exists(select 1 from public.auction_bids b where b.auction_id=a.id and b.bidder_id=v_uid) else a.status='active' end)
 and (a.title ilike '%'||p_query||'%' or a.offer->>'name' ilike '%'||p_query||'%');
 select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc,q.id),'[]') into v_items from(
 select a.* from public.auction_listings a where
 (case p_tab when 'mine' then a.owner_id=v_uid when 'bids' then exists(select 1 from public.auction_bids b where b.auction_id=a.id and b.bidder_id=v_uid) else a.status='active' end)
 and (a.title ilike '%'||p_query||'%' or a.offer->>'name' ilike '%'||p_query||'%')
 order by a.created_at desc,a.id limit 20 offset p_offset)q;
 return jsonb_build_object('items',v_items,'total',v_total,'serverNow',clock_timestamp());
end $function$

CREATE OR REPLACE FUNCTION app_private.automatic_experience_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare amount integer;
begin
 if new.claimed_at is null then return new;end if;
 if tg_op='UPDATE' and old.claimed_at is not null then return new;end if;
 select coalesce(sum(app_private.catch_experience(item->'species'->>'kind',item->'species'->>'rarity',true)),0)::integer into amount
 from jsonb_array_elements(coalesce(new.result->'items','[]'::jsonb)) item;
 perform app_private.award_experience(new.user_id,case when tg_table_name='fishing_expeditions' then 'trap' else 'harbor' end,new.id,amount);
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.award_experience(p_user uuid, p_source text, p_source_id uuid, p_xp integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e app_private.player_experience;new_level integer;milestone integer;gift uuid;amount integer;player_name text;
begin
 insert into app_private.experience_events(source,source_id,user_id,xp) values(p_source,p_source_id,p_user,p_xp) on conflict(user_id,source,source_id) do nothing;
 if not found then return;end if;
 insert into app_private.player_experience(user_id) values(p_user) on conflict(user_id) do nothing;
 select * into strict e from app_private.player_experience where user_id=p_user for update;
 new_level:=app_private.experience_level(e.total_xp::numeric+e.curve_offset+p_xp);
 update app_private.player_experience set total_xp=total_xp+p_xp,updated_at=clock_timestamp(),rewarded_through=greatest(rewarded_through,new_level) where user_id=p_user;
 if new_level<=e.rewarded_through then return;end if;
 select nickname into strict player_name from public.player_profiles where id=p_user;
 for milestone in e.rewarded_through+1..new_level loop
  amount:=least(1000000000::bigint,100*((milestone::bigint+9)/10))::integer;
  insert into public.collectible_gifts(sender_name,recipient_id,recipient_name,operation_id,collectible_ids,species,quantity,message,source,reward_kind,reward_id)
  values('퐁당섬 운영팀',p_user,player_name,gen_random_uuid(),'{}'::uuid[],
   jsonb_build_object('id','level-up:'||milestone,'name','Lv.'||milestone||' 레벨업 보상'),amount,
   'Lv.'||milestone||' 달성을 축하해요! 레벨업 보상 '||amount||'골드를 받아주세요.','system','gold','level-up:'||milestone)
  on conflict do nothing returning id into gift;
  if gift is not null then
   insert into public.notifications(recipient_id,category,kind,title,body,gift_id)
   values(p_user,'gift','gift_received','레벨업 보상이 도착했어요!','Lv.'||milestone||' 달성 보상 '||amount||'골드를 보관함에서 받아주세요.',gift);
  end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION app_private.bait_production_action(p_action text, p_operation_id uuid, p_facility text, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w public.player_wallets;f public.bait_production_facilities;s app_private.bait_production_sites;prev app_private.bait_production_operations;
 sig jsonb;receipt jsonb;v_now timestamptz;v_count bigint;v_cost bigint;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in('buy','sell','start','claim','discard') or p_operation_id is null or p_facility is null or p_quantity is null or p_quantity not between 1 and 100 or (p_action<>'buy' and p_quantity<>1) then raise exception 'INVALID_PRODUCTION';end if;
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=u for update;
 sig:=jsonb_build_object('action',p_action,'facility',p_facility,'quantity',p_quantity);
 select * into prev from app_private.bait_production_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.bait_production_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 v_now:=clock_timestamp();
 if p_action='buy' then
  select * into f from public.bait_production_facilities where id=p_facility for share;
  if not found or not f.enabled then raise exception 'PRODUCTION_UNAVAILABLE';end if;
  v_cost:=f.price::bigint*p_quantity;
  if w.gold<v_cost then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into app_private.bait_production_sites(user_id,facility_id) select u,f.id from generate_series(1,p_quantity);
  update public.player_wallets set gold=gold-v_cost,updated_at=v_now where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','bait-production:'||f.id,-v_cost);
  receipt:=jsonb_build_object('action','buy','count',p_quantity);
 else
  select * into s from app_private.bait_production_sites where id=p_facility::uuid and user_id=u for update;
  if not found then raise exception 'PRODUCTION_NOT_OWNED';end if;
  select * into f from public.bait_production_facilities where id=s.facility_id for share;
  if p_action='sell' then
   if s.started_at is not null then raise exception 'PRODUCTION_BUSY';end if;
   v_cost:=f.price/2;
   if w.gold::bigint+v_cost>1000000000 then raise exception 'GOLD_LIMIT';end if;
   delete from app_private.bait_production_sites where id=s.id and user_id=u;
   update public.player_wallets set gold=gold+v_cost,updated_at=v_now where user_id=u;
   insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'sell','bait-production:'||f.id,v_cost);
   receipt:=jsonb_build_object('action','sell','facility',f.id,'siteId',s.id,'gold',v_cost,'count',1);
  elsif p_action='start' then
   if not f.enabled then raise exception 'PRODUCTION_UNAVAILABLE';end if;
   if s.started_at is not null then raise exception 'PRODUCTION_BUSY';end if;
   if app_private.bait_production_active_count()>=4 then raise exception 'PRODUCTION_ACTIVE_LIMIT';end if;
   if coalesce((w.inventory->>'fuel')::bigint,0)<f.fuel_cost then raise exception 'INSUFFICIENT_FUEL';end if;
   update public.player_wallets set inventory=jsonb_set(inventory,'{fuel}',to_jsonb((inventory->>'fuel')::integer-f.fuel_cost)),updated_at=v_now where user_id=u;
   update app_private.bait_production_sites set started_at=v_now,completes_at=v_now+make_interval(mins=>f.production_minutes),expires_at=v_now+make_interval(mins=>f.production_minutes+f.storage_minutes),run_output=f.output_count,run_bait_id=f.bait_id where id=s.id;
  else
   if s.started_at is null then raise exception 'PRODUCTION_IDLE';end if;
   if p_action='claim' then
    if v_now<s.completes_at then raise exception 'PRODUCTION_NOT_READY';end if;
    if v_now>=s.expires_at then raise exception 'PRODUCTION_EXPIRED';end if;
    v_count:=coalesce((w.inventory->>s.run_bait_id)::bigint,0)+s.run_output;
    if v_count>1000000000 then raise exception 'BAIT_LIMIT';end if;
    update public.player_wallets set inventory=jsonb_set(inventory,array[s.run_bait_id],to_jsonb(v_count::integer)),updated_at=v_now where user_id=u;
   elsif v_now<s.expires_at then raise exception 'PRODUCTION_NOT_EXPIRED';end if;
   update app_private.bait_production_sites set started_at=null,completes_at=null,expires_at=null,run_output=null,run_bait_id=null where id=s.id;
  end if;
  if p_action<>'sell' then
   receipt:=jsonb_build_object('action',p_action,'siteId',s.id,'count',case when p_action='claim' then s.run_output else 0 end);
  end if;
 end if;
 insert into app_private.bait_production_operations values(u,p_operation_id,sig,receipt);
 return app_private.bait_production_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.bait_production_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();r jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 perform app_private.get_gold_wallet();
 select jsonb_build_object('activeTotal',app_private.bait_production_active_count(),'serverNow',clock_timestamp(),'gold',w.gold,'fuel',coalesce((w.inventory->>'fuel')::integer,0),
 'facilities',(select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('baitName',b.name,'image_path',b.image_path,'ownedCount',(select count(*) from app_private.bait_production_sites s where s.user_id=u and s.facility_id=f.id)) order by f.price,f.id),'[]'::jsonb) from public.bait_production_facilities f join public.fishing_baits b on b.id=f.bait_id where f.enabled),
 'sites',(select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('siteId',s.id,'baitName',b.name,'image_path',b.image_path,'startedAt',s.started_at,'completesAt',s.completes_at,'expiresAt',s.expires_at,'runOutput',s.run_output) order by s.purchased_at,s.id),'[]'::jsonb) from app_private.bait_production_sites s join public.bait_production_facilities f on f.id=s.facility_id join public.fishing_baits b on b.id=f.bait_id where s.user_id=u)) into r from public.player_wallets w where user_id=u;
 return r;
end $function$

CREATE OR REPLACE FUNCTION app_private.base_quest_period(p_kind text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();start_date date;start_at timestamptz;end_at timestamptz;
 attempts integer;rare_catches integer;epic_catches integer;trash_catches integer;decor_catches integer;
 posts integer;trades integer;departures integer;games integer;care integer;gifts integer;maps integer;rods integer;
 boosts integer;need_map boolean;need_rod boolean;entries jsonb;bonus integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_kind not in ('daily','weekly') or p_kind is null then raise exception 'INVALID_QUEST';end if;
 start_date:=case when p_kind='daily' then (p_now at time zone 'Asia/Seoul')::date else date_trunc('week',p_now at time zone 'Asia/Seoul')::date end;
 start_at:=start_date::timestamp at time zone 'Asia/Seoul';
 end_at:=(start_date+case when p_kind='daily' then 1 else 7 end)::timestamp at time zone 'Asia/Seoul';
 select count(*) into attempts from public.fishing_attempts where user_id=u and created_at>=start_at and created_at<end_at;
 -- Catch quests include manual catches and collected expedition results, never gifts or purchases.
 with catches as (
  select s.rarity::text rarity,s.kind::text kind from public.fishing_attempts a
  join public.player_collectibles c on c.id=a.collectible_id join public.collectible_species s on s.id=c.species_id
  where a.user_id=u and a.created_at>=start_at and a.created_at<end_at
  union all
  select item->'species'->>'rarity',item->'species'->>'kind'
  from public.fishing_expeditions e cross join lateral jsonb_array_elements(coalesce(e.result->'items','[]'::jsonb)) item
  where e.user_id=u and e.claimed_at>=start_at and e.claimed_at<end_at
 ) select count(*) filter(where rarity in ('rare','epic','mythic')),
 count(*) filter(where rarity in ('epic','mythic')),
 count(*) filter(where kind='trash'),count(*) filter(where kind='decoration')
 into rare_catches,epic_catches,trash_catches,decor_catches from catches;
 select count(*) into posts from public.exchange_listings where owner_id=u and side='sell' and created_at>=start_at and created_at<end_at;
 select count(*) into trades from public.exchange_listings where (owner_id=u or taker_id=u) and status='completed' and closed_at>=start_at and closed_at<end_at;
 select count(*) into departures from public.fishing_expeditions where user_id=u and departed_at>=start_at and departed_at<end_at;
 select count(*) filter(where item_id in ('arcade:memory','arcade:shadow','arcade:odd-even')),
 count(*) filter(where item_id like 'map:%'),count(*) filter(where item_id like 'rod:%') into games,maps,rods
 from public.gold_transactions where user_id=u and action='buy' and delta<0 and created_at>=start_at and created_at<end_at;
 select count(*) into care from (
  select id from public.aquarium_feedings where visitor_id=u and owner_id<>u and completed_at>=start_at and completed_at<end_at
  union all select id from public.aquarium_cleanings where visitor_id=u and owner_id<>u and completed_at>=start_at and completed_at<end_at
 ) visits;
 select count(*) into gifts from public.collectible_gifts where sender_id=u and source='friend' and created_at>=start_at and created_at<end_at;
 select count(*) into boosts from app_private.expedition_boosts where helper_id=u and created_at>=start_at and created_at<end_at;
 need_map:=maps>0 or exists(select 1 from public.region_maps m join public.regions r on r.id=m.region_id
  where r.requires_map_fragment and not exists(select 1 from public.player_map_fragments f where f.user_id=u and f.region_id=m.region_id));
 need_rod:=rods>0 or exists(select 1 from public.fishing_rods r where r.price>0
  and not exists(select 1 from public.player_fishing_rods o where o.user_id=u and o.rod_id=r.id));
 with definitions(id,title,target,progress,href,icon,ord) as (values
  ('post','판매글 올리기',1,posts,'/exchange','exchange',1),
  ('fish','낚시 5회',5,attempts,'/harbor','rod',2),
  ('depart','통발 설치 1회',1,departures,'/expeditions','expeditions',3),
  ('rare','희귀 이상 포획',1,rare_catches,'/harbor','fish',4),
  ('game','미니게임 실전 플레이 1회',1,games,'/arcade','gameplay',5),
  ('care','친구 어항 청소 또는 먹이 주기',1,care,'/friends','mailFriend',6),
  ('trade','거래 7회 완료',7,trades,'/exchange','exchange',11),
  ('weekly_fish','낚시 40회',40,attempts,'/harbor','rod',12),
  ('epic','특급 이상 포획',1,epic_catches,'/harbor','fish',13),
  ('trash','쓰레기 10회 포획',10,trash_catches,'/harbor','trash',14),
  ('gift','선물 3회 하기',3,gifts,'/notifications?tab=gift','mailGift',15),
  ('decor','장식물 10회 포획',10,decor_catches,'/harbor','decoration',16),
  ('map','지도 구매',1,maps,'/shop?tab=maps','map',17),
  ('rod','낚싯대 구매',1,rods,'/shop?tab=rods','rod',18),
  ('boost','통발 30번 도와주기',30,boosts,'/friends','expeditionBoost',19)
 ), rows as (
  select d.*,c.quest_id is not null claimed from definitions d left join app_private.quest_claims c
   on c.user_id=u and c.period_kind=p_kind and c.period_start=start_date and c.quest_id=d.id
  where (p_kind='daily' and ord<10) or (p_kind='weekly' and ord>10 and (id<>'map' or need_map or c.quest_id is not null) and (id<>'rod' or need_rod or c.quest_id is not null))
 ) select jsonb_agg(jsonb_build_object('id',id,'title',title,'target',target,'progress',least(progress,target),
 'claimed',claimed,'complete',progress>=target or claimed,'reward',case when p_kind='daily' then 30 else 50 end,'href',href,'icon',icon) order by ord) into entries from rows;
 bonus:=case when p_kind='daily' then 200 else 1000 end;
 return jsonb_build_object('kind',p_kind,'start',start_date,'resetsAt',end_at,'quests',entries,'bonus',bonus,
 'bonusReady',not exists(select 1 from jsonb_array_elements(entries) q where not (q->>'complete')::boolean),
 'bonusClaimed',exists(select 1 from app_private.quest_claims where user_id=u and period_kind=p_kind and period_start=start_date and quest_id='all'));
end $function$

CREATE OR REPLACE FUNCTION app_private.board_action(p_action text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<payload>>
declare uid uuid:=auth.uid(); pid uuid; cid uuid; target public.board_posts; comment public.board_comments;
  parent public.board_comments; actor text; choice smallint; previous smallint; images text[]; title text; body text;
begin
  if uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select nickname into actor from public.player_profiles where id=uid;
  if actor is null then raise exception 'NICKNAME_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,4731));
  pid:=(p_payload->>'post_id')::uuid;
  if pid is null then raise exception 'INVALID_BOARD_REQUEST'; end if;
  if p_action='save' then
    select * into target from public.board_posts where id=pid for update;
    if found and target.author_id<>uid then raise exception 'NOT_ALLOWED'; end if;
    title:=btrim(p_payload->>'title'); body:=btrim(p_payload->>'body');
    if title is null or char_length(title) not between 1 and 80 or body is null or char_length(body) not between 1 and 5000 then raise exception 'INVALID_BOARD_REQUEST'; end if;
    select coalesce(array_agg(value),'{}'::text[]) into images from jsonb_array_elements_text(coalesce(p_payload->'images','[]'::jsonb));
    if cardinality(images)>3 or exists(select 1 from unnest(images) path where path !~ ('^'||uid::text||'/'||pid::text||'/[0-9a-f-]+\.(png|jpg|webp)$')) then raise exception 'INVALID_BOARD_IMAGE'; end if;
    if exists(select 1 from unnest(images) path where not exists(select 1 from storage.objects o where o.bucket_id='board-images' and o.name=path)) then raise exception 'INVALID_BOARD_IMAGE'; end if;
    if target.id is null then
      if (select count(*) from public.board_posts where author_id=uid and created_at>now()-interval '1 minute')>=3 then raise exception 'BOARD_RATE_LIMIT'; end if;
      insert into public.board_posts(id,author_id,title,body,images) values(pid,uid,title,body,images);
    else update public.board_posts set title=payload.title,body=payload.body,images=payload.images,updated_at=now() where id=pid; end if;
    return pid;
  end if;
  select * into target from public.board_posts where id=pid for update;
  if not found then raise exception 'BOARD_NOT_FOUND'; end if;
  if p_action='delete' then
    if target.author_id<>uid and not app_private.notice_is_operator() then raise exception 'NOT_ALLOWED'; end if;
    delete from public.board_posts where id=pid; return pid;
  elsif p_action='comment' then
    cid:=(p_payload->>'id')::uuid;
    if cid is null then raise exception 'INVALID_BOARD_REQUEST'; end if;
    select * into comment from public.board_comments where id=cid;
    if found then
      if comment.author_id<>uid or comment.post_id<>pid or comment.deleted then raise exception 'NOT_ALLOWED'; end if;
      return pid; -- Retry of the same comment must not send duplicate notifications.
    end if;
    body:=btrim(p_payload->>'body');
    if body is null or char_length(body) not between 1 and 1000 then raise exception 'INVALID_BOARD_REQUEST'; end if;
    if (select count(*) from public.board_comments where author_id=uid and created_at>now()-interval '1 minute')>=10 then raise exception 'BOARD_RATE_LIMIT'; end if;
    if nullif(p_payload->>'parent_id','') is not null then
      select * into parent from public.board_comments where id=(p_payload->>'parent_id')::uuid and post_id=pid;
      if not found or parent.parent_id is not null or parent.deleted then raise exception 'INVALID_BOARD_REPLY'; end if;
    end if;
    insert into public.board_comments(id,post_id,author_id,parent_id,body) values(cid,pid,uid,parent.id,body);
    insert into public.notifications(recipient_id,actor_id,category,kind,title,body,board_post_id)
      select recipient,uid,'general','system',case when parent.id is null then '내 글에 새 댓글이 달렸어요' else '새 답글이 달렸어요' end,
        left(actor||': '||body,500),pid from (select target.author_id recipient union select parent.author_id where parent.author_id is not null) recipients where recipient<>uid;
    return pid;
  elsif p_action='edit_comment' or p_action='delete_comment' then
    select * into comment from public.board_comments where id=(p_payload->>'id')::uuid and post_id=pid for update;
    if not found or comment.deleted then raise exception 'COMMENT_NOT_FOUND'; end if;
    if comment.author_id<>uid and not (p_action='delete_comment' and app_private.notice_is_operator()) then raise exception 'NOT_ALLOWED'; end if;
    if p_action='delete_comment' then update public.board_comments set body='',deleted=true,updated_at=now() where id=comment.id;
    else
      body:=btrim(p_payload->>'body');
      if body is null or char_length(body) not between 1 and 1000 then raise exception 'INVALID_BOARD_REQUEST'; end if;
      update public.board_comments set body=payload.body,updated_at=now() where id=comment.id;
    end if;
    return pid;
  elsif p_action='react' then
    choice:=(p_payload->>'value')::smallint; cid:=nullif(p_payload->>'comment_id','')::uuid;
    if choice is null or choice not in (-1,0,1) then raise exception 'INVALID_BOARD_REQUEST'; end if;
    if cid is not null and not exists(select 1 from public.board_comments where id=cid and post_id=pid and not deleted) then raise exception 'COMMENT_NOT_FOUND'; end if;
    -- Set the desired state, rather than toggling, so network retries are safe.
    if choice=0 then delete from public.board_reactions where user_id=uid and post_id=pid and comment_id is not distinct from cid;
    else insert into public.board_reactions(user_id,post_id,comment_id,value) values(uid,pid,cid,choice)
      on conflict(user_id,post_id,comment_id) do update set value=excluded.value;
    end if;
    return pid;
  end if;
  raise exception 'INVALID_BOARD_REQUEST';
end $function$

CREATE OR REPLACE FUNCTION app_private.board_detail(p_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_offset<0 or p_offset>10000 then raise exception 'INVALID_BOARD_REQUEST'; end if;
  select app_private.board_post_json(p) into result from public.board_posts p where p.id=p_id;
  if result is null then return null; end if;
  return jsonb_build_object('post',result,'comments',coalesce((select jsonb_agg(q.item order by q.created_at asc,q.id asc) from (
    select c.id,c.created_at,to_jsonb(c)||jsonb_build_object(
      'author_name',a.nickname,'avatar_path',a.avatar_path,'equipped_title',a.equipped_title,
      'parent_author_name',pa.nickname,
      'likes',(select count(*) from public.board_reactions r where r.comment_id=c.id and r.value=1),
      'dislikes',(select count(*) from public.board_reactions r where r.comment_id=c.id and r.value=-1),
      'my_reaction',coalesce((select r.value from public.board_reactions r where r.comment_id=c.id and r.user_id=auth.uid()),0)
    ) item from public.board_comments c join public.player_profiles a on a.id=c.author_id
    left join public.board_comments parent on parent.id=c.parent_id left join public.player_profiles pa on pa.id=parent.author_id
    where c.post_id=p_id order by c.created_at asc,c.id asc limit 50 offset p_offset
  )q),'[]'::jsonb),'comment_total',(select count(*) from public.board_comments where post_id=p_id));
end $function$

CREATE OR REPLACE FUNCTION app_private.board_feed(p_sort text DEFAULT 'latest'::text, p_mine boolean DEFAULT false, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_sort not in ('latest','popular') or p_offset<0 or p_offset>10000 then raise exception 'INVALID_BOARD_REQUEST'; end if;
  select jsonb_build_object('items',coalesce(jsonb_agg(q.item order by q.rank_order),'[]'::jsonb),
    'total',(select count(*) from public.board_posts p where not p_mine or p.author_id=auth.uid())) into result
  from (select app_private.board_post_json(p) item,row_number() over(order by
    case when p_sort='popular' then (select count(*) from public.board_reactions r where r.post_id=p.id and r.comment_id is null and r.value=1) end desc nulls last,p.created_at desc,p.id desc) rank_order
    from public.board_posts p where not p_mine or p.author_id=auth.uid()
    order by rank_order limit 20 offset p_offset) q;
  return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.boost_friend_expedition(p_expedition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();e public.fishing_expeditions;b app_private.expedition_boosts;owner_id uuid;t timestamptz;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 select user_id into owner_id from public.fishing_expeditions where id=p_expedition_id;
 if not found then raise exception 'EXPEDITION_NOT_FOUND';end if;
 -- Locks the accepted friendship before the expedition, also excluding self.
 perform app_private.require_aquarium_friend(owner_id);
 select * into e from public.fishing_expeditions where id=p_expedition_id for update;
 if not found then raise exception 'EXPEDITION_NOT_FOUND';end if;
 -- A retried response must succeed even when this help caused the boat to return.
 select * into b from app_private.expedition_boosts where expedition_id=e.id and helper_id=u;
 if found then return app_private.friend_expedition_status()||jsonb_build_object('replayed',true);end if;
 t:=clock_timestamp();
 if e.claimed_at is not null or e.returns_at<=t then raise exception 'EXPEDITION_NOT_SAILING';end if;
 insert into app_private.expedition_boosts(expedition_id,helper_id,nickname,avatar_path)
 select e.id,u,nickname,avatar_path from public.player_profiles where id=u returning * into b;
 if not found then raise exception 'NICKNAME_REQUIRED';end if;
 insert into public.notifications(recipient_id,actor_id,category,kind,title,body,expedition_boost_id)
 values(e.user_id,u,'general','system',b.nickname||'님이 물고기를 유인해줬어요',
 '친구가 통발에 물고기를 유인해 수확이 최대 10분 빨라졌어요.',b.id);
 update public.fishing_expeditions set returns_at=greatest(t,returns_at-interval '10 minutes') where id=e.id;
 return app_private.friend_expedition_status()||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.brick_game_settle(p_user_id uuid, p_run_id uuid, p_score integer, p_reward integer, p_replay jsonb, p_final boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.brick_game_runs;v_gold integer;v_delta integer;v_ticks integer;
begin
 select gold into v_gold from public.player_wallets where user_id=p_user_id for update;
 if not found then raise exception 'WALLET_NOT_FOUND';end if;
 select * into r from public.brick_game_runs where id=p_run_id and user_id=p_user_id for update;
 if not found then raise exception 'RUN_NOT_FOUND';end if;
 if r.finished_at is not null then return to_jsonb(r);end if;
 v_ticks:=(p_replay->>'ticks')::integer;
 if p_score is null or p_score not between 0 and 360 or p_reward is null or (r.engine_version=1 and p_reward not in (0,10,30,60,100,150))
  or (r.engine_version in (2,3,4,5,6) and (p_score<>0 or p_reward not between 0 and 6400 or p_reward%10<>0))
  or p_reward<r.reward or p_score<r.score or v_ticks is null or v_ticks<r.ticks or v_ticks>216000
  or v_ticks>floor(extract(epoch from(clock_timestamp()-r.started_at))*120)+240
  or jsonb_typeof(p_replay->'inputs') is distinct from 'array'
  or octet_length(p_replay::text)>(case when r.engine_version=1 then 1000000 else 8000000 end)
  or p_final is null then raise exception 'INVALID_SETTLEMENT';end if;
 v_delta:=p_reward-r.paid_reward;
 if v_gold>1000000000-v_delta then raise exception 'GOLD_LIMIT';end if;
 if v_delta>0 then
  update public.player_wallets set gold=gold+v_delta,updated_at=clock_timestamp() where user_id=p_user_id;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(p_user_id,gen_random_uuid(),'charge','arcade:brick-breaker:'||r.id::text,v_delta);
 end if;
 update public.brick_game_runs set score=p_score,reward=p_reward,paid_reward=p_reward,ticks=v_ticks,replay=p_replay,
  finished_at=case when p_final then clock_timestamp() else null end where id=r.id returning * into r;
 return to_jsonb(r);
end $function$

