CREATE OR REPLACE FUNCTION app_private.capture_title_acquisition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.collectible_species;fresh boolean;last_one boolean:=false;complete boolean:=false;
begin
 perform pg_advisory_xact_lock(hashtextextended('title-acquisition:'||new.user_id::text,0));
 select * into strict s from public.collectible_species where id=new.species_id;
 fresh:=not exists(select 1 from public.player_discoveries where user_id=new.user_id and species_id=new.species_id);
 if fresh and s.kind='fish' and s.rarity='mythic' then
  last_one:=not exists(select 1 from public.collectible_species x where x.kind='fish' and x.rarity='mythic' and x.id<>s.id
   and not exists(select 1 from public.player_discoveries d where d.user_id=new.user_id and d.species_id=x.id));
 end if;
 if s.is_native then
  complete:=not exists(select 1 from public.collectible_species x where x.is_native and x.native_region_id=s.native_region_id
   and not exists(select 1 from public.player_discoveries d where d.user_id=new.user_id and d.species_id=x.id));
 end if;
 insert into app_private.title_acquisition_evidence values(new.id,new.user_id,new.species_id,fresh,last_one,complete);
 insert into app_private.title_dirty values(new.user_id) on conflict do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.catch_experience(p_kind text, p_rarity text, p_automatic boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare amount numeric;
begin
 if p_kind not in ('fish','trash','decoration','map') or p_kind is null or p_rarity not in ('common','rare','epic','mythic') or p_rarity is null or p_automatic is null then raise exception 'INVALID_EXPERIENCE_CATCH';end if;
 amount:=case when p_kind='map' then 30 else case p_rarity when 'common' then 10 when 'rare' then 30 when 'epic' then 100 else 400 end end;
 if p_kind='trash' then amount:=amount/2;end if;
 if p_automatic then amount:=amount*0.3;end if;
 return round(amount)::integer;
end $function$

CREATE OR REPLACE FUNCTION app_private.check_native_collectible_habitats()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_ids text[];v_id text;v_region text;v_count bigint;v_match bigint;
begin
 if tg_table_name='collectible_species' then
  if tg_op='DELETE' then v_ids:=array[old.id];
  elsif tg_op='INSERT' then v_ids:=array[new.id];
  else v_ids:=array[old.id,new.id]; end if;
 else
  if tg_op='DELETE' then v_ids:=array[old.species_id];
  elsif tg_op='INSERT' then v_ids:=array[new.species_id];
  else v_ids:=array[old.species_id,new.species_id]; end if;
 end if;
 for v_id in select distinct unnest(v_ids) loop
  select native_region_id into v_region from public.collectible_species where id=v_id;
  if found and v_region is not null then
   select count(*),count(*) filter(where region_id=v_region) into v_count,v_match
    from public.collectible_habitats where species_id=v_id;
   if v_count<>1 or v_match<>1 then
    raise exception 'NATIVE_HABITAT_REQUIRED: % must have exactly one habitat in %',v_id,v_region using errcode='23514';
   end if;
  end if;
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION app_private.claim_attendance(p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_today date:=(transaction_timestamp() at time zone 'Asia/Seoul')::date;
 a public.player_attendance;c public.attendance_claims;w public.player_wallets;
 v_streak integer;v_day integer;v_bait text;v_count integer;v_gold integer;v_fuel integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_day is null then raise exception 'INVALID_ATTENDANCE_DAY'; end if;
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=v_uid for update;
 select * into c from public.attendance_claims where user_id=v_uid and claim_date=p_day;
 if found then
  return app_private.attendance_state()||jsonb_build_object('replayed',true,'reward',to_jsonb(c));
 end if;
 if p_day<>v_today then raise exception 'ATTENDANCE_DAY_CHANGED'; end if;
 insert into public.player_attendance(user_id) values(v_uid) on conflict do nothing;
 select * into a from public.player_attendance where user_id=v_uid;
 v_streak:=case when a.last_claim_date=v_today-1 then a.streak+1 else 1 end;
 if a.last_claim_date is distinct from v_today-1 then a.sheet_streak_offset:=0; end if;
 v_day:=(v_streak-a.sheet_streak_offset-1)%28+1;
 v_gold:=case when v_day%7<>0 and v_day%2=1 then 200 else 0 end;
 v_fuel:=case when v_day%7<>0 and v_day%2=0 then 3 else 0 end;
 v_bait:=case when v_day=28 then 'bait_epic' when v_day%7=0 then 'bait_first_greeting' else null end;
 if v_gold>0 and w.gold>1000000000-v_gold then raise exception 'GOLD_LIMIT'; end if;
 if v_fuel>0 then
  v_count:=coalesce((w.inventory->>'fuel')::integer,0);
  if v_count>100000-v_fuel then raise exception 'FUEL_LIMIT'; end if;
  w.inventory:=jsonb_set(w.inventory,'{fuel}',to_jsonb(v_count+v_fuel));
 end if;
 if v_bait is not null then
  if not exists(select 1 from public.fishing_baits where id=v_bait) then raise exception 'ATTENDANCE_REWARD_UNAVAILABLE'; end if;
  v_count:=coalesce((w.inventory->>v_bait)::integer,0);
  if v_count>=2147483647 then raise exception 'INVENTORY_LIMIT'; end if;
  w.inventory:=jsonb_set(w.inventory,array[v_bait],to_jsonb(v_count+1));
 end if;
 update public.player_wallets set gold=gold+v_gold,inventory=w.inventory,updated_at=now() where user_id=v_uid;
 update public.player_attendance set last_claim_date=v_today,streak=v_streak,sheet_streak_offset=a.sheet_streak_offset,
  completed_sheets=completed_sheets+case when v_day=28 then 1 else 0 end where user_id=v_uid;
 insert into public.attendance_claims(user_id,claim_date,streak,sheet_day,bait_id,gold,fuel)
 values(v_uid,v_today,v_streak,v_day,v_bait,v_gold,v_fuel) returning * into c;
 if v_gold>0 then
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
  values(v_uid,c.operation_id,'charge','attendance:'||v_today::text,v_gold);
 end if;
 return app_private.attendance_state()||jsonb_build_object('replayed',false,'reward',to_jsonb(c));
end $function$

CREATE OR REPLACE FUNCTION app_private.claim_collectible_gift(p_gift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();g public.collectible_gifts;v_count integer;v_inventory integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=v_uid for update;
 select * into g from public.collectible_gifts where id=p_gift_id and recipient_id=v_uid and not exchange_hold for update;
 if not found then raise exception 'GIFT_NOT_FOUND';end if;
 if g.status='claimed' then return to_jsonb(g);end if;
 if g.reward_kind='gold' then
  update public.player_wallets set gold=gold+g.quantity,updated_at=now() where user_id=v_uid and gold<=1000000000-g.quantity;
  if not found then raise exception 'GOLD_LIMIT';end if;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,g.id,'charge','exchange:claim:'||g.id,g.quantity);
 elsif g.reward_kind in ('bait','fuel') then
  select coalesce((inventory->>g.reward_id)::integer,0) into v_inventory from public.player_wallets where user_id=v_uid;
  if v_inventory>2147483647-g.quantity then raise exception 'INVENTORY_LIMIT';end if;
  update public.player_wallets set inventory=jsonb_set(inventory,array[g.reward_id],to_jsonb(v_inventory+g.quantity)),updated_at=now() where user_id=v_uid;
 else
  perform app_private.aquarium_state();
  perform 1 from public.player_collectibles where user_id=v_uid and escrow_gift_id=g.id order by id for update;
  select count(*) into v_count from public.player_collectibles where user_id=v_uid and escrow_gift_id=g.id and sold_at is null;
  if v_count<>g.quantity then raise exception 'GIFT_UNAVAILABLE';end if;
  update public.player_collectibles set tank_id=null,escrow_gift_id=null where user_id=v_uid and escrow_gift_id=g.id;
  -- Gifts enter storage; only actual catches unlock the collection.
 end if;
 update public.collectible_gifts set status='claimed',claimed_at=now() where id=g.id returning * into g;
 update public.notifications set read_at=coalesce(read_at,now()) where recipient_id=v_uid and gift_id=g.id and kind='gift_received';
 if g.sender_id is not null and g.source='friend' then
  insert into public.notifications(recipient_id,actor_id,category,kind,title,body,gift_id)
  values(g.sender_id,v_uid,'gift','gift_claimed','선물을 받았어요',g.recipient_name||'님이 보낸 선물을 받았어요.',g.id) on conflict do nothing;
 end if;
 return to_jsonb(g);
end $function$

CREATE OR REPLACE FUNCTION app_private.claim_quest(p_kind text, p_start date, p_quest_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();p jsonb;q jsonb;amount integer;fuel integer:=0;w public.player_wallets;balance integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_kind is null or p_kind not in ('daily','weekly','growth') or p_start is null or p_quest_id is null then raise exception 'INVALID_QUEST';end if;
 perform app_private.get_gold_wallet();select * into w from public.player_wallets where user_id=u for update;
 if p_kind='growth' then p:=app_private.growth_quest_period();else p:=app_private.quest_period(p_kind,clock_timestamp());end if;
 if p_start<>(p->>'start')::date then raise exception 'QUEST_PERIOD_CHANGED';end if;
 if p_quest_id='all' then
  if p_kind='growth' then raise exception 'INVALID_QUEST';end if;
  if not (p->>'bonusReady')::boolean then raise exception 'QUEST_INCOMPLETE';end if;
  amount:=(p->>'bonus')::integer;
 else
  select value into q from jsonb_array_elements(p->'quests') where value->>'id'=p_quest_id;
  if q is null then raise exception 'INVALID_QUEST';end if;
  if not (q->>'complete')::boolean then raise exception 'QUEST_INCOMPLETE';end if;
  amount:=(q->>'reward')::integer;fuel:=coalesce((q->>'rewardFuel')::integer,0);
 end if;
 if exists(select 1 from app_private.quest_claims where user_id=u and period_kind=p_kind and period_start=p_start and quest_id=p_quest_id) then
  return app_private.quest_state()||jsonb_build_object('credited',0,'creditedFuel',0);
 end if;
 if w.gold::bigint+amount>1000000000 then raise exception 'GOLD_LIMIT';end if;
 balance:=coalesce((w.inventory->>'fuel')::integer,0);
 if fuel>0 and balance>100000-fuel then raise exception 'FUEL_LIMIT';end if;
 insert into app_private.quest_claims(user_id,period_kind,period_start,quest_id,gold,fuel) values(u,p_kind,p_start,p_quest_id,amount,fuel);
 update public.player_wallets set gold=gold+amount,inventory=case when fuel>0 then jsonb_set(inventory,'{fuel}',to_jsonb(balance+fuel)) else inventory end,updated_at=clock_timestamp() where user_id=u;
 if amount>0 then insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,gen_random_uuid(),'charge','quest:'||p_kind||':'||p_start||':'||p_quest_id,amount);end if;
 return app_private.quest_state()||jsonb_build_object('credited',amount,'creditedFuel',fuel);
end $function$

CREATE OR REPLACE FUNCTION app_private.claim_web_push(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 update app_private.push_deliveries q set status='skipped',finished_at=clock_timestamp()
 from app_private.push_subscriptions s where s.id=q.subscription_id and q.status in ('pending','sending') and (q.locked_until is null or q.locked_until<clock_timestamp())
 and (q.expires_at<=clock_timestamp() or q.attempts>=5 or (q.category<>'test' and not(q.category=any(s.categories))) or not app_private.push_delivery_current(q,s.user_id));
 with due as (
  select q.id from app_private.push_deliveries q where q.status in ('pending','sending') and q.attempts<5
   and q.available_at<=clock_timestamp() and q.expires_at>clock_timestamp() and (q.locked_until is null or q.locked_until<clock_timestamp())
  order by q.available_at,q.id limit greatest(1,least(coalesce(p_limit,20),20)) for update skip locked
 ), claimed as (
  update app_private.push_deliveries q set status='sending',attempts=q.attempts+1,lease_token=gen_random_uuid(),locked_until=clock_timestamp()+interval '3 minutes'
  from due where q.id=due.id returning q.*
 ) select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'leaseToken',q.lease_token,'payload',q.payload,'subscription',jsonb_build_object('endpoint',s.endpoint,'keys',jsonb_build_object('p256dh',s.p256dh,'auth',s.auth)))),'[]'::jsonb)
 into result from claimed q join app_private.push_subscriptions s on s.id=q.subscription_id;
 -- Finished payloads are short-lived; never retain a growing delivery history.
 delete from app_private.push_deliveries where finished_at<clock_timestamp()-interval '7 days';
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.clean_friend_aquarium(p_tank uuid, p_operation uuid, p_step integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_owner uuid;v_tank_name text;f public.aquarium_cleanings;v_replayed boolean:=false;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_tank is null or p_operation is null or p_step is null or p_step not between 1 and 3 then raise exception 'INVALID_CLEANING';end if;
 select user_id,name into v_owner,v_tank_name from public.aquarium_tanks where id=p_tank for share;
 if not found then raise exception 'TANK_NOT_FOUND';end if;
 perform app_private.require_aquarium_friend(v_owner);
 if p_step=1 then
  insert into public.aquarium_cleanings(visitor_id,owner_id,tank_id,operation_id,strokes)
  values(v_uid,v_owner,p_tank,p_operation,1) on conflict(visitor_id,operation_id) do nothing;
  v_replayed:=not found;
 end if;
 select * into f from public.aquarium_cleanings where visitor_id=v_uid and operation_id=p_operation for update;
 if not found then raise exception 'CLEANING_STEP_REQUIRED';end if;
 if f.tank_id is distinct from p_tank or f.owner_id<>v_owner then raise exception 'OPERATION_CONFLICT';end if;
 if p_step>f.strokes+1 then raise exception 'CLEANING_STEP_REQUIRED';end if;
 if p_step<=f.strokes then
  if p_step<>1 then v_replayed:=true;end if;
 else
  update public.aquarium_cleanings set strokes=p_step,completed_at=case when p_step=3 then transaction_timestamp() end
  where id=f.id returning * into f;
  if p_step=3 then
   insert into app_private.aquarium_clean_notices(visitor_id,owner_id,notice_day)
   values(v_uid,v_owner,(transaction_timestamp() at time zone 'Asia/Seoul')::date) on conflict do nothing;
   if found then
    insert into public.notifications(recipient_id,actor_id,category,kind,title,body)
    values(v_owner,v_uid,'general','system','친구가 어항을 닦아줬어요',
    (select nickname from public.player_profiles where id=v_uid)||'님이 '||v_tank_name||'을 반짝이게 닦아줬어요.');
   end if;
  end if;
 end if;
 return jsonb_build_object('id',f.id,'strokes',f.strokes,'completed',f.completed_at is not null,'replayed',v_replayed);
end $function$

CREATE OR REPLACE FUNCTION app_private.collectible_storage(p_offset integer DEFAULT 0, p_query text DEFAULT ''::text, p_kind text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_total integer;v_items jsonb;v_query text:=btrim(coalesce(p_query,''));
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_offset is null or p_offset<0 or char_length(v_query)>60 or p_kind is null or p_kind not in ('all','fish','trash','decoration') then raise exception 'INVALID_STORAGE_QUERY'; end if;
 select count(*) into v_total from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.user_id=v_uid and c.tank_id is null and c.sold_at is null and c.escrow_gift_id is null
   and s.kind in ('fish','trash','decoration') and (p_kind='all' or s.kind::text=p_kind) and strpos(s.name,v_query)>0;
 select coalesce(jsonb_agg((to_jsonb(q)-'storage_order')||jsonb_build_object('species',app_private.species_payload(q.species_id,q.map_region_id)) order by q.storage_order),'[]'::jsonb) into v_items
 from (select c.*,row_number() over(order by case s.rarity when 'mythic' then 3 when 'epic' then 2 when 'rare' then 1 else 0 end asc,s.sell_price asc,s.name collate "C",s.id,c.acquired_at desc,c.id) as storage_order from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.user_id=v_uid and c.tank_id is null and c.sold_at is null and c.escrow_gift_id is null
   and s.kind in ('fish','trash','decoration') and (p_kind='all' or s.kind::text=p_kind) and strpos(s.name,v_query)>0
 order by storage_order limit 50 offset p_offset) q;
 return jsonb_build_object('items',v_items,'total',v_total,'pageSize',50);
end $function$

CREATE OR REPLACE FUNCTION app_private.collectible_storage_filtered(p_offset integer DEFAULT 0, p_query text DEFAULT ''::text, p_kind text DEFAULT 'all'::text, p_rarity text DEFAULT 'all'::text, p_concept text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();query text:=btrim(coalesce(p_query,''));result jsonb;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or char_length(query)>60 or p_kind is null or p_kind not in ('all','fish','trash','decoration')
 or p_rarity is null or p_rarity not in ('all','common','rare','epic','mythic') or p_concept is null
 or (p_concept not in ('all','common') and not exists(select 1 from public.regions where id=p_concept)) then raise exception 'INVALID_STORAGE_QUERY';end if;
 with matched as materialized (
  select c.*,row_number() over(order by case s.rarity when 'mythic' then 3 when 'epic' then 2 when 'rare' then 1 else 0 end asc,s.sell_price asc,s.name collate "C",s.id,c.acquired_at desc,c.id) as storage_order from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
  where c.user_id=uid and c.tank_id is null and c.sold_at is null and c.escrow_gift_id is null
  and s.kind in ('fish','trash','decoration') and (p_kind='all' or s.kind::text=p_kind)
  and (p_rarity='all' or s.rarity::text=p_rarity)
  and (p_concept='all' or (p_concept='common' and s.native_region_id is null) or s.native_region_id=p_concept)
  and strpos(lower(s.name),lower(query))>0
 ), page as (select * from matched order by storage_order limit 50 offset p_offset)
 select jsonb_build_object('total',(select count(*) from matched),'pageSize',50,'items',coalesce((select jsonb_agg((to_jsonb(p)-'storage_order')||jsonb_build_object('species',app_private.species_payload(p.species_id,p.map_region_id)) order by p.storage_order) from page p),'[]'::jsonb)) into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.configure_web_push_worker(p_url text, p_secret text, p_keys jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid uuid; entry record;
begin
 if p_url !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/web-push$' or p_secret !~ '^[A-Za-z0-9_-]{43}$' then raise exception 'INVALID_PUSH_CONFIGURATION';end if;
 if to_regclass('vault.secrets') is null then raise exception 'VAULT_UNAVAILABLE';end if;
 execute 'select id from vault.secrets where name=$1 limit 1' into sid using 'web_push_worker_url';
 if sid is null then execute 'select vault.create_secret($1,$2)' using p_url,'web_push_worker_url';else execute 'select vault.update_secret($1,$2)' using sid,p_url;end if;
 execute 'select id from vault.secrets where name=$1 limit 1' into sid using 'web_push_cron_secret';
 if sid is null then execute 'select vault.create_secret($1,$2)' using p_secret,'web_push_cron_secret';else execute 'select vault.update_secret($1,$2)' using sid,p_secret;end if;
 if p_keys is not null then
  if coalesce(p_keys->>'WEB_PUSH_PUBLIC_KEY','') !~ '^[A-Za-z0-9_-]{87}$' or coalesce(p_keys->>'WEB_PUSH_PRIVATE_KEY','') !~ '^[A-Za-z0-9_-]{43}$'
   or coalesce(p_keys->>'WEB_PUSH_SUBJECT','') !~ '^(https://|mailto:)[^[:space:]]+$' then raise exception 'INVALID_PUSH_KEYS';end if;
  for entry in select * from jsonb_each_text(p_keys) where key in ('WEB_PUSH_PUBLIC_KEY','WEB_PUSH_PRIVATE_KEY','WEB_PUSH_SUBJECT') loop
   execute 'select id from vault.secrets where name=$1 limit 1' into sid using lower(entry.key);
   if sid is null then execute 'select vault.create_secret($1,$2)' using entry.value,lower(entry.key);else execute 'select vault.update_secret($1,$2)' using sid,entry.value;end if;
  end loop;
 end if;
end $function$

