CREATE OR REPLACE FUNCTION app_private.exchange_action(p_listing_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();l public.exchange_listings;owner uuid;payment uuid;parcel uuid;parcels uuid[];
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in ('accept','cancel') then raise exception 'INVALID_EXCHANGE';end if;
 select owner_id into owner from public.exchange_listings where id=p_listing_id;
 if owner is null then raise exception 'EXCHANGE_NOT_FOUND';end if;
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id in(u,owner) order by user_id for update;
 select * into l from public.exchange_listings where id=p_listing_id for update;
 select array_agg(gift_id order by gift_id) into parcels from app_private.exchange_bundle_gifts where listing_id=l.id;
 parcels:=coalesce(parcels,array[l.escrow_gift_id]);
 if p_action='cancel' then
  if l.owner_id<>u then raise exception 'EXCHANGE_FORBIDDEN';end if;
  if l.status='cancelled' then return to_jsonb(l);end if;
  if l.status<>'active' then raise exception 'EXCHANGE_UNAVAILABLE';end if;
  update public.exchange_listings set status='cancelled',closed_at=now() where id=l.id returning * into l;
  foreach parcel in array parcels loop
   perform app_private.exchange_deliver(parcel,u,'거래를 취소하여 맡긴 물품을 돌려보냈어요.');
  end loop;
 else
  if l.owner_id=u then raise exception 'EXCHANGE_SELF_TRADE';end if;
  if l.status='completed' and l.taker_id=u then return to_jsonb(l);end if;
  if l.status<>'active' then raise exception 'EXCHANGE_UNAVAILABLE';end if;
  if l.side<>'sell' or l.offer->>'kind' not in ('collectible','bait','fuel') or l.wanted->>'kind'<>'gold' then raise exception 'EXCHANGE_UNAVAILABLE';end if;
  payment:=app_private.exchange_reserve(u,l.wanted);
  update public.exchange_listings set status='completed',taker_id=u,closed_at=now() where id=l.id returning * into l;
  foreach parcel in array parcels loop
   perform app_private.exchange_deliver(parcel,u,'구매한 묶음 물품을 선물함에서 받아주세요.');
  end loop;
  perform app_private.exchange_deliver(payment,l.owner_id,'판매가 성사되어 판매 대금을 보냈어요.');
  update public.notifications set title='판매가 성사됐어요' where gift_id=payment and kind='gift_received';
  update public.notifications set title='구매가 완료됐어요',body='구매한 물품을 선물함에서 받아주세요.' where gift_id=any(parcels) and kind='gift_received';
 end if;
 return to_jsonb(l);
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_asset(p_kind text, p_id text, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_name text;v_path text;v_subtype text;
begin
 if p_quantity is null or p_quantity<1 then raise exception 'INVALID_EXCHANGE_ASSET';end if;
 if p_kind='gold' and p_id='gold' and p_quantity<=1000000000 then
  return jsonb_build_object('kind','gold','id','gold','quantity',p_quantity,'name','골드','thumbnail_path',null);
 elsif p_kind='fuel' and p_id='fuel' and p_quantity<=9999 then
  return jsonb_build_object('kind','fuel','id','fuel','quantity',p_quantity,'name','기름','thumbnail_path','/app-icons/fuel.png');
 elsif p_kind='bait' and p_quantity<=9999 then
  select name,image_path into v_name,v_path from public.fishing_baits where id=p_id;
 elsif p_kind='collectible' and p_quantity<=20 then
  select name,thumbnail_path,kind::text into v_name,v_path,v_subtype from public.collectible_species
   where id=p_id and kind in ('fish','trash','decoration') and id not like 'test-%';
 else raise exception 'INVALID_EXCHANGE_ASSET';end if;
 if v_name is null then raise exception 'INVALID_EXCHANGE_ASSET';end if;
 return jsonb_build_object('kind',p_kind,'id',p_id,'quantity',p_quantity,'name',v_name,'thumbnail_path',v_path,'subtype',v_subtype);
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_deliver(p_gift uuid, p_recipient uuid, p_message text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare g public.collectible_gifts;v_name text;
begin
 select nickname into v_name from public.player_profiles where id=p_recipient;
 if v_name is null then raise exception 'PROFILE_REQUIRED';end if;
 update public.collectible_gifts set recipient_id=p_recipient,recipient_name=v_name,exchange_hold=false,message=p_message
 where id=p_gift and exchange_hold and source='exchange' returning * into g;
 if not found then raise exception 'EXCHANGE_UNAVAILABLE';end if;
 update public.player_collectibles set user_id=p_recipient,tank_id=null where escrow_gift_id=p_gift;
 insert into public.notifications(recipient_id,actor_id,category,kind,title,body,gift_id)
 values(p_recipient,g.sender_id,'gift','gift_received','거래소 물품이 도착했어요',p_message,g.id) on conflict do nothing;
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_inventory()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 perform app_private.get_gold_wallet();
 return jsonb_build_object('gold',(select gold from public.player_wallets where user_id=v_uid),
 'assets',coalesce((select jsonb_agg(app_private.exchange_asset('collectible',s.id,1)||jsonb_build_object('available',(
  select count(*) from public.player_collectibles c where c.user_id=v_uid and c.species_id=s.id and c.sold_at is null and c.escrow_gift_id is null and c.tank_id is null
 ))) from public.collectible_species s where s.kind in ('fish','trash','decoration') and s.id not like 'test-%'),'[]'::jsonb)||
 coalesce((select jsonb_agg(app_private.exchange_asset('bait',b.id,1)||jsonb_build_object('available',coalesce((w.inventory->>b.id)::integer,0)))
 from public.fishing_baits b cross join public.player_wallets w where w.user_id=v_uid),'[]'::jsonb)||jsonb_build_array(app_private.exchange_asset('fuel','fuel',1)||jsonb_build_object('available',(select coalesce((inventory->>'fuel')::integer,0) from public.player_wallets where user_id=v_uid))));
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_listing_detail(p_listing_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();l public.exchange_listings;v_listing jsonb;v_comments jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 then raise exception 'INVALID_EXCHANGE';end if;
 select * into l from public.exchange_listings where id=p_listing_id and side='sell'
  and (status in ('active','completed') or owner_id=u);
 if not found then raise exception 'EXCHANGE_NOT_FOUND';end if;
 select (to_jsonb(l)-'operation_id'-'escrow_gift_id')||jsonb_build_object(
  'owner_avatar_path',(select avatar_path from public.player_profiles where id=l.owner_id),
  'like_count',(select count(*) from public.exchange_listing_likes where listing_id=l.id),
  'comment_count',(select count(*) from public.exchange_listing_comments where listing_id=l.id),
  'liked',exists(select 1 from public.exchange_listing_likes where listing_id=l.id and user_id=u)
 ) into v_listing;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc,q.id desc),'[]'::jsonb) into v_comments from(
  select c.id,c.user_id,c.body,c.created_at,p.nickname as author_name,p.avatar_path as author_avatar_path
  from public.exchange_listing_comments c join public.player_profiles p on p.id=c.user_id
  where c.listing_id=l.id order by c.created_at desc,c.id desc limit 30 offset p_offset
 ) q;
 return jsonb_build_object('listing',v_listing,'comments',v_comments,'pageSize',30);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.exchange_post(p_side text, p_offer_kind text, p_offer_id text, p_offer_quantity integer, p_wanted_kind text, p_wanted_id text, p_wanted_quantity integer, p_operation_id uuid, p_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_offer jsonb;v_wanted jsonb;l public.exchange_listings;v_gift uuid;v_title text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_side is null or p_side<>'sell' or p_operation_id is null then raise exception 'INVALID_EXCHANGE';end if;
 v_offer:=app_private.exchange_asset(p_offer_kind,p_offer_id,p_offer_quantity);
 v_title:=coalesce(nullif(btrim(p_title),''),(v_offer->>'name')||' 판매합니다');
 if char_length(v_title)>80 or v_title ~ '[[:cntrl:]]' then raise exception 'INVALID_EXCHANGE_TITLE';end if;
 v_wanted:=app_private.exchange_asset(p_wanted_kind,p_wanted_id,p_wanted_quantity);
 if p_offer_kind not in ('collectible','bait','fuel') or p_wanted_kind<>'gold' or p_wanted_id<>'gold' then raise exception 'INVALID_EXCHANGE';end if;
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=v_uid for update;
 select * into l from public.exchange_listings where owner_id=v_uid and operation_id=p_operation_id;
 if found then
  if l.side<>p_side or l.offer<>v_offer or l.wanted<>v_wanted or coalesce(l.title,(l.offer->>'name')||' 판매합니다')<>v_title then raise exception 'OPERATION_CONFLICT';end if;
  return to_jsonb(l);
 end if;
 if (select count(*) from public.exchange_listings where owner_id=v_uid and status='active')>=10 then raise exception 'EXCHANGE_LISTING_LIMIT';end if;
 v_gift:=app_private.exchange_reserve(v_uid,v_offer);
 insert into public.exchange_listings(owner_id,owner_name,side,operation_id,offer,wanted,escrow_gift_id,title)
 values(v_uid,(select nickname from public.player_profiles where id=v_uid),p_side,p_operation_id,v_offer,v_wanted,v_gift,v_title) returning * into l;
 return to_jsonb(l);
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_post_bundle(p_items jsonb, p_price integer, p_operation_id uuid, p_title text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();part jsonb;asset jsonb;assets jsonb:='[]';v_offer jsonb;v_wanted jsonb;
 l public.exchange_listings;gifts uuid[]:='{}';v_title text;keys text[]:='{}';key text;collectibles integer:=0;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or jsonb_typeof(p_items) is distinct from 'array' then raise exception 'INVALID_EXCHANGE';end if;
 if jsonb_array_length(p_items) not between 1 and 10 then raise exception 'EXCHANGE_BUNDLE_LIMIT';end if;
 for part in select value from jsonb_array_elements(p_items) order by value->>'kind',value->>'id' loop
  if jsonb_typeof(part) is distinct from 'object' or coalesce(part->>'kind','') not in ('collectible','bait','fuel')
   or coalesce(part->>'id','')='' or coalesce(part->>'quantity','') !~ '^[1-9][0-9]{0,3}$' then raise exception 'INVALID_EXCHANGE_ASSET';end if;
  key:=(part->>'kind')||':'||(part->>'id');
  if key=any(keys) then raise exception 'INVALID_EXCHANGE_ASSET';end if;
  keys:=array_append(keys,key);
  asset:=app_private.exchange_asset(part->>'kind',part->>'id',(part->>'quantity')::integer);
  if asset->>'kind'='collectible' then collectibles:=collectibles+(asset->>'quantity')::integer;end if;
  assets:=assets||jsonb_build_array(asset);
 end loop;
 if collectibles>20 then raise exception 'EXCHANGE_BUNDLE_LIMIT';end if;
 v_wanted:=app_private.exchange_asset('gold','gold',p_price);
 -- Keep the legacy first-item shape for old clients; items is authoritative for bundles.
 v_offer:=assets->0;
 if jsonb_array_length(assets)>1 then
  v_offer:=v_offer||jsonb_build_object('items',assets,'name',(select string_agg(value->>'name',' + ') from jsonb_array_elements(assets)),
   'quantity',(select sum((value->>'quantity')::integer) from jsonb_array_elements(assets)));
 end if;
 v_title:=coalesce(nullif(btrim(p_title),''),case when jsonb_array_length(assets)>1 then '묶음 판매합니다' else (v_offer->>'name')||' 판매합니다' end);
 if char_length(v_title)>80 or v_title ~ '[[:cntrl:]]' then raise exception 'INVALID_EXCHANGE_TITLE';end if;
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=u for update;
 select * into l from public.exchange_listings where owner_id=u and operation_id=p_operation_id;
 if found then
  if l.side<>'sell' or l.offer<>v_offer or l.wanted<>v_wanted or l.title<>v_title then raise exception 'OPERATION_CONFLICT';end if;
  return to_jsonb(l);
 end if;
 if (select count(*) from public.exchange_listings where owner_id=u and status='active')>=10 then raise exception 'EXCHANGE_LISTING_LIMIT';end if;
 -- A failure on any item rolls back every earlier reservation in this call.
 for asset in select value from jsonb_array_elements(assets) loop
  gifts:=array_append(gifts,app_private.exchange_reserve(u,asset));
 end loop;
 insert into public.exchange_listings(owner_id,owner_name,side,operation_id,offer,wanted,escrow_gift_id,title)
 values(u,(select nickname from public.player_profiles where id=u),'sell',p_operation_id,v_offer,v_wanted,gifts[1],v_title) returning * into l;
 if cardinality(gifts)>1 then
  insert into app_private.exchange_bundle_gifts(listing_id,gift_id) select l.id,unnest(gifts);
 end if;
 return to_jsonb(l);
end $function$

CREATE OR REPLACE FUNCTION app_private.exchange_reserve(p_owner uuid, p_asset jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_kind text:=p_asset->>'kind';v_item text:=p_asset->>'id';v_qty integer:=(p_asset->>'quantity')::integer;
 v_ids uuid[]:='{}';v_gift uuid;v_name text;v_count integer;v_operation uuid:=gen_random_uuid();v_species jsonb;
begin
 select nickname into v_name from public.player_profiles where id=p_owner;
 if v_name is null then raise exception 'PROFILE_REQUIRED';end if;
 if v_kind='collectible' then
  select array_agg(id order by id) into v_ids from (
   select id from public.player_collectibles where user_id=p_owner and species_id=v_item
    and sold_at is null and escrow_gift_id is null and tank_id is null
   order by id limit v_qty for update
  ) q;
  if coalesce(cardinality(v_ids),0)<>v_qty then raise exception 'EXCHANGE_INSUFFICIENT_ITEMS';end if;
  v_species:=app_private.species_payload(v_item);
 elsif v_kind='gold' then
  update public.player_wallets set gold=gold-v_qty,updated_at=now() where user_id=p_owner and gold>=v_qty;
  if not found then raise exception 'INSUFFICIENT_GOLD';end if;
  v_species:=p_asset;
 elsif v_kind in ('bait','fuel') then
  select coalesce((inventory->>v_item)::integer,0) into v_count from public.player_wallets where user_id=p_owner;
  if coalesce(v_count,0)<v_qty then raise exception 'EXCHANGE_INSUFFICIENT_ITEMS';end if;
  update public.player_wallets set inventory=jsonb_set(inventory,array[v_item],to_jsonb(v_count-v_qty)),updated_at=now() where user_id=p_owner;
  v_species:=p_asset;
 else raise exception 'INVALID_EXCHANGE_ASSET';end if;
 insert into public.collectible_gifts(sender_id,recipient_id,sender_name,recipient_name,operation_id,collectible_ids,species,quantity,message,source,exchange_hold,reward_kind,reward_id)
 values(p_owner,p_owner,v_name,v_name,v_operation,v_ids,v_species,v_qty,'거래소에서 맡긴 물품이에요.','exchange',true,v_kind,v_item) returning id into v_gift;
 if v_kind='collectible' then
  update public.player_collectibles set escrow_gift_id=v_gift,position_x=null,position_y=null where id=any(v_ids);
 elsif v_kind='gold' then
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(p_owner,v_operation,'buy','exchange:reserve:'||v_gift,-v_qty);
 end if;
 return v_gift;
end $function$

CREATE OR REPLACE FUNCTION app_private.expand_aquarium_capacity(p_target_capacity integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w public.player_wallets;previous public.gold_transactions;current_capacity integer;price integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_target_capacity is null or p_target_capacity not in (70,100) then raise exception 'INVALID_CAPACITY';end if;
 perform app_private.get_gold_wallet();
 select * into strict w from public.player_wallets where user_id=u for update;
 select * into previous from public.gold_transactions where user_id=u and operation_id=p_operation_id;
 if found then
  if previous.action<>'buy' or previous.item_id is distinct from 'aquarium-capacity:'||p_target_capacity::text then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.aquarium_state();
 end if;
 select coalesce((select capacity from app_private.player_aquarium_capacity where user_id=u),50) into current_capacity;
 if current_capacity=100 then raise exception 'AQUARIUM_FULLY_EXPANDED';end if;
 if p_target_capacity<>(case current_capacity when 50 then 70 else 100 end) then raise exception 'CAPACITY_CHANGED';end if;
 price:=case current_capacity when 50 then 5000 else 10000 end;
 if w.gold<price then raise exception 'INSUFFICIENT_GOLD';end if;
 insert into app_private.player_aquarium_capacity(user_id,capacity) values(u,p_target_capacity)
  on conflict(user_id) do update set capacity=excluded.capacity;
 update public.player_wallets set gold=gold-price,updated_at=clock_timestamp() where user_id=u;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
  values(u,p_operation_id,'buy','aquarium-capacity:'||p_target_capacity::text,-price);
 return app_private.aquarium_state();
end $function$

CREATE OR REPLACE FUNCTION app_private.expedition_action(p_action text, p_operation_id uuid, p_vessel_id text DEFAULT NULL::text, p_region_id text DEFAULT NULL::text, p_cargo jsonb DEFAULT NULL::jsonb, p_expedition_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();r jsonb;c record;total integer:=0;minutes integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action='buy' then raise exception 'VESSEL_RETIRED';end if;
 if p_action='depart' then
  if p_vessel_id is distinct from 'dinghy' then raise exception 'VESSEL_RETIRED';end if;
  if p_cargo is null or jsonb_typeof(p_cargo)<>'object' then raise exception 'INVALID_CARGO';end if;
  for c in select value from jsonb_each_text(p_cargo) loop
   if c.value !~ '^[1-9][0-9]{0,2}$' then raise exception 'INVALID_CARGO';end if;
   total:=total+c.value::integer;
  end loop;
  if total<1 or total>30 then raise exception 'CARGO_LIMIT';end if;
 end if;
 r:=app_private.settle_legacy_expedition(p_action,p_operation_id,p_vessel_id,p_region_id,p_cargo,p_expedition_id);
 if p_action='depart' and not (r->>'replayed')::boolean then
  minutes:=total*app_private.trap_minutes_per_bait();
  update public.fishing_expeditions set returns_at=departed_at+make_interval(mins=>minutes),
   vessel_snapshot=jsonb_set(vessel_snapshot,'{duration_minutes}',to_jsonb(minutes))
   where id=(r->'receipt'->>'expeditionId')::uuid and user_id=u;
  r:=app_private.expedition_state()||jsonb_build_object('receipt',r->'receipt','replayed',false);
 end if;
 return r;
end $function$

CREATE OR REPLACE FUNCTION app_private.expedition_pick(p_region text, p_bait text, p_native boolean, p_local_discovery boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.fishing_baits;r public.game_rarity;roll integer:=floor(random()*10000);ids text[];fallback boolean;
begin
 select * into strict b from public.fishing_baits where id=p_bait;
 r:=case when b.alternating then app_private.consume_bait_cycle()
 when roll<b.mythic_bp then 'mythic'::public.game_rarity when roll<b.mythic_bp+b.epic_bp then 'epic'::public.game_rarity
 when roll<b.mythic_bp+b.epic_bp+b.rare_bp then 'rare'::public.game_rarity else 'common'::public.game_rarity end;
 if p_bait in ('bait_snowflake_salt','bait_shooting_star_tail') then return app_private.pick_balanced_bait_collectible(p_region,r,p_bait,p_native,false);end if;
 if b.fish_only then return app_private.pick_bait_fish(p_region,r,p_native,false);end if;
 with candidates as materialized (
 select s.id,s.rarity from public.collectible_species s where case
 when p_bait='bait_first_greeting' then s.kind in ('fish','trash','decoration') and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
 and (not p_local_discovery or exists(select 1 from public.collectible_habitats h where h.species_id=s.id and h.region_id=p_region))
 when p_bait='bait_grubby_magnet' then s.kind='trash'
 when b.effect_kind='decoration' then s.kind='decoration' and s.rarity=r else s.kind in ('fish','trash') and s.rarity=r end
 ),pool as(select * from candidates c where c.rarity=r or not exists(select 1 from candidates c2 where c2.rarity=r))
 select array_agg(id order by id),not coalesce(bool_or(rarity=r),false) into ids,fallback from pool;
 return app_private.pick_habitat_group(ids,p_region,null,(case when p_native then 1.5 else 1 end)*(case when p_bait='bait_sea_memory' then 3 else 1 end),fallback and b.effect_kind<>'decoration');
end $function$

CREATE OR REPLACE FUNCTION app_private.experience_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();xp bigint:=0;legacy bigint:=0;adjustment bigint:=0;lv integer;base numeric;needed bigint;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 select e.total_xp,e.legacy_xp,e.curve_offset into xp,legacy,adjustment from app_private.player_experience e where e.user_id=uid;
 xp:=coalesce(xp,0);legacy:=coalesce(legacy,0);adjustment:=coalesce(adjustment,0);
 lv:=app_private.experience_level(xp::numeric+adjustment);
 base:=20::numeric*(lv-1)*(2*lv+1);needed:=100+80::bigint*(lv-1);
 -- totalXp is actual earned XP, so the conversion never appears as a fresh XP gain in clients.
 return jsonb_build_object('level',lv,'totalXp',xp,'currentXp',xp::numeric+adjustment-base,'nextLevelXp',needed,'legacyXp',legacy);
end $function$

CREATE OR REPLACE FUNCTION app_private.feed_friend_aquarium(p_tank uuid, p_operation uuid, p_step integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_owner uuid;v_tank_name text;f public.aquarium_feedings;v_replayed boolean:=false;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_tank is null or p_operation is null or p_step is null or p_step not between 1 and 3 then raise exception 'INVALID_FEEDING';end if;
 select user_id,name into v_owner,v_tank_name from public.aquarium_tanks where id=p_tank for share;
 if not found then raise exception 'TANK_NOT_FOUND';end if;
 perform app_private.require_aquarium_friend(v_owner);
 if p_step=1 then
  insert into public.aquarium_feedings(visitor_id,owner_id,tank_id,operation_id,clicks)
  values(v_uid,v_owner,p_tank,p_operation,1) on conflict(visitor_id,operation_id) do nothing;
  v_replayed:=not found;
 end if;
 select * into f from public.aquarium_feedings where visitor_id=v_uid and operation_id=p_operation for update;
 if not found then raise exception 'FEEDING_STEP_REQUIRED';end if;
 if f.tank_id is distinct from p_tank or f.owner_id<>v_owner then raise exception 'OPERATION_CONFLICT';end if;
 if p_step>f.clicks+1 then raise exception 'FEEDING_STEP_REQUIRED';end if;
 if p_step<=f.clicks then
  if p_step<>1 then v_replayed:=true;end if;
 else
  update public.aquarium_feedings set clicks=p_step,completed_at=case when p_step=3 then transaction_timestamp() end
  where id=f.id returning * into f;
  if p_step=3 then
   insert into app_private.aquarium_feed_notices(visitor_id,owner_id,notice_day)
   values(v_uid,v_owner,(transaction_timestamp() at time zone 'Asia/Seoul')::date) on conflict do nothing;
   if found then
    insert into public.notifications(recipient_id,actor_id,category,kind,title,body)
    values(v_owner,v_uid,'general','system','친구가 먹이를 줬어요',
    (select nickname from public.player_profiles where id=v_uid)||'님이 '||v_tank_name||'에 먹이를 줬어요.');
   end if;
  end if;
 end if;
 return jsonb_build_object('id',f.id,'clicks',f.clicks,'completed',f.completed_at is not null,'replayed',v_replayed);
end $function$

CREATE OR REPLACE FUNCTION app_private.feedback_authors(p_kind text, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); result jsonb;
begin
 if actor is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_ids is null or cardinality(p_ids)>20 then raise exception 'INVALID_FEEDBACK_IDS'; end if;
 if p_kind='suggestion' then
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'avatar_path',a.avatar_path)),'[]'::jsonb) into result
  from public.suggestion_posts p left join public.player_profiles a on a.id=p.author_id
  where p.id=any(p_ids) and (
   not p.friends_only or p.author_id=actor or (select app_private.notice_is_operator()) or exists(
    select 1 from public.friend_requests f where f.status='accepted' and
    ((f.sender_id=actor and f.recipient_id=p.author_id) or (f.recipient_id=actor and f.sender_id=p.author_id))
   )
  );
 elsif p_kind='bug' then
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'avatar_path',a.avatar_path)),'[]'::jsonb) into result
  from public.bug_reports p left join public.player_profiles a on a.id=p.author_id where p.id=any(p_ids);
 else raise exception 'INVALID_FEEDBACK_KIND'; end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.feedback_comment_action(p_kind text, p_id uuid, p_action text, p_comment_id uuid, p_body text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();c public.feedback_comments;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_comment_id is null or p_action is null or p_action not in ('add','edit','delete') then raise exception 'INVALID_FEEDBACK_COMMENT';end if;
 -- Lock the parent against concurrent deletion or visibility changes.
 if p_kind='suggestion' then perform 1 from public.suggestion_posts where id=p_id for share;
 elsif p_kind='bug' then perform 1 from public.bug_reports where id=p_id for share;
 else raise exception 'INVALID_FEEDBACK_COMMENT';end if;
 if not app_private.feedback_can_read(p_kind,p_id) then raise exception 'FEEDBACK_NOT_FOUND';end if;
 perform pg_advisory_xact_lock(hashtextextended('feedback-comment:'||p_comment_id::text,0));
 select * into c from public.feedback_comments where id=p_comment_id for update;
 if found then
  if (p_kind='suggestion' and c.suggestion_id is distinct from p_id) or (p_kind='bug' and c.bug_id is distinct from p_id) then raise exception 'FEEDBACK_COMMENT_FORBIDDEN';end if;
  if c.author_id<>u and not (p_action='delete' and app_private.notice_is_operator()) then raise exception 'FEEDBACK_COMMENT_FORBIDDEN';end if;
  if p_action='add' then
   if c.body is distinct from btrim(p_body) then raise exception 'OPERATION_CONFLICT';end if;
   return c.id;
  end if;
 elsif p_action='delete' then return p_comment_id;
 elsif p_action<>'add' then raise exception 'FEEDBACK_COMMENT_NOT_FOUND';
 end if;
 if p_action='delete' then delete from public.feedback_comments where id=p_comment_id;return p_comment_id;end if;
 if p_body is null or char_length(btrim(p_body)) not between 1 and 500 then raise exception 'INVALID_FEEDBACK_COMMENT';end if;
 if p_action='add' then
  insert into public.feedback_comments(id,suggestion_id,bug_id,author_id,body)
  values(p_comment_id,case when p_kind='suggestion' then p_id end,case when p_kind='bug' then p_id end,u,btrim(p_body));
 else update public.feedback_comments set body=btrim(p_body),updated_at=now() where id=p_comment_id;end if;
 return p_comment_id;
end $function$

CREATE OR REPLACE FUNCTION app_private.feedback_comments(p_kind text, p_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;total bigint;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'INVALID_FEEDBACK_COMMENT';end if;
 if not app_private.feedback_can_read(p_kind,p_id) then raise exception 'FEEDBACK_NOT_FOUND';end if;
 select count(*) into total from public.feedback_comments c where case p_kind when 'suggestion' then c.suggestion_id=p_id else c.bug_id=p_id end;
 select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at,t.id),'[]'::jsonb) into result from (
  select c.id,c.author_id,coalesce(p.nickname,'낚시꾼') author_name,p.avatar_path,c.body,c.created_at,c.updated_at
  from public.feedback_comments c left join public.player_profiles p on p.id=c.author_id
  where case p_kind when 'suggestion' then c.suggestion_id=p_id else c.bug_id=p_id end
  order by c.created_at,c.id limit 20 offset p_offset
 ) t;
 return jsonb_build_object('items',result,'total',total);
end $function$

CREATE OR REPLACE FUNCTION app_private.finish_fishing(p_operation_id uuid, p_won boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();p app_private.prepared_fishing_casts;a public.fishing_attempts;
 v_item uuid;v_success boolean;v_result jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_won is null then raise exception 'INVALID_RESULT';end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||v_uid::text,0));
 select * into p from app_private.prepared_fishing_casts where user_id=v_uid and operation_id=p_operation_id for update;
 if not found then raise exception 'CAST_NOT_FOUND';end if;
 if p.finished_at is not null then return p.result||jsonb_build_object('replayed',true);end if;
 if p_won and p.confirm_bite and p.fight_started_at is null then raise exception 'CAST_NOT_STARTED';end if;
 if p_won and clock_timestamp()<(case when p.fight_started_at is null
  then p.created_at+make_interval(secs=>p.wait_seconds::double precision+3)
  else p.fight_started_at+interval '3 seconds' end) then raise exception 'CAST_TOO_EARLY';end if;
 v_success:=p_won and p.eligible and clock_timestamp()<=p.expires_at;
 if v_success then
  if p.map_piece_number is not null then
   insert into app_private.player_fishing_map_pieces(user_id,region_id,piece_number) values(v_uid,p.map_region_id,p.map_piece_number) on conflict do nothing;
   if not exists(select 1 from public.fishing_map_blueprints b cross join lateral generate_series(1,b.piece_count) n(piece_number) where b.region_id=p.map_region_id and not exists(select 1 from app_private.player_fishing_map_pieces f where f.user_id=v_uid and f.region_id=b.region_id and f.piece_number=n.piece_number)) then
    insert into public.player_map_fragments(user_id,region_id) values(v_uid,p.map_region_id) on conflict do nothing;
   end if;
  else
  if p.map_region_id is not null then
   insert into public.player_map_fragments(user_id,region_id) values(v_uid,p.map_region_id) on conflict do nothing;
  end if;
  insert into public.player_collectibles(user_id,species_id,map_region_id) values(v_uid,p.species_id,p.map_region_id) returning id into v_item;
  insert into public.player_discoveries(user_id,species_id) values(v_uid,p.species_id) on conflict do nothing;
 end if;
 end if;
 insert into public.fishing_attempts(user_id,operation_id,region_id,bait_id,rarity,collectible_id)
 values(v_uid,p.operation_id,p.region_id,p.bait_id,case when v_success then p.rarity end,v_item) returning * into a;
 v_result:=jsonb_build_object('attempt',to_jsonb(a)||jsonb_build_object('species',case when v_success then p.snapshot end,'firstDiscovery',coalesce((select evidence.first_discovery from app_private.title_acquisition_evidence evidence where evidence.collectible_id=v_item and evidence.user_id=v_uid),false)),
 'replayed',false,'failure_reason',case when v_success then null when clock_timestamp()>p.expires_at then 'expired' when not p.eligible then p.failure_reason else 'minigame' end);
 update app_private.prepared_fishing_casts set finished_at=clock_timestamp(),result=v_result where user_id=v_uid and operation_id=p_operation_id;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION app_private.finish_web_push(p_id bigint, p_lease_token uuid, p_status integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q app_private.push_deliveries;
begin
 select * into q from app_private.push_deliveries where id=p_id and lease_token=p_lease_token and status='sending' for update;
 if not found then return;end if;
 if p_status in (404,410) then delete from app_private.push_subscriptions where id=q.subscription_id;return;end if;
 update app_private.push_deliveries set last_status=p_status,lease_token=null,locked_until=null,
  status=case when p_status between 200 and 299 then 'sent' when p_status in (400,401,403,413) or attempts>=5 then 'failed' else 'pending' end,
  finished_at=case when p_status between 200 and 299 or p_status in (400,401,403,413) or attempts>=5 then clock_timestamp() else null end,
  available_at=clock_timestamp()+make_interval(secs=>least(3600,30*power(2,attempts)::integer)) where id=q.id;
end $function$

