 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_table_schema <> 'app_private' then raise exception 'INVALID_HELP_SOURCE'; end if;
 if tg_table_name = 'expedition_boosts' then
  perform app_private.award_experience(new.helper_id,'friend_lure',new.id,1);
 elsif tg_table_name in ('aquarium_feed_notices','aquarium_clean_notices') then
  perform app_private.award_experience(new.visitor_id,
   case when tg_table_name='aquarium_feed_notices' then 'friend_feeding' else 'friend_cleaning' end,
   pg_catalog.md5(new.visitor_id::text || ':' || new.owner_id::text || ':' || new.notice_day::text)::uuid,1);
 else raise exception 'INVALID_HELP_SOURCE';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.friend_levels()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();result jsonb;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 with friends as (
  select distinct case when sender_id=uid then recipient_id else sender_id end friend_id
  from public.friend_requests where status='accepted' and (sender_id=uid or recipient_id=uid)
 )
 select coalesce(jsonb_agg(jsonb_build_object('friendId',f.friend_id,'level',app_private.player_level(f.friend_id)) order by f.friend_id),'[]'::jsonb)
 into result from friends f left join app_private.player_experience e on e.user_id=f.friend_id;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.friend_presence_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();v_now timestamptz:=clock_timestamp();result jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('friend_id',f.friend_id,'state',coalesce(p.state,'offline')) order by f.friend_id),'[]'::jsonb)
 into result
 from (
  select recipient_id friend_id from public.friend_requests where sender_id=u and status='accepted'
  union
  select sender_id from public.friend_requests where recipient_id=u and status='accepted'
 ) f
 left join lateral (
  select case when bool_or(s.state='online') then 'online' when bool_or(s.state='away') then 'away' else 'offline' end state
  from app_private.player_presence_sessions s
  where s.user_id=f.friend_id and s.last_seen_at>v_now-interval '90 seconds'
 ) p on true;
 return jsonb_build_object('serverNow',v_now,'friends',result);
end $function$

