CREATE OR REPLACE FUNCTION app_private.gift_detail(p_gift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g public.collectible_gifts;v_uid uuid:=auth.uid();v_offers jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 select * into g from public.collectible_gifts where id=p_gift_id and not exchange_hold and (sender_id=v_uid or recipient_id=v_uid);
 if not found then raise exception 'GIFT_NOT_FOUND';end if;
 if g.source='exchange' and g.reward_kind='gold' then
  -- Payment creation and listing closure share the transaction's now(). Check
  -- both participants and the exact amount, and never guess ambiguous matches.
  select jsonb_agg(l.offer) into v_offers from public.exchange_listings l
  where l.side='sell' and l.status='completed'
   and l.owner_id=g.recipient_id and l.taker_id=g.sender_id and l.closed_at=g.created_at
   and l.wanted->>'kind'='gold' and l.wanted->>'id'=g.reward_id
   and (l.wanted->>'quantity')::integer=g.quantity;
  if jsonb_array_length(v_offers)=1 then
   g.species:=g.species||jsonb_build_object('exchange_offer',v_offers->0);
  end if;
 end if;
 return to_jsonb(g);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.gift_mailbox(p_direction text DEFAULT 'received'::text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_total integer;v_items jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_direction is null or p_direction not in ('received','sent') or p_offset is null or p_offset<0 then raise exception 'INVALID_GIFT';end if;
 select count(*) into v_total from public.collectible_gifts where not exchange_hold and ((p_direction='received' and recipient_id=v_uid) or(p_direction='sent' and sender_id=v_uid));
 select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc,q.id),'[]') into v_items from(
  select * from public.collectible_gifts where not exchange_hold and ((p_direction='received' and recipient_id=v_uid) or(p_direction='sent' and sender_id=v_uid)) order by created_at desc,id limit 30 offset p_offset
 ) q;
 return jsonb_build_object('items',v_items,'total',v_total);
end $function$

CREATE OR REPLACE FUNCTION app_private.giseong_catch_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.collectible_id is not null and new.rarity is not null then
  perform app_private.grant_giseong_catch_reward(new.user_id,new.operation_id,clock_timestamp());
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.giseong_settled_capture_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item jsonb;v_species_id text;
begin
 if old.claimed_at is not null or new.claimed_at is null
  or jsonb_typeof(new.result->'items') is distinct from 'array' then return new;end if;
 for v_item in select value from jsonb_array_elements(new.result->'items') loop
  select c.species_id into v_species_id from public.player_collectibles c
  where c.user_id=new.user_id and c.id=case
   when v_item->>'id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   then (v_item->>'id')::uuid else null end;
  if found then
   perform app_private.grant_giseong_capture_reward(new.user_id,v_species_id,new.claimed_at,clock_timestamp());
  end if;
 end loop;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.grant_giseong_capture_reward(p_user_id uuid, p_species_id text, p_captured_at timestamp with time zone, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.notices;v_species_name text;v_recipient_name text;v_gift uuid;
begin
 if p_species_id is null or p_species_id not in ('giseong-fish','giseong-webfoot-octopus') then return null;end if;
 select * into v_event from public.notices
 where id='a87b4c3e-cdbc-494e-b1d2-ca3810ba749d' and category='event' and status='published';
 if not found or p_now is null or p_captured_at is null
  or v_event.starts_at is null or v_event.ends_at is null
  or p_now<v_event.starts_at or p_captured_at<v_event.starts_at
  or p_now>=least(v_event.ends_at,timestamptz '2026-11-01 00:00:00+09')
  or p_captured_at>=least(v_event.ends_at,timestamptz '2026-11-01 00:00:00+09')
  or p_captured_at>p_now then return null;end if;
 select s.name,p.nickname into v_species_name,v_recipient_name
 from public.collectible_species s cross join public.player_profiles p
 where s.id=p_species_id and p.id=p_user_id;
 if not found then return null;end if;
 insert into public.collectible_gifts(sender_name,recipient_id,recipient_name,operation_id,collectible_ids,
  species,quantity,message,source,reward_kind,reward_id)
 values('퐁당섬 운영자',p_user_id,v_recipient_name,gen_random_uuid(),'{}'::uuid[],
  jsonb_build_object('id','giseong-catch-202610:'||p_species_id,'name',v_species_name||' 포획 보상'),300,
  v_species_name||' 포획 성공! 이벤트 보상 300골드예요. 낚시·통발·어선 포획을 인정하며, 종류별 보상은 계정당 한 번씩 받을 수 있어요.',
  'system','gold','giseong-catch-202610:'||p_species_id)
 on conflict do nothing returning id into v_gift;
 if v_gift is not null then
  insert into public.notifications(recipient_id,category,kind,title,body,gift_id)
  values(p_user_id,'gift','gift_received','기성 포획 이벤트 보상 도착!',
   v_species_name||'를 잡았어요! 선물함에서 300골드를 받아주세요.',v_gift);
 end if;
 return v_gift;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.grant_giseong_catch_reward(p_user_id uuid, p_operation_id uuid, p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_species_id text;v_captured_at timestamptz;
begin
 select c.species_id,a.created_at into v_species_id,v_captured_at
 from public.fishing_attempts a
 join public.player_collectibles c on c.id=a.collectible_id and c.user_id=a.user_id
 where a.user_id=p_user_id and a.operation_id=p_operation_id and a.rarity is not null;
 if not found then return null;end if;
 return app_private.grant_giseong_capture_reward(p_user_id,v_species_id,v_captured_at,p_now);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.grant_special_bait_reward(p_recipient uuid, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_inventory jsonb;v_reward jsonb:='{}';v_bait text;v_i integer;
 v_baits text[]:=array['bait_safe','bait_special','bait_epic','bait_magnet','bait_forbidden_star','bait_grubby_magnet','bait_sea_memory','bait_first_greeting'];
begin
 if auth.uid() is null or not app_private.notice_is_operator() then raise exception 'NOT_ALLOWED';end if;
 if p_quantity is null or p_quantity not between 1 and 2 then raise exception 'INVALID_REWARD';end if;
 if (select count(*) from public.fishing_baits where id=any(v_baits))<>cardinality(v_baits) then raise exception 'REWARD_UNAVAILABLE';end if;
 insert into public.player_wallets(user_id) values(p_recipient) on conflict do nothing;
 select inventory into v_inventory from public.player_wallets where user_id=p_recipient for update;
 for v_i in 1..p_quantity loop
  v_bait:=v_baits[1+floor(random()*cardinality(v_baits))::integer];
  v_reward:=jsonb_set(v_reward,array[v_bait],to_jsonb(coalesce((v_reward->>v_bait)::integer,0)+1));
  v_inventory:=jsonb_set(v_inventory,array[v_bait],to_jsonb(coalesce((v_inventory->>v_bait)::integer,0)+1));
 end loop;
 update public.player_wallets set inventory=v_inventory,updated_at=now() where user_id=p_recipient;
 return v_reward;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.hall_action(p_target uuid, p_action text, p_value integer DEFAULT 0, p_body text DEFAULT ''::text, p_comment_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_target is null or not exists(select 1 from public.player_profiles where id=p_target) then raise exception 'HALL_NOT_FOUND';end if;
 perform pg_advisory_xact_lock(hashtextextended('hall:'||u::text,0));
 if p_action='react' then
  if p_target=u then raise exception 'HALL_SELF_REACTION';end if;
  if p_value is null or p_value not in (-1,0,1) then raise exception 'INVALID_HALL';end if;
  if p_value=0 then delete from app_private.hall_reactions where target_id=p_target and user_id=u;
  else insert into app_private.hall_reactions(target_id,user_id,value) values(p_target,u,p_value)
   on conflict(target_id,user_id) do update set value=excluded.value;end if;
 elsif p_action='comment' then
  if p_body is null or char_length(btrim(p_body)) not between 1 and 500 then raise exception 'INVALID_HALL';end if;
  if exists(select 1 from app_private.hall_comments where author_id=u and created_at>clock_timestamp()-interval '5 seconds') then raise exception 'HALL_RATE_LIMIT';end if;
  insert into app_private.hall_comments(target_id,author_id,body) values(p_target,u,btrim(p_body));
 elsif p_action='delete_comment' then
  delete from app_private.hall_comments where id=p_comment_id and target_id=p_target and author_id=u;
  if not found then raise exception 'NOT_ALLOWED';end if;
 else raise exception 'INVALID_HALL';end if;
 return app_private.hall_wall(p_target,0);
end $function$

CREATE OR REPLACE FUNCTION app_private.hall_section_action(p_section text, p_action text, p_body text DEFAULT ''::text, p_comment_id uuid DEFAULT NULL::uuid, p_value integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();author uuid;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_section is null or not exists(select 1 from app_private.hall_sections where id=p_section) then raise exception 'HALL_NOT_FOUND';end if;
 perform pg_advisory_xact_lock(hashtextextended('hall-section:'||u::text,0));
 if p_action='comment' then
  if p_body is null or char_length(btrim(p_body)) not between 1 and 500 then raise exception 'INVALID_HALL';end if;
  if exists(select 1 from app_private.hall_section_comments where author_id=u and created_at>clock_timestamp()-interval '5 seconds') then raise exception 'HALL_RATE_LIMIT';end if;
  insert into app_private.hall_section_comments(section_id,author_id,body) values(p_section,u,btrim(p_body));
 elsif p_action='delete_comment' then
  delete from app_private.hall_section_comments where id=p_comment_id and section_id=p_section and author_id=u;
  if not found then raise exception 'NOT_ALLOWED';end if;
 elsif p_action='react' then
  if p_value is null or p_value not in (-1,0,1,2,3) then raise exception 'INVALID_HALL';end if;
  select c.author_id into author from app_private.hall_section_comments c where c.id=p_comment_id and c.section_id=p_section for update;
  if not found then raise exception 'HALL_NOT_FOUND';end if;
  if author=u then raise exception 'HALL_SELF_REACTION';end if;
  if p_value=0 then delete from app_private.hall_section_comment_reactions where comment_id=p_comment_id and user_id=u;
  else insert into app_private.hall_section_comment_reactions(comment_id,user_id,value) values(p_comment_id,u,p_value)
   on conflict(comment_id,user_id) do update set value=excluded.value;end if;
 else raise exception 'INVALID_HALL';end if;
 return app_private.hall_section_wall(p_section,0);
end $function$

CREATE OR REPLACE FUNCTION app_private.hall_section_counts()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 select jsonb_object_agg(s.id,coalesce(c.n,0)) into result from app_private.hall_sections s
 left join (select section_id,count(*) n from app_private.hall_section_comments group by section_id) c on c.section_id=s.id;
 return coalesce(result,'{}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION app_private.hall_section_wall(p_section text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'INVALID_HALL';end if;
 if p_section is null or not exists(select 1 from app_private.hall_sections where id=p_section) then raise exception 'HALL_NOT_FOUND';end if;
 select jsonb_build_object(
  'total',(select count(*) from app_private.hall_section_comments where section_id=p_section),
  'comments',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc,c.id desc) from (
   select c.id,c.author_id,c.body,c.created_at,p.nickname,p.avatar_path,
    (select count(*) from app_private.hall_section_comment_reactions r where r.comment_id=c.id and r.value=2) sad,
    (select count(*) from app_private.hall_section_comment_reactions r where r.comment_id=c.id and r.value=3) angry,
    (select count(*) from app_private.hall_section_comment_reactions r where r.comment_id=c.id and r.value=1) likes,
    (select count(*) from app_private.hall_section_comment_reactions r where r.comment_id=c.id and r.value=-1) dislikes,
    coalesce((select r.value from app_private.hall_section_comment_reactions r where r.comment_id=c.id and r.user_id=auth.uid()),0) as "myReaction"
   from app_private.hall_section_comments c join public.player_profiles p on p.id=c.author_id
   where c.section_id=p_section order by c.created_at desc,c.id desc limit 30 offset p_offset
  ) c),'[]'::jsonb)
 ) into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.hall_wall(p_target uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'INVALID_HALL';end if;
 if not exists(select 1 from public.player_profiles where id=p_target) then raise exception 'HALL_NOT_FOUND';end if;
 select jsonb_build_object(
  'likes',(select count(*) from app_private.hall_reactions where target_id=p_target and value=1),
  'dislikes',(select count(*) from app_private.hall_reactions where target_id=p_target and value=-1),
  'myReaction',coalesce((select value from app_private.hall_reactions where target_id=p_target and user_id=auth.uid()),0),
  'total',(select count(*) from app_private.hall_comments where target_id=p_target),
  'comments',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc,c.id desc) from (
   select c.id,c.author_id,c.body,c.created_at,p.nickname,p.avatar_path from app_private.hall_comments c
   join public.player_profiles p on p.id=c.author_id where target_id=p_target
   order by c.created_at desc,c.id desc limit 30 offset p_offset
  ) c),'[]'::jsonb)
 ) into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.harbor_action(p_action text, p_operation_id uuid, p_vessel_id text DEFAULT NULL::text, p_voyage_id uuid DEFAULT NULL::uuid, p_quantity integer DEFAULT 1, p_boat_id uuid DEFAULT NULL::uuid, p_slot integer DEFAULT NULL::integer, p_region_id text DEFAULT 'pongdang'::text, p_secondary_region_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();v public.harbor_vessels;b public.harbor_boats;occupant public.harbor_boats;w public.player_wallets;trip public.harbor_voyages;
 prev app_private.harbor_operations;sig jsonb;receipt jsonb;n integer;slot integer;fuel integer;capacity integer;expansion_price integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('buy','depart','dock','store','sell','fuel','arrive','claim','claim_all','expand') then raise exception 'INVALID_HARBOR_ACTION';end if;
 if p_action in ('fuel','arrive','claim','claim_all') then return app_private.settle_legacy_harbor(p_action,p_operation_id,p_vessel_id,p_voyage_id,p_quantity);end if;
 sig:=jsonb_build_object('action',p_action,'vessel',p_vessel_id,'voyage',p_voyage_id,'quantity',p_quantity);
 if p_boat_id is not null or p_slot is not null then sig:=sig||jsonb_build_object('boat',p_boat_id,'slot',p_slot);end if;
 if p_action='depart' and p_region_id is distinct from 'pongdang' then sig:=sig||jsonb_build_object('region',p_region_id);end if;
 if p_secondary_region_id is not null then sig:=sig||jsonb_build_object('secondaryRegion',p_secondary_region_id);end if;
 perform pg_advisory_xact_lock(hashtextextended('harbor:'||u::text,0));
 select * into prev from app_private.harbor_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.harbor_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 perform app_private.get_gold_wallet();select * into w from public.player_wallets where user_id=u for update;
 select coalesce((select dock_slots from app_private.player_harbor_capacity where user_id=u),2) into capacity;
 if p_action='expand' then
  if capacity>=4 then raise exception 'HARBOR_FULLY_EXPANDED';end if;
  if p_slot is distinct from capacity+1 then raise exception 'HARBOR_EXPANSION_CHANGED';end if;
  expansion_price:=case capacity when 2 then 10000 else 30000 end;
  if w.gold<expansion_price then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into app_private.player_harbor_capacity(user_id,dock_slots) values(u,capacity+1)
   on conflict(user_id) do update set dock_slots=excluded.dock_slots;
  update public.player_wallets set gold=gold-expansion_price,updated_at=now() where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
   values(u,p_operation_id,'buy','harbor-dock:'||(capacity+1)::text,-expansion_price);
  receipt:=jsonb_build_object('action','expand','dockSlots',capacity+1,'gold',expansion_price);
 elsif p_action='buy' then
  select * into v from public.harbor_vessels where id=p_vessel_id;
  if not found then raise exception 'VESSEL_NOT_FOUND';end if;
  select count(*) into n from public.harbor_boats where user_id=u and vessel_id=v.id and sold_at is null;
  if w.gold<v.price then raise exception 'INSUFFICIENT_GOLD';end if;
  select s into slot from generate_series(1,capacity) s where not exists(select 1 from public.harbor_boats where user_id=u and dock_slot=s) order by s limit 1;
  insert into public.harbor_boats(user_id,vessel_id,instance_no,dock_slot) values(u,v.id,(select s from generate_series(1,n+1) s where not exists(select 1 from public.harbor_boats hb where hb.user_id=u and hb.vessel_id=v.id and hb.instance_no=s and hb.sold_at is null) order by s limit 1),slot) returning * into b;
  insert into public.player_harbor_vessels(user_id,vessel_id) values(u,v.id) on conflict do nothing;
  update public.player_wallets set gold=gold-v.price,updated_at=now() where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','harbor-vessel:'||v.id,-v.price);
  receipt:=jsonb_build_object('action','buy','vesselId',v.id,'boatId',b.id);
 else
  if p_boat_id is not null then select * into b from public.harbor_boats where id=p_boat_id and user_id=u and sold_at is null;
  elsif p_action='depart' then
   select * into b from public.harbor_boats b0 where b0.user_id=u and b0.vessel_id=p_vessel_id and b0.dock_slot is not null
    order by exists(select 1 from public.harbor_voyages t where t.boat_id=b0.id and t.claimed_at is null),b0.dock_slot limit 1;
  end if;
  if b.id is null then raise exception 'VESSEL_NOT_OWNED';end if;
  if p_vessel_id is not null and p_vessel_id<>b.vessel_id then raise exception 'INVALID_BOAT';end if;
  if exists(select 1 from public.harbor_voyages where boat_id=b.id and claimed_at is null) then raise exception 'VOYAGE_ACTIVE';end if;
  if p_action='sell' then
   select * into strict v from public.harbor_vessels where id=b.vessel_id;
   n:=v.price/2;
   if w.gold::bigint+n>1000000000 then raise exception 'GOLD_LIMIT';end if;
   update public.harbor_boats set sold_at=clock_timestamp(),dock_slot=null where id=b.id;
   update public.player_wallets set gold=gold+n,updated_at=now() where user_id=u;
   insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'sell','harbor-boat:'||b.id,n);
   receipt:=jsonb_build_object('action','sell','vesselId',v.id,'boatId',b.id,'gold',n);
  elsif p_action='dock' then
   if p_slot is null or p_slot not between 1 and capacity then raise exception 'INVALID_DOCK_SLOT';end if;
   if b.dock_slot is not null and b.dock_slot<>p_slot then raise exception 'BOAT_ALREADY_DOCKED';end if;
   select * into occupant from public.harbor_boats where user_id=u and dock_slot=p_slot and id<>b.id;
   if occupant.id is not null then
    if exists(select 1 from public.harbor_voyages where boat_id=occupant.id and claimed_at is null) then raise exception 'DOCK_RESERVED';end if;
    update public.harbor_boats set dock_slot=null where id=occupant.id;
   end if;
   update public.harbor_boats set dock_slot=p_slot where id=b.id;
   receipt:=jsonb_build_object('action','dock','boatId',b.id,'slot',p_slot);
  elsif p_action='store' then
   update public.harbor_boats set dock_slot=null where id=b.id;
   receipt:=jsonb_build_object('action','store','boatId',b.id);
  else
   if not exists(select 1 from public.regions where id=p_region_id) then raise exception 'REGION_NOT_FOUND';end if;
   if exists(select 1 from public.regions r where r.id=p_region_id and r.requires_map_fragment
    and not exists(select 1 from public.player_map_fragments m where m.user_id=u and m.region_id=r.id)) then raise exception 'REGION_LOCKED';end if;
   if b.dock_slot is null or b.dock_slot>capacity then raise exception 'DOCK_REQUIRED';end if;
   select * into strict v from public.harbor_vessels where id=b.vessel_id;
   if coalesce((v.catch_rule->>'region_count')::integer,1)=2 then
    if p_secondary_region_id is null or p_secondary_region_id=p_region_id then raise exception 'SECOND_REGION_REQUIRED';end if;
    if not exists(select 1 from public.regions where id=p_secondary_region_id) then raise exception 'REGION_NOT_FOUND';end if;
    if exists(select 1 from public.regions r where r.id=p_secondary_region_id and r.requires_map_fragment
     and not exists(select 1 from public.player_map_fragments m where m.user_id=u and m.region_id=r.id)) then raise exception 'REGION_LOCKED';end if;
   elsif p_secondary_region_id is not null then raise exception 'SECOND_REGION_NOT_ALLOWED';end if;
   fuel:=coalesce((w.inventory->>'fuel')::integer,0);
   if fuel<v.fuel_cost then raise exception 'INSUFFICIENT_FUEL';end if;
   update public.player_wallets set inventory=jsonb_set(inventory,'{fuel}',to_jsonb(fuel-v.fuel_cost)),updated_at=now() where user_id=u;
   insert into public.harbor_voyages(user_id,vessel_id,boat_id,region_id,vessel_snapshot,returns_at) values(u,v.id,b.id,p_region_id,to_jsonb(v)||case when p_secondary_region_id is not null then jsonb_build_object('secondary_region_id',p_secondary_region_id,'secondary_region_name',(select name from public.regions where id=p_secondary_region_id)) else '{}'::jsonb end||jsonb_build_object('fishing_count',v.fishing_count+floor(random()*(coalesce(v.fishing_count_max,v.fishing_count)-v.fishing_count+1))::integer),clock_timestamp()+make_interval(mins=>v.duration_minutes)) returning * into trip;
   receipt:=jsonb_build_object('action','depart','voyageId',trip.id,'vesselId',v.id,'boatId',b.id);
  end if;
 end if;
 insert into app_private.harbor_operations(user_id,operation_id,signature,receipt) values(u,p_operation_id,sig,receipt);
 return app_private.harbor_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.harbor_draw(p_region text, p_rule jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.game_rarity;roll integer;v_kind text:=p_rule->>'kind';wanted text;ids text[];
 fallback boolean:=false;sid text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if random()*10000>=(p_rule->>'success_bp')::integer then return null;end if;
 roll:=floor(random()*10000)::integer;
 r:=case when roll<(p_rule->>'mythic_bp')::integer then 'mythic'::public.game_rarity
  when roll<(p_rule->>'mythic_bp')::integer+(p_rule->>'epic_bp')::integer then 'epic'::public.game_rarity
  when roll<(p_rule->>'mythic_bp')::integer+(p_rule->>'epic_bp')::integer+(p_rule->>'rare_bp')::integer then 'rare'::public.game_rarity
  else 'common'::public.game_rarity end;
 if v_kind='trash_weighted' then
  wanted:=case when random()*10000<(p_rule->>'trash_bp')::integer then 'trash' else 'fish' end;
 end if;
 select array_agg(s.id order by s.id) into ids from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and s.rarity=r and case v_kind
  when 'decoration' then s.kind='decoration'
  when 'trash_only' then s.kind='trash'
  when 'trash_weighted' then s.kind::text=wanted
  when 'discovery_only' then s.kind in('fish','trash','decoration') and not exists(
   select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
  when 'discovery_weighted' then s.kind in('fish','trash','decoration')
  else s.kind in('fish','trash') end;
 -- Preserve legacy specialty fallback rules. New mixed-kind boats only
 -- renormalize a missing kind within the same grade, never upgrade the grade.
 if ids is null and v_kind='trash_weighted' then
  select array_agg(s.id order by s.id) into ids from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and s.rarity=r and s.kind in('fish','trash');
 elsif ids is null and v_kind in('trash_only','discovery_only') then
  fallback:=true;
  select array_agg(s.id order by s.id) into ids from public.collectible_species s where
   case when v_kind='trash_only' then s.kind='trash' else s.kind in('fish','trash','decoration')
    and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id) end;
 end if;
 if ids is null then
  if v_kind='discovery_only' then return null;end if;
  raise exception 'NO_COLLECTIBLE_FOR_REGION';
 end if;
 -- Independent habitat picker: future bait/rod helper changes cannot leak in.
 with candidates as materialized(
  select s.id,s.rarity,
   case when not s.is_native then 'shared' when s.native_region_id=p_region then 'home' else 'away' end bucket,
   case when v_kind='discovery_weighted' and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
    then (p_rule->>'discovery_weight')::numeric else 1 end discovery_weight
  from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and s.id=any(ids)
 ),groups as materialized(select distinct bucket from candidates),selected as materialized(
  select bucket from groups order by -ln(greatest(random(),1e-15))/case bucket
   when 'home' then 35*(p_rule->>'home_multiplier')::numeric when 'shared' then 60 else 5 end,bucket limit 1
 )select c.id into sid from candidates c join selected g using(bucket)
 order by -ln(greatest(random(),1e-15))/(c.discovery_weight*case when fallback then
  case c.rarity when 'common' then 7700 when 'rare' then 2000 when 'epic' then 270 else 30 end else 1 end),c.id limit 1;
 return sid;
end $function$

CREATE OR REPLACE FUNCTION app_private.harbor_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w jsonb;capacity integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 w:=app_private.get_gold_wallet();
 select coalesce((select dock_slots from app_private.player_harbor_capacity where user_id=u),2) into capacity;
 return jsonb_build_object('serverNow',clock_timestamp(),'fuel',coalesce((w->'inventory'->>'fuel')::integer,0),'fuelPrice',57,'fuelDailyLimit',5,'fuelPurchasedToday',coalesce((select sum((op.receipt->>'quantity')::integer) from app_private.harbor_operations op where op.user_id=u and op.receipt->>'action'='fuel' and op.created_at>=((clock_timestamp() at time zone 'Asia/Seoul')::date::timestamp at time zone 'Asia/Seoul')),0),'dockSlots',capacity,'nextDockExpansion',case when capacity<4 then jsonb_build_object('slot',capacity+1,'price',case capacity when 2 then 10000 else 30000 end) else null end,
 'regions',(select jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'unlocked',not r.requires_map_fragment or exists(select 1 from public.player_map_fragments m where m.user_id=u and m.region_id=r.id)) order by r.sort_order) from public.regions r),
 'vessels',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('owned',o.n>0,'ownedCount',o.n) order by v.sort_order)
  from public.harbor_vessels v cross join lateral(select count(*)::integer n from public.harbor_boats b where b.user_id=u and b.vessel_id=v.id and b.sold_at is null)o),'[]'::jsonb),
 'boats',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('id',b.id,'vessel_id',b.vessel_id,'instance_no',b.instance_no,'dock_slot',b.dock_slot,'owned',true) order by b.purchased_at,b.id)
  from public.harbor_boats b join public.harbor_vessels v on v.id=b.vessel_id where b.user_id=u and b.sold_at is null),'[]'::jsonb),
 'voyages',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('region_name',(select name from public.regions where id=v.region_id)) order by v.departed_at) from public.harbor_voyages v where v.user_id=u and v.claimed_at is null),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION app_private.ladder_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT NULL::text, p_stake integer DEFAULT NULL::integer, p_choice integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r app_private.ladder_runs;v_gold integer;v_payouts integer[];v_bridges integer[]:='{}';v_col integer;v_link integer;v_reward integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action='state' then
  select * into r from app_private.ladder_runs where user_id=v_uid order by created_at desc,id limit 1;
  return jsonb_build_object('run',case when r.id is null then null else to_jsonb(r)-'user_id' end);
 end if;
 if p_action is distinct from 'play' or p_operation_id is null or p_mode is null or p_mode not in ('calm','wave','lucky','shark','storm')
  or p_stake is null or p_stake not between 20 and 1000 or p_stake%20<>0
  or p_choice is null or p_choice not between 0 and 5 then raise exception 'INVALID_LADDER_REQUEST';end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 select * into r from app_private.ladder_runs where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if r.mode<>p_mode or r.stake<>p_stake or r.choice<>p_choice then raise exception 'OPERATION_CONFLICT';end if;
  return jsonb_build_object('run',to_jsonb(r)-'user_id');
 end if;
 if v_gold<p_stake then raise exception 'INSUFFICIENT_GOLD';end if;
 -- Every start has the same six equally likely endpoints, independently of bridges.
 -- Stakes are multiples of 20; these tenths pay integral gold without rounding loss.
 select array_agg(x order by random()) into v_payouts from unnest(case p_mode
  when 'calm' then array[70,80,90,100,120,140]
  when 'wave' then array[0,50,80,100,150,220]
  when 'lucky' then array[0,20,120,130,150,180]
  when 'shark' then array[0,0,0,50,150,400]
  else array[0,0,0,0,0,600] end) x;
 v_col:=p_choice;
 for i in 1..12 loop
  v_link:=floor(random()*6)::integer-1;
  v_bridges:=array_append(v_bridges,v_link);
  if v_link>=0 then
   if v_link=v_col then v_col:=v_col+1;elsif v_link=v_col-1 then v_col:=v_col-1;end if;
  end if;
 end loop;
 v_reward:=p_stake*v_payouts[v_col+1]/100;
 if v_gold-p_stake+v_reward>1000000000 then raise exception 'GOLD_LIMIT';end if;
 insert into app_private.ladder_runs(user_id,operation_id,mode,stake,choice,bridges,payouts,destination,reward)
 values(v_uid,p_operation_id,p_mode,p_stake,p_choice,v_bridges,v_payouts,v_col,v_reward) returning * into r;
 update public.player_wallets set gold=gold-p_stake+v_reward,updated_at=clock_timestamp() where user_id=v_uid;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
 values(v_uid,p_operation_id,'buy','arcade:ladder:'||r.id::text,-p_stake);
 if v_reward>0 then
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
  values(v_uid,gen_random_uuid(),'charge','arcade:ladder:'||r.id::text,v_reward);
 end if;
 return jsonb_build_object('run',to_jsonb(r)-'user_id');
end $function$

CREATE OR REPLACE FUNCTION app_private.ladder_leaderboard(p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>10000 then raise exception 'INVALID_OFFSET';end if;
 with personal as (
  select r.*,row_number() over(partition by user_id order by reward desc,created_at,id) rn from app_private.ladder_runs r where reward>0
 ), ranked as (
  select p.*,row_number() over(order by reward desc,created_at,id) rank from personal p where rn=1
 ), page as (select * from ranked order by rank offset p_offset limit 20)
 select jsonb_build_object('total',(select count(*) from ranked),'rows',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'rank',p.rank,'gold',p.reward,'nickname',coalesce(u.nickname,'섬 여행자'),'mine',p.user_id=auth.uid(),'avatarPath',u.avatar_path,'level',app_private.player_level(p.user_id),'levelProgress',app_private.player_level_progress(p.user_id),'userId',p.user_id,'friendCode',u.friend_code,'friendStatus',(select f.status from public.friend_requests f where f.status in ('pending','accepted') and ((f.sender_id=auth.uid() and f.recipient_id=p.user_id) or (f.recipient_id=auth.uid() and f.sender_id=p.user_id)) order by f.created_at desc limit 1)) order by p.rank) from page p left join public.player_profiles u on u.id=p.user_id),'[]'::jsonb)) into v_result;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION app_private.lock_collectible_habitat_species()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_ids text[];
begin
 if tg_op='INSERT' then v_ids:=array[new.species_id];
 elsif tg_op='DELETE' then v_ids:=array[old.species_id];
 else v_ids:=array[old.species_id,new.species_id]; end if;
 perform 1 from public.collectible_species where id=any(v_ids) order by id for update;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.manage_aquarium_tank(p_tank_id uuid, p_action text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_tank public.aquarium_tanks; v_name text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into v_tank from public.aquarium_tanks where id=p_tank_id and user_id=v_uid for update;
 if not found then raise exception 'TANK_NOT_FOUND'; end if;
 if p_action='rename' then
  v_name:=btrim(p_value);
  if v_name is null or char_length(v_name) not between 1 and 20 or v_name ~ '[[:cntrl:]]' then raise exception 'INVALID_TANK_NAME'; end if;
  update public.aquarium_tanks set name=v_name where id=p_tank_id;
 elsif p_action='equip' then
  if p_value is null or not exists(select 1 from public.aquarium_backgrounds where id=p_value) then raise exception 'INVALID_ITEM'; end if;
  if p_value<>'default' and not exists(select 1 from public.owned_aquarium_backgrounds where user_id=v_uid and background_id=p_value) then raise exception 'BACKGROUND_NOT_OWNED'; end if;
  update public.aquarium_tanks set background_id=p_value where id=p_tank_id;
  if v_tank.is_default then update public.player_aquariums set background_id=p_value where user_id=v_uid; end if;
 else raise exception 'INVALID_TRADE';
 end if;
 return app_private.aquarium_state();
end $function$

CREATE OR REPLACE FUNCTION app_private.manual_experience_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare kind text;amount integer;
begin
 if new.rarity is null then amount:=2;
 else
  select p.snapshot->>'kind' into kind from app_private.prepared_fishing_casts p where p.user_id=new.user_id and p.operation_id=new.operation_id;
  if kind is null then select s.kind::text into kind from public.player_collectibles c join public.collectible_species s on s.id=c.species_id where c.id=new.collectible_id and c.user_id=new.user_id;end if;
  amount:=app_private.catch_experience(kind,new.rarity::text);
 end if;
 perform app_private.award_experience(new.user_id,'manual',new.operation_id,amount);
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.manual_fishing_success_chance_bp(p_bait_id text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare bonus integer;fixed integer;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 select success_chance_bp into fixed from public.fishing_baits where id=p_bait_id;
 if fixed is not null then return fixed;end if;
 select r.failure_reduction_bp into bonus from public.player_rod_loadouts l
 join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
 join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.id in ('bronze','calm');
 return least(10000,app_private.fishing_success_chance_bp(p_bait_id)+coalesce(bonus,0));
end $function$

