CREATE OR REPLACE FUNCTION app_private.memory_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_card integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r public.memory_game_runs;b app_private.memory_game_boards;v_gold integer;v_deck text[];
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_action is null or p_action not in ('state','start','flip','clear','leave') then raise exception 'INVALID_MEMORY_ACTION'; end if;
 if p_action='state' then
  if p_run_id is null then select * into r from public.memory_game_runs where user_id=v_uid and finished_at is null and abandoned_at is null;
  else select * into r from public.memory_game_runs where user_id=v_uid and id=p_run_id;
   if not found then raise exception 'MEMORY_RUN_NOT_FOUND'; end if;
  end if;
  return app_private.memory_response(r.id);
 end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 if p_action='start' then
  if p_operation_id is null then raise exception 'INVALID_OPERATION'; end if;
  select * into r from public.memory_game_runs where user_id=v_uid and operation_id=p_operation_id;
  if found then return app_private.memory_response(r.id); end if;
  select * into r from public.memory_game_runs where user_id=v_uid and finished_at is null and abandoned_at is null;
  if found then return app_private.memory_response(r.id); end if;
  if v_gold<10 then raise exception 'INSUFFICIENT_GOLD'; end if;
  select array_agg(face order by shuffle) into v_deck from (
   select face,random() shuffle from unnest(array['starfish','shell','pearl','rod','float','lighthouse','boat','treasure','coral','fish','shrimp','letter']) face cross join generate_series(1,2)) s;
  v_deck:=v_deck[1:12]||array['pongi']||v_deck[13:24];
  insert into public.memory_game_runs(user_id,operation_id) values(v_uid,p_operation_id) returning * into r;
  insert into app_private.memory_game_boards(run_id,deck) values(r.id,v_deck);
  update public.player_wallets set gold=gold-10,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','arcade:memory',-10);
  return app_private.memory_response(r.id);
 end if;
 select * into r from public.memory_game_runs where id=p_run_id and user_id=v_uid for update;
 if not found then raise exception 'MEMORY_RUN_NOT_FOUND'; end if;
 if r.finished_at is not null or r.abandoned_at is not null then return app_private.memory_response(r.id); end if;
 select * into strict b from app_private.memory_game_boards where run_id=r.id;
 if p_action='leave' then
  update public.memory_game_runs set abandoned_at=clock_timestamp() where id=r.id;
  return app_private.memory_response(r.id);
 end if;
 if p_action='clear' then
  if b.clear_at is null or clock_timestamp()<b.clear_at then return app_private.memory_response(r.id); end if;
  update app_private.memory_game_boards set first_card=null,second_card=null,clear_at=null where run_id=r.id;
  return app_private.memory_response(r.id);
 end if;
 if p_card is null or p_card not between 1 and 25 then raise exception 'INVALID_MEMORY_CARD'; end if;
 if p_card=13 or p_card=any(b.matched) or p_card=b.first_card or b.second_card is not null then return app_private.memory_response(r.id); end if;
 if r.timer_started_at is null then
  update public.memory_game_runs set timer_started_at=clock_timestamp() where id=r.id returning * into r;
 end if;
 if b.first_card is null then update app_private.memory_game_boards set first_card=p_card where run_id=r.id;
 else
  update public.memory_game_runs set moves=moves+1 where id=r.id;
  if b.deck[b.first_card]=b.deck[p_card] then
   b.matched:=b.matched||array[b.first_card,p_card];
   update app_private.memory_game_boards set matched=b.matched,first_card=null,second_card=null,clear_at=null where run_id=r.id;
   if cardinality(b.matched)=24 then
    update public.memory_game_runs set finished_at=clock_timestamp(),elapsed_ms=floor(extract(epoch from(clock_timestamp()-r.timer_started_at))*1000)::bigint where id=r.id;
   end if;
  else update app_private.memory_game_boards set second_card=p_card,clear_at=clock_timestamp()+interval '900 milliseconds' where run_id=r.id;
  end if;
 end if;
 return app_private.memory_response(r.id);
end $function$

CREATE OR REPLACE FUNCTION app_private.memory_response(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.memory_game_runs;b app_private.memory_game_boards;v_cards jsonb;
begin
 if p_id is null then return jsonb_build_object('run',null,'serverNow',clock_timestamp()); end if;
 select * into strict r from public.memory_game_runs where id=p_id;
 select * into strict b from app_private.memory_game_boards where run_id=p_id;
 select jsonb_agg(case when i=13 or i=any(b.matched) or i=b.first_card or i=b.second_card then to_jsonb(b.deck[i]) else 'null'::jsonb end order by i) into v_cards from generate_series(1,25) i;
 return jsonb_build_object('serverNow',clock_timestamp(),'run',jsonb_build_object('id',r.id,'cards',v_cards,
 'matched',to_jsonb(b.matched),'first',b.first_card,'second',b.second_card,'clearAt',b.clear_at,
 'startedAt',r.timer_started_at,'elapsedMs',case when r.elapsed_ms is not null then r.elapsed_ms when r.timer_started_at is null then 0 else floor(extract(epoch from(clock_timestamp()-r.timer_started_at))*1000)::bigint end,
 'moves',r.moves,'finished',r.finished_at is not null,'abandoned',r.abandoned_at is not null));
end $function$

CREATE OR REPLACE FUNCTION app_private.merchant_order_bonus(p_items jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare n integer;total integer;rare_units integer;rare_kinds integer;epics integer;mythics integer;bonus integer;
begin
 if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'INVALID_MERCHANT_ITEMS';end if;
 n:=jsonb_array_length(p_items);
 if n not between 1 and 3 or exists(select 1 from jsonb_array_elements(p_items) a where (a->>'quantity') is null or (a->>'quantity')::integer not between 1 and 2 or coalesce(a->>'rarity','') not in ('common','rare','epic','mythic')) then raise exception 'INVALID_MERCHANT_ITEMS';end if;
 select sum((a->>'quantity')::integer),coalesce(sum((a->>'quantity')::integer) filter(where a->>'rarity'='rare'),0),count(*) filter(where a->>'rarity'='rare'),count(*) filter(where a->>'rarity'='epic'),count(*) filter(where a->>'rarity'='mythic')
 into total,rare_units,rare_kinds,epics,mythics from jsonb_array_elements(p_items) a;
 if n=1 and total=1 then
  return case p_items->0->>'rarity' when 'common' then 80 when 'rare' then 100 when 'epic' then 250 else 600 end;
 elsif n=2 and total=2 then
  bonus:=case rare_kinds when 0 then 120 when 1 then 200 else 250 end;
 elsif n=2 and total=3 then
  bonus:=case rare_units when 0 then 200 when 1 then 300 when 2 then 380 else 500 end;
 elsif n=3 and total=4 and (select max((a->>'quantity')::integer) from jsonb_array_elements(p_items) a)=2 then
  bonus:=case rare_kinds when 0 then 600 when 1 then 800 else 1000 end;
 else raise exception 'INVALID_MERCHANT_ITEMS';end if;
 return bonus+epics*250+mythics*600;
end $function$

CREATE OR REPLACE FUNCTION app_private.merchant_recipe(p_size_roll integer, p_grade_roll integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare n integer;grade text;
begin
 if p_size_roll is null or p_grade_roll is null or p_size_roll not between 0 and 9999 or p_grade_roll not between 0 and 9999 then raise exception 'INVALID_MERCHANT_ROLL';end if;
 n:=case when p_size_roll<3000 then 1 when p_size_roll<8000 then 2 when p_size_roll<9700 then 3 else 4 end;
 grade:=case when p_grade_roll<7600 then 'common' when p_grade_roll<9600 then 'rare' when p_grade_roll<9970 then 'epic' else 'mythic' end;
 return jsonb_build_object('count',n,'rarity',grade);
end $function$

CREATE OR REPLACE FUNCTION app_private.merchant_reward(p_count integer, p_rarity text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare position integer;rewards integer[];
begin
 if p_count is null or p_count not between 1 and 4 or p_rarity is null or p_rarity not in ('common','rare','epic','mythic') then raise exception 'INVALID_MERCHANT_REWARD';end if;
 position:=case p_rarity when 'common' then 1 when 'rare' then 2 when 'epic' then 3 else 4 end;
 rewards:=case p_count when 1 then array[100,130,170,200] when 2 then array[200,230,270,300] when 3 then array[300,360,430,500] else array[500,560,630,700] end;
 return rewards[position];
end $function$

CREATE OR REPLACE FUNCTION app_private.merchant_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();d date;result jsonb;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 loop
  perform app_private.ensure_merchant_orders();
  d:=(clock_timestamp() at time zone 'Asia/Seoul')::date;
  exit when exists(select 1 from app_private.merchant_days m where m.day=d);
 end loop;
 with stock as materialized (select c.species_id,count(*) n from public.player_collectibles c where c.user_id=uid and c.sold_at is null and c.escrow_gift_id is null and c.tank_id is null group by c.species_id)
 select jsonb_build_object('day',d,'serverNow',clock_timestamp(),'resetsAt',(d+1)::timestamp at time zone 'Asia/Seoul','dailyLimit',null,
 'deliveredToday',(select count(*) from app_private.merchant_deliveries x where x.user_id=uid and x.day=d),
 'orders',coalesce(jsonb_agg(jsonb_build_object('id',o.id,'number',o.slot,'tier',o.tier,'regionName',r.name,
 'baseGold',o.base_gold,'rewardGold',o.reward_gold,'completed',o.completed_at is not null,'mine',coalesce(o.completed_by=uid,false),
 'delivery',case when o.completed_at is not null then jsonb_build_object('nickname',coalesce(o.completed_name,'섬 모험가'),'avatarPath',case when profile.id is not null then profile.avatar_path else o.completed_avatar_path end,'message',o.completed_message,'level',case when profile.id is not null then app_private.player_level(profile.id) end,'levelProgress',case when profile.id is not null then app_private.player_level_progress(profile.id) end) end,
 'items',(select jsonb_agg(item||jsonb_build_object('owned',coalesce(stock.n,0)) order by ord) from jsonb_array_elements(o.items) with ordinality a(item,ord)
 left join stock on stock.species_id=item->>'speciesId')) order by o.slot),'[]'::jsonb)) into result
 from app_private.merchant_orders o left join public.regions r on r.id=o.region_id left join public.player_profiles profile on profile.id=o.completed_by where o.day=d;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.move_collectibles(p_collectible_ids uuid[], p_tank_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_ids uuid[];v_count integer;v_occupancy integer;v_added integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if coalesce(cardinality(p_collectible_ids),0) not between 1 and 100 then raise exception 'INVALID_SELECTION'; end if;
 select array_agg(id order by id) into v_ids from(select distinct unnest(p_collectible_ids) as id) q;
 if cardinality(v_ids)<>cardinality(p_collectible_ids) or array_position(v_ids,null) is not null then raise exception 'INVALID_SELECTION'; end if;
 -- Serialize admissions to the same tank before locking individuals in ID order.
 if p_tank_id is not null then
  perform 1 from public.aquarium_tanks where id=p_tank_id and user_id=v_uid for update;
  if not found then raise exception 'TANK_NOT_FOUND'; end if;
 end if;
 perform 1 from public.player_collectibles where id=any(v_ids) and user_id=v_uid order by id for update;
 select count(*) into v_count from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.id=any(v_ids) and c.user_id=v_uid and c.sold_at is null and c.escrow_gift_id is null and s.kind in ('fish','trash','decoration');
 if v_count<>cardinality(v_ids) then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 if p_tank_id is not null then
  if exists(select 1 from public.player_collectibles where id=any(v_ids) and tank_id is not null and tank_id<>p_tank_id) then raise exception 'STORAGE_REQUIRED'; end if;
  select count(*) into v_added from public.player_collectibles where id=any(v_ids) and tank_id is null;
  select count(*) into v_occupancy from public.player_collectibles where tank_id=p_tank_id and user_id=v_uid and sold_at is null and escrow_gift_id is null;
  if v_added>0 and v_occupancy+v_added>coalesce((select capacity from app_private.player_aquarium_capacity where user_id=v_uid),50) then raise exception 'TANK_FULL'; end if;
 end if;
 update public.player_collectibles set tank_id=p_tank_id,position_x=null,position_y=null
 where id=any(v_ids) and tank_id is distinct from p_tank_id;
 return app_private.aquarium_state();
end $function$

CREATE OR REPLACE FUNCTION app_private.music_edit(p_action text, p_id text, p_title text DEFAULT ''::text, p_name text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid();
begin
 if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_id is null or p_id !~ '^[A-Za-z0-9_-]{11}$' or p_title is null or char_length(p_title)>1000 or p_name is null or char_length(p_name)>150 then raise exception 'INVALID_MUSIC'; end if;
 perform app_private.music_library();
 if p_action='add' then
  if not exists(select 1 from public.music_tracks where user_id=v_user and video_id=p_id) and (select count(*) from public.music_tracks where user_id=v_user)>=200 then raise exception 'MUSIC_LIMIT'; end if;
  insert into public.music_tracks(user_id,video_id,title,custom_name) values(v_user,p_id,p_title,btrim(p_name))
  on conflict(user_id,video_id) do nothing;
 elsif p_action='rename' then update public.music_tracks set custom_name=btrim(p_name) where user_id=v_user and video_id=p_id;
 elsif p_action='title' then update public.music_tracks set title=p_title where user_id=v_user and video_id=p_id;
 elsif p_action='delete' then delete from public.music_tracks where user_id=v_user and video_id=p_id;
 else raise exception 'INVALID_MUSIC_ACTION'; end if;
 return app_private.music_library();
end $function$

CREATE OR REPLACE FUNCTION app_private.music_library(p_import jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_new uuid; v_track jsonb;
begin
 if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_import is not null then
  if jsonb_typeof(p_import)<>'array' then raise exception 'INVALID_MUSIC_IMPORT'; end if;
  if jsonb_array_length(p_import)>200 then raise exception 'MUSIC_LIMIT'; end if;
  for v_track in select value from jsonb_array_elements(p_import) loop
   if jsonb_typeof(v_track)<>'object' or coalesce(v_track->>'id','') !~ '^[A-Za-z0-9_-]{11}$'
    or jsonb_typeof(v_track->'id') is distinct from 'string'
    or jsonb_typeof(v_track->'title') is distinct from 'string'
    or jsonb_typeof(v_track->'customName') is distinct from 'string'
    or char_length(v_track->>'title')>1000 or char_length(v_track->>'customName')>150
    then raise exception 'INVALID_MUSIC_IMPORT'; end if;
  end loop;
 end if;
 insert into public.music_libraries(user_id) values(v_user) on conflict do nothing returning user_id into v_new;
 -- Serialize initial import and all subsequent changes for this owner only.
 perform 1 from public.music_libraries where user_id=v_user for update;
 if v_new is not null then
  if p_import is null then
   insert into public.music_tracks(user_id,video_id,title,created_at)
   select v_user,video_id,title,now()+sort_order*interval '1 microsecond' from public.music_defaults;
  else
   insert into public.music_tracks(user_id,video_id,title,custom_name,created_at)
   select v_user,t.id,t.title,t.name,now()+t.ord*interval '1 microsecond' from (
    select distinct on (value->>'id') value->>'id' id,value->>'title' title,btrim(value->>'customName') name,ordinality ord
    from jsonb_array_elements(p_import) with ordinality order by value->>'id',ordinality desc
   ) t;
  end if;
 end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',video_id,'title',title,'customName',custom_name) order by created_at,video_id) from public.music_tracks where user_id=v_user),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION app_private.notice_delete(p_id uuid, p_revision integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.notices;
begin
 if not app_private.notice_is_operator() then raise exception 'NOTICE_FORBIDDEN';end if;
 select * into n from public.notices where id=p_id for update;
 if not found then return;end if;
 if p_revision is distinct from n.revision then raise exception 'NOTICE_CHANGED';end if;
 -- Linked announcement notifications are removed by the foreign key cascade.
 delete from public.notices where id=p_id;
end $function$

CREATE OR REPLACE FUNCTION app_private.notice_save(p_id uuid, p_category text, p_title text, p_body text, p_images text[], p_status text, p_pinned boolean, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n public.notices;v_path text;
begin
 if not app_private.notice_is_operator() then raise exception 'NOTICE_FORBIDDEN';end if;
 if p_id is null or p_category is null or p_category not in('guide','update','maintenance','event') or p_title is null or char_length(btrim(p_title)) not between 2 and 100
 or p_body is null or char_length(p_body)>20000 or p_images is null or cardinality(p_images)>6 or array_position(p_images,null) is not null
 or p_status is null or p_status not in('draft','published','hidden') or p_pinned is null or p_revision is null or p_revision<0
 or (p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at) then raise exception 'INVALID_NOTICE';end if;
 if p_status='published' and btrim(p_body)='' and cardinality(p_images)=0 then raise exception 'NOTICE_EMPTY';end if;
 foreach v_path in array p_images loop
  if split_part(v_path,'/',1)<>p_id::text or not exists(select 1 from storage.objects where bucket_id='notice-images' and name=v_path and metadata->>'mimetype' in('image/png','image/jpeg','image/webp')) then raise exception 'NOTICE_IMAGE_INVALID';end if;
 end loop;
 -- Serialize creates and updates, including duplicate retries of the same document.
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into n from public.notices where id=p_id for update;
 if found then
  if n.revision<>p_revision then raise exception 'NOTICE_CHANGED';end if;
  update public.notices set category=p_category,title=btrim(p_title),body=p_body,images=p_images,status=p_status,pinned=p_pinned,
   starts_at=p_starts_at,ends_at=p_ends_at,updated_at=clock_timestamp(),revision=revision+1,
   published_at=case when p_status='published' then coalesce(published_at,clock_timestamp()) else published_at end where id=p_id returning * into n;
 else
  if p_revision<>0 then raise exception 'NOTICE_CHANGED';end if;
  insert into public.notices(id,category,title,body,images,status,pinned,starts_at,ends_at,author_id,published_at)
  values(p_id,p_category,btrim(p_title),p_body,p_images,p_status,p_pinned,p_starts_at,p_ends_at,auth.uid(),case when p_status='published' then clock_timestamp() end) returning * into n;
 end if;
 return to_jsonb(n);
end $function$

CREATE OR REPLACE FUNCTION app_private.notify_due_bait_production_sites()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 with due as (
  select id from app_private.bait_production_sites where started_at is not null and notified_started_at is distinct from started_at
   and completes_at<=clock_timestamp() and expires_at>clock_timestamp() order by completes_at,id limit 500 for update skip locked
 ), marked as (
  update app_private.bait_production_sites s set notified_started_at=s.started_at from due where s.id=due.id returning s.*
 ) insert into public.notifications(recipient_id,category,kind,title,body,bait_production_site_id,bait_production_started_at)
 select s.user_id,'general','system','미끼 생산이 끝났어요!',f.name||'에서 '||b.name||' '||s.run_output||'개를 만들었어요. 보관 시간 안에 수령해 주세요.',s.id,s.started_at
 from marked s join public.bait_production_facilities f on f.id=s.facility_id join public.fishing_baits b on b.id=coalesce(s.run_bait_id,f.bait_id)
 on conflict(bait_production_site_id,bait_production_started_at) where bait_production_site_id is not null do nothing;
 get diagnostics n=row_count;return n;
end $function$

CREATE OR REPLACE FUNCTION app_private.notify_due_expeditions(p_expedition_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 with due as (
  select id from public.fishing_expeditions where returns_at<=clock_timestamp() and notified_at is null and claimed_at is null and (p_expedition_id is null or id=p_expedition_id)
  order by returns_at limit 500 for update skip locked
 ), marked as (
  update public.fishing_expeditions e set notified_at=clock_timestamp() from due where e.id=due.id returning e.*
