 on conflict (expedition_id) where expedition_id is not null do nothing;
 get diagnostics n=row_count;
 return n;
end $function$

CREATE OR REPLACE FUNCTION app_private.odd_even_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_round integer DEFAULT NULL::integer, p_choice text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r public.odd_even_runs;v_gold integer;v_pearls integer;v_win boolean;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in ('state','start','answer','double','cashout') then raise exception 'INVALID_ODD_EVEN_ACTION';end if;
 if p_action='state' then
  select * into r from public.odd_even_runs where user_id=v_uid and finished_at is null;
  return app_private.odd_even_response(r.id);
 end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 if p_action='start' then
  if p_operation_id is null then raise exception 'INVALID_OPERATION';end if;
  select * into r from public.odd_even_runs where user_id=v_uid and operation_id=p_operation_id;
  if found then return app_private.odd_even_response(r.id);end if;
  select * into r from public.odd_even_runs where user_id=v_uid and finished_at is null;
  if found then return app_private.odd_even_response(r.id);end if;
  if v_gold<10 then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into public.odd_even_runs(user_id,operation_id) values(v_uid,p_operation_id) returning * into r;
  update public.player_wallets set gold=gold-10,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','arcade:odd-even',-10);
  return app_private.odd_even_response(r.id);
 end if;
 select * into r from public.odd_even_runs where id=p_run_id and user_id=v_uid for update;
 if not found then raise exception 'ODD_EVEN_RUN_NOT_FOUND';end if;
 if r.finished_at is not null then return app_private.odd_even_response(r.id);end if;
 if p_round is null then raise exception 'INVALID_ROUND';end if;
 if p_round<r.round then return app_private.odd_even_response(r.id);end if;
 if p_round<>r.round then raise exception 'INVALID_ROUND';end if;
 if p_action='answer' then
  if r.stage<>'choose' then return app_private.odd_even_response(r.id);end if;
  if p_choice is null or p_choice not in ('odd','even') then raise exception 'INVALID_CHOICE';end if;
  v_pearls:=1+floor(random()*10)::integer;
  v_win:=(v_pearls%2=1)=(p_choice='odd');
  update public.odd_even_runs set pearls=v_pearls,choice=p_choice,stake=case when v_win then stake*2 else 0 end,
   wins=wins+case when v_win then 1 else 0 end,stage=case when v_win then 'decision' else 'lost' end,
   finished_at=case when v_win then null else clock_timestamp() end where id=r.id;
 elsif p_action='double' then
  if r.stage='choose' then return app_private.odd_even_response(r.id);end if;
  if r.wins>=20 then raise exception 'ODD_EVEN_LIMIT';end if;
  update public.odd_even_runs set stage='choose',round=round+1,pearls=null,choice=null where id=r.id;
 else
  if r.stage<>'decision' then raise exception 'ODD_EVEN_WIN_REQUIRED';end if;
  if v_gold>1000000000-r.stake then raise exception 'GOLD_LIMIT';end if;
  update public.player_wallets set gold=gold+r.stake,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,r.payout_operation_id,'charge','arcade:odd-even:'||r.id::text,r.stake);
  update public.odd_even_runs set stage='banked',finished_at=clock_timestamp() where id=r.id;
 end if;
 return app_private.odd_even_response(r.id);
end $function$

CREATE OR REPLACE FUNCTION app_private.owned_collectibles()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('species',app_private.species_payload(s.id,c.map_region_id)) order by c.acquired_at desc)
 from public.player_collectibles c join public.collectible_species s on s.id=c.species_id where c.user_id=v_uid and c.sold_at is null and c.escrow_gift_id is null),'[]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION app_private.personal_bait_workshop_action(p_action text, p_operation_id uuid, p_bait_id text DEFAULT NULL::text, p_quantity integer DEFAULT NULL::integer, p_minutes integer DEFAULT NULL::integer, p_job_id uuid DEFAULT NULL::uuid, p_expected_fuel integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w public.player_wallets;b public.fishing_baits;j app_private.personal_bait_jobs;
 previous app_private.personal_bait_operations;sig jsonb;receipt jsonb;unit_value integer;cost integer;stock bigint;v_now timestamptz;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('start','claim') then raise exception 'INVALID_WORKSHOP_ACTION';end if;
 sig:=jsonb_build_object('action',p_action,'bait',p_bait_id,'quantity',p_quantity,'minutes',p_minutes,'job',p_job_id,'expectedFuel',p_expected_fuel);
 perform app_private.get_gold_wallet();
 -- Shares the wallet lock with all other fuel spenders and reward claims.
 select * into strict w from public.player_wallets where user_id=u for update;
 select * into previous from app_private.personal_bait_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if previous.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.personal_bait_workshop_state()||jsonb_build_object('receipt',previous.receipt,'replayed',true);
 end if;
 v_now:=clock_timestamp();
 if p_action='start' then
  if p_quantity is null or p_quantity not between 1 and 100 then raise exception 'INVALID_WORKSHOP_QUANTITY';end if;
  if p_minutes is null or p_minutes not between 30 and 720 or p_minutes%30<>0 then raise exception 'INVALID_WORKSHOP_TIME';end if;
  if p_job_id is not null then raise exception 'INVALID_WORKSHOP_ACTION';end if;
  select * into b from public.fishing_baits where id=p_bait_id and price>0 for share;
  if not found then raise exception 'BAIT_NOT_AVAILABLE';end if;
  if exists(select 1 from app_private.personal_bait_jobs where user_id=u and claimed_at is null) then raise exception 'PERSONAL_PRODUCTION_BUSY';end if;
  unit_value:=case when b.id='bait' then 50 else b.price end;
  -- 20% less fuel before rounding; preserve the existing linear time bonus.
  cost:=ceil(p_quantity::numeric*unit_value*92/(5750+100*(p_minutes/30-1)))::integer;
  if p_expected_fuel is distinct from cost then raise exception 'FUEL_QUOTE_CHANGED';end if;
  if coalesce((w.inventory->>'fuel')::bigint,0)<cost then raise exception 'INSUFFICIENT_FUEL';end if;
  update public.player_wallets set inventory=jsonb_set(inventory,'{fuel}',to_jsonb((inventory->>'fuel')::integer-cost)),updated_at=v_now where user_id=u;
  insert into app_private.personal_bait_jobs(user_id,bait_id,bait_name,image_path,quantity,production_minutes,unit_value,fuel_cost,started_at,completes_at)
   values(u,b.id,b.name,b.image_path,p_quantity,p_minutes,unit_value,cost,v_now,v_now+make_interval(mins=>p_minutes)) returning * into j;
  receipt:=jsonb_build_object('action','start','jobId',j.id,'baitId',b.id,'baitName',b.name,'quantity',j.quantity,'fuelCost',cost,'minutes',p_minutes);
 else
  if p_job_id is null or p_bait_id is not null or p_quantity is not null or p_minutes is not null or p_expected_fuel is not null then raise exception 'INVALID_WORKSHOP_ACTION';end if;
  select * into j from app_private.personal_bait_jobs where id=p_job_id and user_id=u for update;
  if not found or j.claimed_at is not null then raise exception 'WORKSHOP_JOB_NOT_FOUND';end if;
  if v_now<j.completes_at then raise exception 'PRODUCTION_NOT_READY';end if;
  stock:=coalesce((w.inventory->>j.bait_id)::bigint,0)+j.quantity;
  if stock>1000000000 then raise exception 'BAIT_LIMIT';end if;
  update public.player_wallets set inventory=jsonb_set(inventory,array[j.bait_id],to_jsonb(stock::integer)),updated_at=v_now where user_id=u;
  update app_private.personal_bait_jobs set claimed_at=v_now where id=j.id;
  receipt:=jsonb_build_object('action','claim','jobId',j.id,'baitId',j.bait_id,'baitName',j.bait_name,'quantity',j.quantity,'fuelCost',j.fuel_cost,'minutes',j.production_minutes);
 end if;
 insert into app_private.personal_bait_operations(user_id,operation_id,signature,receipt) values(u,p_operation_id,sig,receipt);
 return app_private.personal_bait_workshop_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.personal_bait_workshop_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 w:=app_private.get_gold_wallet();
 return jsonb_build_object('serverNow',clock_timestamp(),'fuel',coalesce((w->'inventory'->>'fuel')::integer,0),
  'limits',jsonb_build_object('maxQuantity',100,'minMinutes',30,'maxMinutes',720,'stepMinutes',30,'maxActive',1),
  'baits',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'name',b.name,'imagePath',b.image_path,
   'unitValue',case when b.id='bait' then 50 else b.price end,'owned',coalesce((w->'inventory'->>b.id)::integer,0)) order by b.sort_order,b.id)
   from public.fishing_baits b where b.price>0),'[]'::jsonb),
  'job',(select jsonb_build_object('id',j.id,'baitId',j.bait_id,'baitName',j.bait_name,'imagePath',j.image_path,
   'quantity',j.quantity,'minutes',j.production_minutes,'unitValue',j.unit_value,'fuelCost',j.fuel_cost,
   'startedAt',j.started_at,'completesAt',j.completes_at)
   from app_private.personal_bait_jobs j where j.user_id=u and j.claimed_at is null));
end $function$

CREATE OR REPLACE FUNCTION app_private.pick_bait_fish(p_region text, p_rarity game_rarity, p_native boolean DEFAULT false, p_manual boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids text[];rod_region text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if not exists(select 1 from public.regions where id=p_region) then raise exception 'REGION_NOT_FOUND';end if;
 if p_manual then
  select r.region_id into rod_region from public.player_rod_loadouts l
  join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
  join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.native_bonus_bp>0;
 end if;
 select array_agg(id order by id) into ids from public.collectible_species where app_private.collectible_available_at(id,statement_timestamp()) and kind='fish' and rarity=p_rarity;
 return app_private.pick_habitat_group(ids,p_region,rod_region,case when p_native then 1.5 else 1 end,false);
end $function$

CREATE OR REPLACE FUNCTION app_private.pick_balanced_bait_collectible(p_region text, p_rarity game_rarity, p_bait text, p_native boolean DEFAULT false, p_manual boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids text[];rod_region text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_bait is null or p_bait not in ('bait_snowflake_salt','bait_shooting_star_tail') then raise exception 'INVALID_BAIT';end if;
 if not exists(select 1 from public.regions where id=p_region) then raise exception 'REGION_NOT_FOUND';end if;
 if p_rarity is null or (p_bait='bait_shooting_star_tail' and p_rarity not in ('common','mythic')) then raise exception 'INVALID_RARITY';end if;
 if p_manual then
  select r.region_id into rod_region from public.player_rod_loadouts l
  join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
  join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.native_bonus_bp>0;
 end if;
 select array_agg(s.id order by s.id) into ids from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and s.rarity=p_rarity and case
  when p_bait='bait_snowflake_salt' then not s.is_native and s.kind in ('fish','trash')
  when p_rarity='mythic' then s.kind in ('fish','trash','decoration')
  else s.kind='trash' end;
 if ids is null then raise exception 'NO_COLLECTIBLE_FOR_REGION';end if;
 return app_private.pick_habitat_group(ids,p_region,rod_region,case when p_native then 1.5 else 1 end,false);
end $function$

CREATE OR REPLACE FUNCTION app_private.pick_profile_collectible(p_region text, p_rarity game_rarity, p_profile jsonb, p_manual boolean DEFAULT false, p_native boolean DEFAULT false, p_local_discovery boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ids text[];rod_region text;fallback boolean;bid text:=p_profile->>'id';effect text:=p_profile->>'effect_kind';
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_profile is null then raise exception 'INVALID_BAIT';end if;
 if not exists(select 1 from public.regions where id=p_region) then raise exception 'REGION_NOT_FOUND';end if;
 if p_manual then
  select r.region_id into rod_region from public.player_rod_loadouts l
  join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
  join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.native_bonus_bp>0;
 end if;
 with candidates as materialized (
  select s.id,s.rarity from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and case
   when effect='undiscovered' then s.kind in ('fish','trash','decoration')
    and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
    and (not p_local_discovery or exists(select 1 from public.collectible_habitats h where h.species_id=s.id and h.region_id=p_region))
   when bid='bait_grubby_magnet' then s.kind='trash'
   when effect='shooting_star' then s.rarity=p_rarity and (p_rarity='mythic' or s.kind='trash')
   when effect='common_only' then s.rarity=p_rarity and not s.is_native and (p_profile->'target_kinds') ? s.kind::text
   else s.rarity=p_rarity and (p_profile->'target_kinds') ? s.kind::text end
 ), pool as (
  select * from candidates c where c.rarity=p_rarity
   or (effect='undiscovered' or bid='bait_grubby_magnet') and not exists(select 1 from candidates c2 where c2.rarity=p_rarity)
 )
 select array_agg(id order by id),not coalesce(bool_or(rarity=p_rarity),false) into ids,fallback from pool;
 return app_private.pick_habitat_group(ids,p_region,rod_region,
  coalesce((p_profile->>'native_multiplier')::numeric,1)*(case when p_native then 1.5 else 1 end),fallback);
end $function$

CREATE OR REPLACE FUNCTION app_private.pick_regional_collectible(p_region_id text, p_rarity game_rarity, p_decoration boolean, p_map_roll integer)
 RETURNS TABLE(species_id text, map_region_id text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_rod_region text;ids text[];sid text;
begin
 if p_map_roll is null or p_map_roll<0 or p_map_roll>=10000 then raise exception 'INVALID_ROLL';end if;
 if not exists(select 1 from public.regions where id=p_region_id) then raise exception 'REGION_NOT_FOUND';end if;
 select r.region_id into v_rod_region from public.player_rod_loadouts l
 join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
 join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.native_bonus_bp>0;
 select array_agg(s.id order by s.id) into ids from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and s.rarity=p_rarity and ((p_decoration and s.kind='decoration') or (not p_decoration and s.kind in ('fish','trash')));
 sid:=app_private.pick_habitat_group(ids,p_region_id,v_rod_region);
 if sid is not null then return query select sid,null::text;end if;
end $function$

CREATE OR REPLACE FUNCTION app_private.pick_special_bait_collectible(p_region_id text, p_rarity game_rarity, p_bait_id text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_rod_region text;ids text[];fallback boolean;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_bait_id not in ('bait_grubby_magnet','bait_sea_memory','bait_first_greeting') then raise exception 'INVALID_BAIT';end if;
 if not exists(select 1 from public.regions where id=p_region_id) then raise exception 'REGION_NOT_FOUND';end if;
 select r.region_id into v_rod_region from public.player_rod_loadouts l
 join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
 join public.fishing_rods r on r.id=o.rod_id where l.user_id=auth.uid() and r.native_bonus_bp>0;
 with candidates as materialized (
  select s.id,s.rarity from public.collectible_species s where case p_bait_id
   when 'bait_grubby_magnet' then s.kind='trash'
   when 'bait_first_greeting' then s.kind in ('fish','trash','decoration') and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
   else s.kind in ('fish','trash') and s.rarity=p_rarity end
 ), pool as (select * from candidates c where c.rarity=p_rarity or not exists(select 1 from candidates c2 where c2.rarity=p_rarity))
 select array_agg(id order by id),not coalesce(bool_or(rarity=p_rarity),false) into ids,fallback from pool;
 return app_private.pick_habitat_group(ids,p_region_id,v_rod_region,case when p_bait_id='bait_sea_memory' then 3 else 1 end,fallback);
end $function$

CREATE OR REPLACE FUNCTION app_private.place_collectible(p_collectible_id uuid, p_tank_id uuid, p_x numeric, p_y numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();item public.player_collectibles;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_x is null or p_y is null or not(p_x between 0 and 1) or not(p_y between 0 and 1) then raise exception 'INVALID_POSITION';end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=u) then raise exception 'TANK_NOT_FOUND';end if;
 select * into item from public.player_collectibles where id=p_collectible_id and user_id=u and sold_at is null and escrow_gift_id is null for update;
 if not found or item.tank_id is distinct from p_tank_id then raise exception 'COLLECTIBLE_NOT_FOUND';end if;
 if not exists(select 1 from public.collectible_species where id=item.species_id and (kind in ('decoration','trash') or (kind='fish' and movement_type='fixed'))) then raise exception 'INVALID_ITEM';end if;
 -- Dragging changes coordinates only: retain the lock and manual transform.
 update public.player_collectibles set position_x=p_x,position_y=p_y where id=item.id;
 return jsonb_build_object('id',item.id,'position_x',p_x,'position_y',p_y);
end $function$

CREATE OR REPLACE FUNCTION app_private.player_directory(p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid();v_result jsonb;
begin
 if v_user is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>100000 or p_limit is null or p_limit<1 or p_limit>50 then raise exception 'INVALID_DIRECTORY_PAGE';end if;
 with candidates as materialized (
  select p.id,p.nickname,p.avatar_path,p.equipped_title from public.player_profiles p
  where p.id<>v_user order by p.nickname,p.id limit p_limit+1 offset p_offset
 ), page as (select * from candidates order by nickname,id limit p_limit)
 select jsonb_build_object('players',coalesce((
  select jsonb_agg(jsonb_build_object('id',p.id,'nickname',p.nickname,'avatar_path',p.avatar_path,
   'equipped_title',p.equipped_title,'level',app_private.player_level(p.id),
   'relationship',case when r.status='accepted' then 'friend' when r.status='pending' and r.sender_id=v_user then 'outgoing' when r.status='pending' then 'incoming' else 'none' end)
   order by p.nickname,p.id)
  from page p left join lateral (
   select f.status,f.sender_id from public.friend_requests f where f.status in ('pending','accepted') and
    ((f.sender_id=v_user and f.recipient_id=p.id) or (f.recipient_id=v_user and f.sender_id=p.id))
   order by f.updated_at desc,f.id limit 1
  ) r on true
 ),'[]'::jsonb),'hasMore',(select count(*)>p_limit from candidates)) into v_result;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION app_private.player_presence_ping(p_session_id uuid, p_state text, p_revision integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();v_now timestamptz:=clock_timestamp();
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_session_id is null or p_state is null or p_state not in ('online','away','offline')
  or p_revision is null or p_revision<=0 then raise exception 'INVALID_PRESENCE';end if;
 -- Retain offline revisions briefly so delayed requests cannot resurrect a closed tab.
 delete from app_private.player_presence_sessions where user_id=u and last_seen_at<v_now-interval '1 day';
 insert into app_private.player_presence_sessions(user_id,session_id,state,revision,last_seen_at)
 values(u,p_session_id,p_state,p_revision,v_now)
 on conflict(user_id,session_id) do update
 set state=excluded.state,revision=excluded.revision,last_seen_at=excluded.last_seen_at
 where excluded.revision>player_presence_sessions.revision;
end $function$

CREATE OR REPLACE FUNCTION app_private.prepare_fishing(p_region_id text, p_bait_id text, p_operation_id uuid, p_confirm_bite boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();p app_private.prepared_fishing_casts;w public.player_wallets;
 v_current text;v_required boolean;v_count integer;v_profile jsonb;v_started timestamptz;v_wait numeric;
 v_rarity public.game_rarity;v_species text;v_snapshot jsonb;v_reduction integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_confirm_bite is null then raise exception 'INVALID_TRADE';end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||v_uid::text,0));
 select * into p from app_private.prepared_fishing_casts where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if p.region_id<>p_region_id or p.bait_id<>p_bait_id then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.prepared_fishing_payload(p);
 end if;
 if exists(select 1 from public.fishing_attempts where user_id=v_uid and operation_id=p_operation_id) then raise exception 'OPERATION_CONFLICT';end if;
 select * into p from app_private.prepared_fishing_casts where user_id=v_uid and finished_at is null;
 if found then
  if p.expires_at<=clock_timestamp() then perform app_private.finish_fishing(p.operation_id,false);
  else return app_private.prepared_fishing_payload(p);end if;
 end if;
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=v_uid for update;
 if not exists(select 1 from public.fishing_baits where id=p_bait_id) then raise exception 'INVALID_BAIT';end if;
 select requires_map_fragment into v_required from public.regions where id=p_region_id;
 if not found then raise exception 'REGION_NOT_FOUND';end if;
 select region_id into v_current from public.player_navigation where user_id=v_uid;
 if v_current is distinct from p_region_id then raise exception 'NOT_IN_REGION';end if;
 if v_required and not exists(select 1 from public.player_map_fragments where user_id=v_uid and region_id=p_region_id) then raise exception 'REGION_LOCKED';end if;
 v_count:=coalesce((w.inventory->>p_bait_id)::integer,0);
 if v_count<1 then raise exception 'NO_BAIT';end if;
 if p_bait_id='bait_first_greeting' and not exists(select 1 from public.collectible_species s where s.kind in ('fish','trash','decoration')
 and not exists(select 1 from public.player_discoveries d where d.user_id=v_uid and d.species_id=s.id)) then raise exception 'ALL_COLLECTIBLES_DISCOVERED';end if;
 v_started:=clock_timestamp();
 v_profile:=app_private.fishing_bait_balance_at(p_bait_id,v_started);
 v_rarity:=app_private.profile_fishing_rarity(v_profile);
 v_species:=app_private.pick_profile_collectible(p_region_id,v_rarity,v_profile,true);
 if v_species is null then raise exception 'NO_COLLECTIBLE_FOR_REGION';end if;
 select rarity into v_rarity from public.collectible_species where id=v_species;
 v_snapshot:=app_private.species_payload(v_species,null);
 select r.wait_reduction_seconds into v_reduction from public.player_rod_loadouts l
 join public.player_fishing_rods o on o.user_id=l.user_id and o.rod_id=l.equipped_rod_id
 join public.fishing_rods r on r.id=o.rod_id where l.user_id=v_uid;
 v_wait:=12+12*random()-coalesce(v_reduction,0);
 insert into app_private.prepared_fishing_casts(user_id,operation_id,region_id,bait_id,eligible,species_id,map_region_id,rarity,snapshot,wait_seconds,failure_at,failure_reason,created_at,expires_at,bait_snapshot,confirm_bite)
 values(v_uid,p_operation_id,p_region_id,p_bait_id,true,v_species,null,v_rarity,v_snapshot,v_wait,4.5,'bait',v_started,
  case when p_confirm_bite then v_started+interval '24 hours'
   else v_started+make_interval(secs=>v_wait::double precision)+interval '3 minutes' end,
  v_profile,p_confirm_bite) returning * into p;
 update public.player_wallets set inventory=jsonb_set(inventory,array[p_bait_id],to_jsonb(v_count-1)),updated_at=now() where user_id=v_uid;
 return app_private.prepared_fishing_payload(p);
end $function$

CREATE OR REPLACE FUNCTION app_private.prepare_fishing_map_piece()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare chosen record;pieces integer;species integer;
begin
 if not new.eligible or new.rarity<>'rare' or not coalesce((new.bait_snapshot->'target_kinds') ? 'fish',false) then return new;end if;
 select count(*) into pieces from public.fishing_map_blueprints b join public.regions r on r.id=b.region_id
 cross join lateral generate_series(1,b.piece_count) n(piece_number)
 where b.enabled and r.requires_map_fragment
 and not exists(select 1 from public.player_map_fragments f where f.user_id=new.user_id and f.region_id=b.region_id)
 and not exists(select 1 from app_private.player_fishing_map_pieces f where f.user_id=new.user_id and f.region_id=b.region_id and f.piece_number=n.piece_number);
 if pieces=0 then return new;end if;
 select count(*) into species from public.collectible_species s where s.rarity='rare'
 and (new.bait_snapshot->'target_kinds') ? s.kind::text
 and (new.bait_snapshot->>'effect_kind'<>'common_only' or not s.is_native)
 and (new.bait_snapshot->>'effect_kind'<>'undiscovered' or not exists(select 1 from public.player_discoveries d where d.user_id=new.user_id and d.species_id=s.id));
 -- Each missing piece occupies one slot in the rare catch pool, never an extra rarity roll.
 if random()*(species+pieces)>=pieces then return new;end if;
 select b.region_id,b.piece_count,b.thumbnail_path,r.name,n.piece_number into chosen
 from public.fishing_map_blueprints b join public.regions r on r.id=b.region_id
 cross join lateral generate_series(1,b.piece_count) n(piece_number)
 where b.enabled and r.requires_map_fragment
 and not exists(select 1 from public.player_map_fragments f where f.user_id=new.user_id and f.region_id=b.region_id)
 and not exists(select 1 from app_private.player_fishing_map_pieces f where f.user_id=new.user_id and f.region_id=b.region_id and f.piece_number=n.piece_number)
 order by random() limit 1;
 if not found then return new;end if;
 new.map_region_id:=chosen.region_id;new.map_piece_number:=chosen.piece_number;
 new.species_id:=null;new.rarity:='rare';
 new.snapshot:=jsonb_build_object('id','map-piece-'||chosen.region_id||'-'||chosen.piece_number,
 'kind','map','rarity','rare','name',chosen.name||'의 지도 조각 ( '||chosen.piece_number||'/'||chosen.piece_count||' )',
 'description','모든 지도 조각을 모으면 해역이 열려요. 지도에서 수집 현황을 확인하세요.',
 'thumbnail_path',chosen.thumbnail_path,'sell_price',0,'speed',0,'size',1,
 'mapPiece',true,'mapRegionId',chosen.region_id,'pieceNumber',chosen.piece_number,'pieceCount',chosen.piece_count);
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.process_title_queue()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;n integer:=0;
begin
 for r in select user_id from app_private.title_dirty order by user_id limit 100 for update skip locked loop
  perform app_private.sync_player_titles(r.user_id);
  delete from app_private.title_dirty where user_id=r.user_id;n:=n+1;
 end loop;return n;
end $function$

CREATE OR REPLACE FUNCTION app_private.production_apply(p_action text, p_operation_id uuid, p_facility text, p_materials jsonb, p_return_state boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w public.player_wallets;f public.production_facilities;s app_private.production_sites;
 prev app_private.production_operations;sig jsonb;receipt jsonb;ids uuid[];n integer;v_now timestamptz;fuel bigint;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('buy','sell','start','claim','discard') or p_facility is null then raise exception 'INVALID_PRODUCTION';end if;
 if p_materials is null or jsonb_typeof(p_materials)<>'object' then raise exception 'INVALID_MATERIALS';end if;
 if p_action<>'start' and p_materials<>'{}'::jsonb then raise exception 'INVALID_MATERIALS';end if;
 sig:=jsonb_build_object('action',p_action,'facility',p_facility,'materials',p_materials);
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=u for update;
 select * into prev from app_private.production_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return (case when p_return_state then app_private.production_state() else '{}'::jsonb end)||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 if p_action='buy' then
  select * into f from public.production_facilities where id=p_facility for share;
  if not found then raise exception 'PRODUCTION_NOT_FOUND';end if;
  if not f.enabled then raise exception 'PRODUCTION_UNAVAILABLE';end if;
 if w.gold<f.price then raise exception 'INSUFFICIENT_GOLD';end if;
  v_now:=clock_timestamp();
  insert into app_private.production_sites(user_id,facility_id) values(u,f.id) returning * into s;
  update public.player_wallets set gold=gold-f.price,updated_at=v_now where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','production:'||f.id,-f.price);
  receipt:=jsonb_build_object('action','buy','facility',f.id,'siteId',s.id,'count',1);
 else
  s:=app_private.production_site(p_facility);
  select * into s from app_private.production_sites where id=s.id and user_id=u for update;
  select * into f from public.production_facilities where id=s.facility_id for share;
  v_now:=clock_timestamp();
  if p_action='sell' then
   if s.started_at is not null then raise exception 'PRODUCTION_BUSY';end if;
   if w.gold::bigint+(f.price/2)>1000000000 then raise exception 'GOLD_LIMIT';end if;
   delete from app_private.production_sites where id=s.id and user_id=u;
   update public.player_wallets set gold=gold+(f.price/2),updated_at=v_now where user_id=u;
   insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
    values(u,p_operation_id,'sell','production:'||f.id,f.price/2);
   receipt:=jsonb_build_object('action','sell','facility',f.id,'siteId',s.id,'gold',f.price/2,'count',1);
  elsif p_action='start' then
   if not f.enabled then raise exception 'PRODUCTION_UNAVAILABLE';end if;
   if s.started_at is not null then raise exception 'PRODUCTION_BUSY';end if;
   if app_private.production_active_count()>=4 then raise exception 'PRODUCTION_ACTIVE_LIMIT';end if;
   if (select count(*) from jsonb_each(p_materials)) not between 1 and 100 then raise exception 'INVALID_MATERIALS';end if;
   if exists(select 1 from jsonb_each(p_materials) e where jsonb_typeof(e.value)<>'number' or e.value::text !~ '^[1-9][0-9]{0,2}$') then raise exception 'INVALID_MATERIALS';end if;
   if (select sum(value::integer) from jsonb_each_text(p_materials))<>f.input_count then raise exception 'INVALID_MATERIAL_COUNT';end if;
   select array_agg(p.id order by p.id) into ids from jsonb_each_text(p_materials) e
   cross join lateral(select c.id from public.player_collectibles c join public.collectible_species cs on cs.id=c.species_id
    where c.user_id=u and c.species_id=e.key and cs.kind::text=f.kind and c.sold_at is null and c.consumed_at is null
    and c.tank_id is null and c.escrow_gift_id is null order by c.id limit e.value::integer)p;
   if coalesce(cardinality(ids),0)<>f.input_count then raise exception 'INSUFFICIENT_MATERIALS';end if;
   perform 1 from public.player_collectibles where user_id=u and id=any(ids) order by id for update;
   select count(*) into n from public.player_collectibles c join public.collectible_species cs on cs.id=c.species_id
    where c.user_id=u and c.id=any(ids) and cs.kind::text=f.kind and c.sold_at is null and c.consumed_at is null and c.tank_id is null and c.escrow_gift_id is null;
   if n<>f.input_count then raise exception 'INSUFFICIENT_MATERIALS';end if;
   v_now:=clock_timestamp();
   update public.player_collectibles set sold_at=v_now,consumed_at=v_now where user_id=u and id=any(ids);
   update app_private.production_sites set started_at=v_now,completes_at=v_now+make_interval(mins=>f.production_minutes),
    expires_at=v_now+make_interval(mins=>f.production_minutes+f.storage_minutes),run_output=f.output_count where user_id=u and id=s.id;
   receipt:=jsonb_build_object('action','start','facility',f.id,'siteId',s.id,'consumedIds',ids);
  else
   if s.started_at is null then raise exception 'PRODUCTION_IDLE';end if;
   if p_action='claim' then
    if v_now<s.completes_at then raise exception 'PRODUCTION_NOT_READY';end if;
    if v_now>=s.expires_at then raise exception 'PRODUCTION_EXPIRED';end if;
    fuel:=coalesce((w.inventory->>'fuel')::bigint,0)+s.run_output;
    if fuel>1000000000 then raise exception 'FUEL_LIMIT';end if;
    update public.player_wallets set inventory=jsonb_set(inventory,'{fuel}',to_jsonb(fuel::integer)),updated_at=v_now where user_id=u;
   elsif v_now<s.expires_at then raise exception 'PRODUCTION_NOT_EXPIRED';end if;
   receipt:=jsonb_build_object('action',p_action,'facility',f.id,'siteId',s.id,'fuel',case when p_action='claim' then s.run_output else 0 end);
   update app_private.production_sites set started_at=null,completes_at=null,expires_at=null,run_output=null where user_id=u and id=s.id;
  end if;
 end if;
 insert into app_private.production_operations(user_id,operation_id,signature,receipt) values(u,p_operation_id,sig,receipt);
 return (case when p_return_state then app_private.production_state() else '{}'::jsonb end)||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.production_bulk_action(p_action text, p_operation_id uuid, p_steps jsonb, p_allow_valuable boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();sig jsonb;prev app_private.production_operations;step jsonb;result jsonb;receipt jsonb;
 total_fuel integer:=0;n integer;site app_private.production_sites;normalized jsonb:='[]'::jsonb;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('start','claim','discard') then raise exception 'INVALID_PRODUCTION';end if;
 if p_steps is null or jsonb_typeof(p_steps)<>'array' then raise exception 'INVALID_PRODUCTION';end if;
 n:=jsonb_array_length(p_steps);
 if n not between 1 and 1000 then raise exception 'INVALID_PRODUCTION';end if;
 if exists(select 1 from jsonb_array_elements(p_steps) e where jsonb_typeof(e)<>'object'
  or jsonb_typeof(e->'facility') is distinct from 'string' or jsonb_typeof(e->'materials') is distinct from 'object') then raise exception 'INVALID_PRODUCTION';end if;
 if (select count(distinct e->>'facility') from jsonb_array_elements(p_steps)e)<>n then raise exception 'INVALID_PRODUCTION';end if;
 sig:=jsonb_build_object('action','bulk_'||p_action,'steps',p_steps,'allowValuable',coalesce(p_allow_valuable,false));
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=u for update;
 select * into prev from app_private.production_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.production_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 for step in select e from jsonb_array_elements(p_steps)e loop
  site:=app_private.production_site(step->>'facility');
  normalized:=normalized||jsonb_build_array(step||jsonb_build_object('facility',site.id,'catalog',site.facility_id));
 end loop;
 if (select count(distinct e->>'facility') from jsonb_array_elements(normalized)e)<>n then raise exception 'INVALID_PRODUCTION';end if;
 if p_action='start' and not coalesce(p_allow_valuable,false) and exists(
  select 1 from jsonb_array_elements(p_steps)e cross join lateral jsonb_object_keys(e->'materials') m(id)
  join public.collectible_species cs on cs.id=m.id where cs.rarity in ('epic','mythic')
 ) then raise exception 'VALUABLE_MATERIAL_CONFIRM_REQUIRED';end if;
 for step in select e from jsonb_array_elements(normalized)e join public.production_facilities f on f.id=e->>'catalog' order by f.price,f.id,e->>'facility' loop
  result:=app_private.production_apply(p_action,gen_random_uuid(),step->>'facility',step->'materials',false);
  total_fuel:=total_fuel+coalesce((result->'receipt'->>'fuel')::integer,0);
 end loop;
 receipt:=jsonb_build_object('action','bulk_'||p_action,'count',n,'fuel',total_fuel);
 insert into app_private.production_operations(user_id,operation_id,signature,receipt) values(u,p_operation_id,sig,receipt);
 return app_private.production_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.production_materials(p_facility text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();k text;result jsonb;site app_private.production_sites;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 site:=app_private.production_site(p_facility);
 select kind into k from public.production_facilities where id=site.facility_id;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.sell_price,q.name,q.id),'[]'::jsonb) into result from (
  select s.id,s.name,s.thumbnail_path,s.rarity,s.sell_price,count(*)::integer available
  from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
  where c.user_id=u and c.sold_at is null and c.consumed_at is null and c.escrow_gift_id is null and c.tank_id is null and s.kind::text=k
  group by s.id
 )q;
 return result;
end $function$

CREATE OR REPLACE FUNCTION app_private.production_purchase(p_facility text, p_quantity integer, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();w public.player_wallets;f public.production_facilities;prev app_private.production_operations;
 sig jsonb;receipt jsonb;ids uuid[];total bigint;v_now timestamptz;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_facility is null or p_quantity is null or p_quantity not between 1 and 100 then raise exception 'INVALID_PRODUCTION_QUANTITY';end if;
 sig:=jsonb_build_object('action','purchase','facility',p_facility,'quantity',p_quantity);
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=u for update;
 select * into prev from app_private.production_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.production_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 select * into f from public.production_facilities where id=p_facility for share;
 if not found then raise exception 'PRODUCTION_NOT_FOUND';end if;
 if not f.enabled then raise exception 'PRODUCTION_UNAVAILABLE';end if;
 total:=f.price::bigint*p_quantity;
 if w.gold<total then raise exception 'INSUFFICIENT_GOLD';end if;
 v_now:=clock_timestamp();
 with purchased as(insert into app_private.production_sites(user_id,facility_id)
  select u,f.id from generate_series(1,p_quantity) returning id) select array_agg(id order by id) into ids from purchased;
 update public.player_wallets set gold=gold-total,updated_at=v_now where user_id=u;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','production:'||f.id,-total);
 receipt:=jsonb_build_object('action','purchase','facility',f.id,'siteIds',ids,'count',p_quantity);
 insert into app_private.production_operations(user_id,operation_id,signature,receipt) values(u,p_operation_id,sig,receipt);
 return app_private.production_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.production_site(p_reference text)
 RETURNS app_private.production_sites
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();s app_private.production_sites;n integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
  select * into s from app_private.production_sites where id=p_reference::uuid and user_id=u;
  if not found then raise exception 'PRODUCTION_NOT_OWNED';end if;
 else
  -- Old clients may address a catalog kind only while it identifies one site.
  select count(*) into n from app_private.production_sites where user_id=u and facility_id=p_reference;
  if n=0 then raise exception 'PRODUCTION_NOT_OWNED';end if;
  if n>1 then raise exception 'PRODUCTION_SITE_REQUIRED';end if;
  select * into s from app_private.production_sites where user_id=u and facility_id=p_reference;
 end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION app_private.profile_fishing_rarity(p_profile jsonb)
 RETURNS game_rarity
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare roll integer:=floor(random()*10000);
begin
 if p_profile is null then raise exception 'INVALID_BAIT';end if;
 if p_profile->>'effect_kind'='alternating' then return app_private.consume_bait_cycle();end if;
 if roll<(p_profile->>'mythic_bp')::integer then return 'mythic';end if;
 if roll<(p_profile->>'mythic_bp')::integer+(p_profile->>'epic_bp')::integer then return 'epic';end if;
 if roll<(p_profile->>'mythic_bp')::integer+(p_profile->>'epic_bp')::integer+(p_profile->>'rare_bp')::integer then return 'rare';end if;
 return 'common';
end $function$

CREATE OR REPLACE FUNCTION app_private.publish_fishing_showcase(p_operation_id uuid, p_caption text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();existing uuid;p app_private.prepared_fishing_casts;a public.fishing_attempts;result_id uuid;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_caption is null or char_length(btrim(p_caption))>200 then raise exception 'INVALID_SHOWCASE';end if;
 perform pg_advisory_xact_lock(hashtextextended('showcase:'||u::text||':'||p_operation_id::text,0));
 select id into existing from public.fishing_showcase_posts where author_id=u and operation_id=p_operation_id;
 if found then return existing;end if;
 select * into p from app_private.prepared_fishing_casts where user_id=u and operation_id=p_operation_id;
 if not found then raise exception 'CATCH_NOT_SHAREABLE';end if;
 select * into a from public.fishing_attempts where user_id=u and operation_id=p_operation_id;
 if not found or p.finished_at is null or not p.eligible or a.rarity is null or a.rarity not in ('epic','mythic')
 or p.result->'attempt'->'species'->>'id' is null
 or p.result->'attempt'->'species'->>'rarity' is distinct from a.rarity::text
 then raise exception 'CATCH_NOT_SHAREABLE';end if;
 insert into public.fishing_showcase_posts(author_id,operation_id,caption,species,rarity,region_name,caught_at,first_discovery,render_version)
 values(u,p_operation_id,btrim(p_caption),p.result->'attempt'->'species',a.rarity,
 (select name from public.regions where id=p.region_id),a.created_at,
 coalesce((p.result->'attempt'->>'firstDiscovery')::boolean,false),1) returning id into result_id;
 return result_id;
end $function$

CREATE OR REPLACE FUNCTION app_private.quest_period(p_kind text, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p jsonb;q jsonb;entries jsonb:='[]'::jsonb;fuel integer;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 p:=app_private.base_quest_period(p_kind,p_now);
 for q in select value from jsonb_array_elements(p->'quests') loop
  fuel:=case when p_kind='daily' and q->>'id' in ('post','depart','care') then 1
   when p_kind='weekly' and q->>'id'='trade' then 3
   when p_kind='weekly' and q->>'id'='gift' then 5 else 0 end;
  entries:=entries||jsonb_build_array(q||jsonb_build_object('reward',case when fuel>0 then 0
   when p_kind='weekly' and (q->>'reward')::integer=50 then 80 else (q->>'reward')::integer end,'rewardFuel',fuel));
 end loop;
 return jsonb_set(p,'{quests}',entries);
end $function$

