 on conflict(post_id,user_id) do update set reaction=excluded.reaction;end if;
 return app_private.showcase_post_json(p);
end $function$

CREATE OR REPLACE FUNCTION app_private.react_to_collectible_gift(p_gift_id uuid, p_reaction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();g public.collectible_gifts;v_title text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_reaction is null or p_reaction not in ('thumbs_up','heart','thanks','laugh','celebrate') then raise exception 'INVALID_REACTION'; end if;
 select * into g from public.collectible_gifts where id=p_gift_id and recipient_id=v_uid for update;
 if not found then raise exception 'GIFT_NOT_FOUND'; end if;
 if g.status<>'claimed' then raise exception 'GIFT_NOT_CLAIMED'; end if;
 if g.reaction is not null then
  if g.reaction<>p_reaction then raise exception 'GIFT_ALREADY_REACTED'; end if;
  return to_jsonb(g);
 end if;
 update public.collectible_gifts set reaction=p_reaction,reacted_at=now() where id=g.id returning * into g;
 v_title:=case p_reaction when 'thumbs_up' then '따봉을 보냈어요' when 'heart' then '하트를 보냈어요' when 'thanks' then '고마움을 보냈어요' when 'laugh' then '웃음을 보냈어요' else '축하를 보냈어요' end;
 if g.sender_id is not null then
  insert into public.notifications(recipient_id,actor_id,category,kind,title,body,gift_id) values(g.sender_id,v_uid,'gift','gift_reaction',v_title,g.recipient_name||'님이 선물에 답장했어요.',g.id) on conflict do nothing;
 end if;
 return to_jsonb(g);
end $function$

CREATE OR REPLACE FUNCTION app_private.regional_bait_odds(p_bait_id text, p_region_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare b jsonb;r public.game_rarity;
begin
 if not exists(select 1 from public.fishing_baits where id=p_bait_id) then raise exception 'INVALID_BAIT';end if;
 if not exists(select 1 from public.regions where id=p_region_id) then raise exception 'REGION_NOT_FOUND';end if;
 b:=app_private.fishing_bait_balance_at(p_bait_id,statement_timestamp());
 if b is null then raise exception 'INVALID_BAIT';end if;
 if b->>'effect_kind'='alternating' then
  select next_rarity into r from app_private.bait_cycles where user_id=auth.uid();r:=coalesce(r,'common');
  return jsonb_build_object('common_bp',case when r='common' then 10000 else 0 end,'rare_bp',case when r='rare' then 10000 else 0 end,'epic_bp',0,'mythic_bp',0,'failure_bp',0,'nextRarity',r);
 end if;
 return jsonb_build_object('common_bp',b->'common_bp','rare_bp',b->'rare_bp','epic_bp',b->'epic_bp','mythic_bp',b->'mythic_bp','failure_bp',0,
  'period',b->'period','target_kinds',b->'target_kinds');
end $function$

CREATE OR REPLACE FUNCTION app_private.remove_friend(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_request public.friend_requests;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_request from public.friend_requests where id=p_request_id for update;
  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;
  if v_uid <> v_request.sender_id and v_uid <> v_request.recipient_id then raise exception 'NOT_ALLOWED'; end if;
  if v_request.status <> 'accepted' then raise exception 'FRIENDSHIP_NOT_ACTIVE'; end if;
  update public.friend_requests set status='removed',updated_at=now() where id=p_request_id;
  update public.notifications set read_at=coalesce(read_at,now()) where request_id=p_request_id;
  -- No separate unfriend notification. Existing UPDATE subscriptions update both lists.
end $function$

CREATE OR REPLACE FUNCTION app_private.reorder_aquarium_tanks(p_tank_ids uuid[], p_expected_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();actual uuid[];
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 -- Purchases take the same wallet lock, so a new tank cannot race a reorder.
 perform app_private.get_gold_wallet();
 perform 1 from public.player_wallets where user_id=u for update;
 perform app_private.aquarium_state();
 select array_agg(id order by display_order,created_at,id) into actual from public.aquarium_tanks where user_id=u;
 if p_tank_ids is null or cardinality(p_tank_ids)<>cardinality(actual)
  or exists(select 1 from unnest(p_tank_ids) t(id) where id is null)
  or (select count(distinct id) from unnest(p_tank_ids)t(id))<>cardinality(actual)
  or exists(select 1 from unnest(p_tank_ids)t(id) where not(id=any(actual))) then raise exception 'INVALID_TANK_ORDER';end if;
 -- An identical retry succeeds; a stale edit cannot overwrite a newer order.
 if p_tank_ids=actual then return app_private.aquarium_state();end if;
 if p_expected_ids is distinct from actual then raise exception 'TANK_ORDER_CHANGED';end if;
 update public.aquarium_tanks t set display_order=p.position-1
 from unnest(p_tank_ids) with ordinality p(id,position) where t.id=p.id and t.user_id=u;
 return app_private.aquarium_state();
end$function$

CREATE OR REPLACE FUNCTION app_private.require_aquarium_friend(p_owner uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_owner is null or p_owner=auth.uid() then raise exception 'FRIENDSHIP_REQUIRED';end if;
 perform 1 from public.friend_requests where status='accepted' and
 ((sender_id=auth.uid() and recipient_id=p_owner) or (recipient_id=auth.uid() and sender_id=p_owner)) for share;
 if not found then raise exception 'FRIENDSHIP_REQUIRED';end if;
end $function$

CREATE OR REPLACE FUNCTION app_private.resize_aquarium_fish(p_collectible_id uuid, p_tank_id uuid, p_scale numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();item public.player_collectibles;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_scale is null or not(p_scale between .5 and 2) then raise exception 'INVALID_TRANSFORM';end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=u) then raise exception 'TANK_NOT_FOUND';end if;
 select * into item from public.player_collectibles where id=p_collectible_id and user_id=u and tank_id=p_tank_id and sold_at is null and consumed_at is null and escrow_gift_id is null for update;
 if not found then raise exception 'COLLECTIBLE_NOT_FOUND';end if;
 if not exists(select 1 from public.collectible_species where id=item.species_id and kind='fish') then raise exception 'INVALID_ITEM';end if;
 update public.player_collectibles set scale=p_scale where id=item.id;
 return jsonb_build_object('id',item.id,'scale',p_scale);
end $function$

CREATE OR REPLACE FUNCTION app_private.resolve_fishing(p_bait_id text, p_roll integer)
 RETURNS game_rarity
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare b public.fishing_baits;
begin
 if p_roll is null or p_roll<0 or p_roll>=10000 then raise exception 'INVALID_ROLL'; end if;
 select * into b from public.fishing_baits where id=p_bait_id;
 if not found then raise exception 'INVALID_BAIT'; end if;
 if b.effect_kind='decoration' then raise exception 'DECORATION_NOT_READY'; end if;
 if p_roll<b.mythic_bp then return 'mythic'; end if;
 if p_roll<b.mythic_bp+b.epic_bp then return 'epic'; end if;
 if p_roll<b.mythic_bp+b.epic_bp+b.rare_bp then return 'rare'; end if;
 if p_roll<b.mythic_bp+b.epic_bp+b.rare_bp+b.common_bp then return 'common'; end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION app_private.resolve_regional_fishing(p_bait_id text, p_region_id text, p_roll integer)
 RETURNS game_rarity
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare o jsonb;v_m integer;v_e integer;v_r integer;v_c integer;
begin
 if p_roll is null or p_roll<0 or p_roll>=10000 then raise exception 'INVALID_ROLL';end if;
 o:=app_private.regional_bait_odds(p_bait_id,p_region_id);
 v_m:=(o->>'mythic_bp')::integer;v_e:=(o->>'epic_bp')::integer;v_r:=(o->>'rare_bp')::integer;v_c:=(o->>'common_bp')::integer;
 if p_roll<v_m then return 'mythic';elsif p_roll<v_m+v_e then return 'epic';elsif p_roll<v_m+v_e+v_r then return 'rare';elsif p_roll<v_m+v_e+v_r+v_c then return 'common';end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION app_private.respond_friend_request(p_request_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_request public.friend_requests; v_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_request from public.friend_requests where id = p_request_id for update;
  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;
  if p_action is null or p_action not in ('accept','decline','cancel') then raise exception 'INVALID_ACTION'; end if;
  if (p_action = 'cancel' and v_request.sender_id <> v_uid)
    or (p_action in ('accept','decline') and v_request.recipient_id <> v_uid) then raise exception 'NOT_ALLOWED'; end if;
  if v_request.status <> 'pending' then raise exception 'REQUEST_ALREADY_HANDLED'; end if;
  update public.friend_requests set status = case p_action when 'accept' then 'accepted' when 'decline' then 'declined' else 'cancelled' end,
    updated_at = now() where id = p_request_id;
  update public.notifications set read_at = coalesce(read_at,now()) where request_id = p_request_id and kind = 'friend_request';
  if p_action = 'accept' then
    select nickname into v_name from public.player_profiles where id = v_uid;
    insert into public.notifications(recipient_id,actor_id,category,kind,title,body,request_id)
      values(v_request.sender_id,v_uid,'friend','friend_accepted',v_name || '님과 친구가 됐어요','친구 목록에서 확인해보세요.',p_request_id);
  end if;
end $function$

CREATE OR REPLACE FUNCTION app_private.savings_action(p_action text, p_operation_id uuid, p_account_id uuid DEFAULT NULL::uuid, p_term_days integer DEFAULT NULL::integer, p_daily_amount integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_now timestamptz;v_account public.shell_savings;v_previous app_private.savings_operations;
 v_signature jsonb;v_status text;v_payout integer:=0;v_bonus integer:=0;v_gold integer;v_receipt jsonb;v_kind text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('open','deposit','withdraw') then raise exception 'INVALID_SAVINGS_ACTION';end if;
 if (p_action='open' and p_account_id is not null) or
    (p_action<>'open' and (p_account_id is null or p_term_days is not null or p_daily_amount is not null)) then raise exception 'INVALID_SAVINGS_ACTION';end if;
 v_signature:=jsonb_build_object('action',p_action,'account',p_account_id,'term',p_term_days,'daily',p_daily_amount);
 perform pg_advisory_xact_lock(hashtextextended('savings:'||v_uid::text,0));
 select * into v_previous from app_private.savings_operations where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if v_previous.signature<>v_signature then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.savings_state()||jsonb_build_object('receipt',v_previous.receipt,'replayed',true);
 end if;
 v_now:=clock_timestamp();
 if p_action='open' then
  if p_term_days is null or p_term_days not in (3,5,7) or p_daily_amount is null or p_daily_amount not between 10 and 5000 then raise exception 'INVALID_SAVINGS_PLAN';end if;
  if exists(select 1 from public.shell_savings where user_id=v_uid and closed_at is null) then raise exception 'SAVINGS_ALREADY_OPEN';end if;
 else
  select * into v_account from public.shell_savings where id=p_account_id and user_id=v_uid for update;
  if not found then raise exception 'SAVINGS_NOT_FOUND';end if;
  if v_account.closed_at is not null then raise exception 'SAVINGS_CLOSED';end if;
 end if;
 insert into public.player_wallets(user_id) values(v_uid) on conflict do nothing;
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 -- Re-read time after any wallet lock wait, including at exact deadlines.
 v_now:=clock_timestamp();
 if p_action<>'open' then
  v_status:=app_private.savings_payload(v_account,v_now)->>'status';
  if p_action='deposit' and v_status<>'due' then
   if v_status='missed' then raise exception 'SAVINGS_MISSED';else raise exception 'SAVINGS_NOT_DUE';end if;
  end if;
 end if;
 if p_action='open' then
  if v_gold<p_daily_amount then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into public.shell_savings(user_id,term_days,daily_amount,started_at) values(v_uid,p_term_days,p_daily_amount,v_now) returning * into v_account;
  update public.player_wallets set gold=gold-p_daily_amount,updated_at=v_now where user_id=v_uid;
 elsif p_action='deposit' then
  if v_gold<v_account.daily_amount then raise exception 'INSUFFICIENT_GOLD';end if;
  update public.shell_savings set paid_count=paid_count+1 where id=v_account.id returning * into v_account;
  update public.player_wallets set gold=gold-v_account.daily_amount,updated_at=v_now where user_id=v_uid;
 else
  v_kind:=case v_status when 'matured' then 'matured' when 'missed' then 'missed' else 'cancelled' end;
  if v_kind='matured' then v_bonus:=(v_account.daily_amount*v_account.paid_count*(case v_account.term_days when 3 then 20 when 5 then 25 else 30 end))/100;end if;
  v_payout:=v_account.daily_amount*v_account.paid_count+v_bonus;
  if v_gold::bigint+v_payout>1000000000 then raise exception 'GOLD_LIMIT';end if;
  update public.player_wallets set gold=gold+v_payout,updated_at=v_now where user_id=v_uid;
  update public.shell_savings set closed_at=v_now,close_kind=v_kind,payout=v_payout where id=v_account.id returning * into v_account;
 end if;
 v_receipt:=jsonb_build_object('action',p_action,'accountId',v_account.id,'paidCount',v_account.paid_count,'payout',v_payout,'bonus',v_bonus,'closeKind',v_kind);
 insert into app_private.savings_operations(user_id,operation_id,account_id,signature,receipt) values(v_uid,p_operation_id,v_account.id,v_signature,v_receipt);
 return app_private.savings_state()||jsonb_build_object('receipt',v_receipt,'replayed',false);
end;
$function$

CREATE OR REPLACE FUNCTION app_private.savings_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_now timestamptz:=clock_timestamp();v_account jsonb;v_history jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 select app_private.savings_payload(a,v_now) into v_account from public.shell_savings a where a.user_id=v_uid and a.closed_at is null;
 select coalesce(jsonb_agg(q.payload),'[]'::jsonb) into v_history from (
  select app_private.savings_payload(a,v_now) payload from public.shell_savings a
  where a.user_id=v_uid and a.closed_at is not null order by a.closed_at desc,a.id limit 5
 ) q;
 return jsonb_build_object('account',v_account,'history',v_history,'serverNow',v_now,
  'gold',coalesce((select gold from public.player_wallets where user_id=v_uid),0));
end;
$function$

CREATE OR REPLACE FUNCTION app_private.sell_collectibles(p_collectible_ids uuid[], p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_ids uuid[]; v_key text; v_wallet public.player_wallets;
 v_previous public.gold_transactions; v_count integer; v_price bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_operation_id is null or coalesce(cardinality(p_collectible_ids),0) not between 1 and 100 then raise exception 'INVALID_TRADE'; end if;
 select array_agg(id order by id) into v_ids from (select distinct unnest(p_collectible_ids) as id) q;
 if cardinality(v_ids)<>cardinality(p_collectible_ids) or array_position(v_ids,null) is not null then raise exception 'INVALID_TRADE'; end if;
 v_key:='collectibles:'||array_to_string(v_ids,',');
 perform app_private.get_gold_wallet();
 -- Same lock order as other gold operations: wallet, then collectibles ordered by ID.
 select * into v_wallet from public.player_wallets where user_id=v_uid for update;
 select * into v_previous from public.gold_transactions where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if v_previous.action<>'sell' or v_previous.item_id is distinct from v_key then raise exception 'OPERATION_CONFLICT'; end if;
  return app_private.get_gold_wallet()||jsonb_build_object('delta',0);
 end if;
 perform 1 from public.player_collectibles where user_id=v_uid and id=any(v_ids) order by id for update;
 select count(*),coalesce(sum(s.sell_price),0) into v_count,v_price
 from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.user_id=v_uid and c.id=any(v_ids) and c.sold_at is null and c.escrow_gift_id is null and s.kind in ('fish','trash','decoration') and s.sell_price>0;
 if v_count<>cardinality(v_ids) then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 if v_wallet.gold::bigint+v_price>1000000000 then raise exception 'GOLD_LIMIT'; end if;
 update public.player_collectibles set sold_at=now(),tank_id=null where user_id=v_uid and id=any(v_ids);
 update public.player_wallets set gold=gold+v_price::integer,updated_at=now() where user_id=v_uid;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'sell',v_key,v_price::integer);
 return app_private.get_gold_wallet()||jsonb_build_object('delta',v_price);
end $function$

CREATE OR REPLACE FUNCTION app_private.send_collectible_gift(p_recipient_id uuid, p_collectible_ids uuid[], p_message text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_ids uuid[]; g public.collectible_gifts; v_count integer; v_species text; v_name text; v_recipient text; v_message text:=btrim(coalesce(p_message,''));
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_recipient_id is null or p_recipient_id=v_uid then raise exception 'INVALID_RECIPIENT'; end if;
 if p_operation_id is null or coalesce(cardinality(p_collectible_ids),0) not between 1 and 20 or char_length(v_message)>300 then raise exception 'INVALID_GIFT'; end if;
 select array_agg(id order by id) into v_ids from(select distinct unnest(p_collectible_ids) as id) q;
 if cardinality(v_ids)<>cardinality(p_collectible_ids) or array_position(v_ids,null) is not null then raise exception 'INVALID_GIFT'; end if;
 perform pg_advisory_xact_lock(hashtextextended('gift-send:'||v_uid::text,0));
 select * into g from public.collectible_gifts where sender_id=v_uid and operation_id=p_operation_id;
 if found then
  if g.recipient_id is distinct from p_recipient_id or g.collectible_ids<>v_ids or g.message<>v_message then raise exception 'OPERATION_CONFLICT'; end if;
  return to_jsonb(g);
 end if;
 perform 1 from public.friend_requests where status='accepted' and ((sender_id=v_uid and recipient_id=p_recipient_id) or(sender_id=p_recipient_id and recipient_id=v_uid)) for share;
 if not found then raise exception 'GIFT_FRIEND_REQUIRED'; end if;
 if (select count(*) from public.collectible_gifts where sender_id=v_uid and created_at>now()-interval '1 minute')>=5 then raise exception 'GIFT_RATE_LIMIT'; end if;
 select nickname into v_name from public.player_profiles where id=v_uid;
 select nickname into v_recipient from public.player_profiles where id=p_recipient_id;
 if v_name is null or v_recipient is null then raise exception 'INVALID_RECIPIENT'; end if;
 perform 1 from public.player_collectibles where user_id=v_uid and id=any(v_ids) order by id for update;
 select count(*),min(c.species_id) into v_count,v_species from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.user_id=v_uid and c.id=any(v_ids) and c.sold_at is null and c.escrow_gift_id is null and s.kind in ('fish','trash','decoration');
 if v_count<>cardinality(v_ids) or (select count(distinct species_id) from public.player_collectibles where id=any(v_ids))<>1 then raise exception 'COLLECTIBLE_NOT_FOUND'; end if;
 insert into public.collectible_gifts(sender_id,recipient_id,sender_name,recipient_name,operation_id,collectible_ids,species,quantity,message)
 values(v_uid,p_recipient_id,v_name,v_recipient,p_operation_id,v_ids,app_private.species_payload(v_species),v_count,v_message) returning * into g;
 -- Recipient owns reserved items, so deletion of the sender cannot destroy the gift.
 update public.player_collectibles set tank_id=null,user_id=p_recipient_id,escrow_gift_id=g.id,position_x=null,position_y=null where id=any(v_ids);
 insert into public.notifications(recipient_id,actor_id,category,kind,title,body,gift_id)
 values(p_recipient_id,v_uid,'gift','gift_received','선물을 받았습니다',v_name||'님이 '||(g.species->>'name')||' ×'||v_count||'를 보냈어요.',g.id);
 return to_jsonb(g);
end $function$

CREATE OR REPLACE FUNCTION app_private.send_friend_request(p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_target uuid; v_id uuid; v_name text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if upper(trim(p_code)) !~ '^[A-F0-9]{12}$' then raise exception 'INVALID_FRIEND_CODE'; end if;
  select id into v_target from public.player_profiles where friend_code = upper(trim(p_code));
  if v_target is null then raise exception 'PLAYER_NOT_FOUND'; end if;
  if v_target = v_uid then raise exception 'CANNOT_FRIEND_SELF'; end if;
  select nickname into v_name from public.player_profiles where id = v_uid;
  if v_name is null then raise exception 'NICKNAME_REQUIRED'; end if;
  -- Serialize a sender's rate limit checks and opposite-direction operations for a pair.
  perform pg_advisory_xact_lock(hashtextextended('sender:' || v_uid::text, 0));
  perform pg_advisory_xact_lock(hashtextextended(least(v_uid, v_target)::text || greatest(v_uid, v_target)::text, 1));
  if exists(select 1 from public.friend_requests where least(sender_id,recipient_id) = least(v_uid,v_target)
    and greatest(sender_id,recipient_id) = greatest(v_uid,v_target) and status in ('pending','accepted')) then
    raise exception 'RELATIONSHIP_EXISTS';
  end if;
  if (select count(*) from public.friend_requests where sender_id = v_uid and created_at > now() - interval '1 minute') >= 5
    or (select count(*) from public.friend_requests where sender_id = v_uid and status = 'pending') >= 30
    or exists(select 1 from public.friend_requests where least(sender_id,recipient_id) = least(v_uid,v_target)
      and greatest(sender_id,recipient_id) = greatest(v_uid,v_target) and updated_at > now() - interval '1 minute') then
    raise exception 'FRIEND_RATE_LIMIT';
  end if;
  insert into public.friend_requests(sender_id,recipient_id) values(v_uid,v_target) returning id into v_id;
  insert into public.notifications(recipient_id,actor_id,category,kind,title,body,request_id)
    values(v_target,v_uid,'friend','friend_request',v_name || '님의 친구 요청','함께 퐁당섬에서 낚시해요.',v_id);
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION app_private.send_player_friend_request(p_player uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_code text;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 select friend_code into v_code from public.player_profiles where id=p_player;
 if v_code is null then raise exception 'PLAYER_NOT_FOUND';end if;
 return app_private.send_friend_request(v_code);
end $function$

CREATE OR REPLACE FUNCTION app_private.send_welcome_gift(p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare gift uuid; bait_gift uuid; player_name text;
begin
 -- Do not turn an uncorrected direct credit into a second payment.
 if exists(select 1 from public.gold_transactions where user_id=p_user_id and item_id='welcome:500')
 and not exists(select 1 from public.gold_transactions where user_id=p_user_id and item_id='welcome:500:reversal' and delta=-500)
 then raise exception 'WELCOME_DIRECT_CREDIT_REQUIRES_REVERSAL';end if;
 select nickname into strict player_name from public.player_profiles where id=p_user_id;
 insert into public.collectible_gifts(sender_name,recipient_id,recipient_name,operation_id,collectible_ids,species,quantity,message,source,reward_kind,reward_id)
 values('퐁당섬 운영자',p_user_id,player_name,gen_random_uuid(),'{}'::uuid[],
 jsonb_build_object('id','welcome-gold','name','모험 응원 골드'),500,
 '첫 모험을 응원하는 500골드 선물이에요. 원하실 때 받아주세요!','system','gold','welcome')
 on conflict do nothing returning id into gift;
 if gift is not null then
  insert into public.notifications(recipient_id,category,kind,title,body,gift_id)
  values(p_user_id,'gift','gift_received','운영자의 선물이 도착했어요!','500골드 선물이에요. 선물함에서 원하실 때 받아주세요.',gift);
 end if;
 insert into public.collectible_gifts(sender_name,recipient_id,recipient_name,operation_id,collectible_ids,species,quantity,message,source,reward_kind,reward_id)
 select '퐁당섬 운영자',p_user_id,player_name,gen_random_uuid(),'{}'::uuid[],
 jsonb_build_object('id','welcome-bait','name',b.name,'thumbnail_path',b.image_path),5,
 '첫 낚시를 위한 지렁이 미끼 5개를 준비했어요. 선물함에서 받아주세요!','system','bait','bait'
 from public.fishing_baits b where b.id='bait'
 on conflict do nothing returning id into bait_gift;
 if bait_gift is not null then
  insert into public.notifications(recipient_id,category,kind,title,body,gift_id)
  values(p_user_id,'gift','gift_received','첫 낚시를 위한 미끼가 도착했어요!','환영 미끼 5개를 선물함에서 받아주세요.',bait_gift);
 end if;
 return gift;
end $function$

CREATE OR REPLACE FUNCTION app_private.set_collectible_display_layer(p_collectible_id uuid, p_tank_id uuid, p_layer integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();item public.player_collectibles;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_layer is not null and not(p_layer between 0 and 800) then raise exception 'INVALID_LAYER';end if;
 if not exists(select 1 from public.aquarium_tanks where id=p_tank_id and user_id=u) then raise exception 'TANK_NOT_FOUND';end if;
 select * into item from public.player_collectibles
