end $function$

CREATE OR REPLACE FUNCTION app_private.set_exchange_listing_like(p_listing_id uuid, p_liked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();l public.exchange_listings;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_liked is null then raise exception 'INVALID_EXCHANGE';end if;
 select * into l from public.exchange_listings where id=p_listing_id and side='sell' and status in ('active','completed') for share;
 if not found then raise exception 'EXCHANGE_UNAVAILABLE';end if;
 perform pg_advisory_xact_lock(hashtextextended('exchange-like:'||p_listing_id::text||':'||u::text,0));
 if p_liked then insert into public.exchange_listing_likes(listing_id,user_id) values(l.id,u) on conflict do nothing;
 else delete from public.exchange_listing_likes where listing_id=l.id and user_id=u;end if;
 return jsonb_build_object('liked',p_liked,'like_count',(select count(*) from public.exchange_listing_likes where listing_id=l.id));
end;
$function$

CREATE OR REPLACE FUNCTION app_private.set_map_piece_test_count(p_region_id text, p_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();total integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if not exists(select 1 from auth.users where id=u and lower(email)='1@1.com') then raise exception 'TEST_ACCOUNT_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||u::text,0));
 select b.piece_count into total from public.fishing_map_blueprints b join public.regions r on r.id=b.region_id
 where b.region_id=p_region_id and b.enabled and r.requires_map_fragment for share of b,r;
 if not found then raise exception 'MAP_BLUEPRINT_NOT_FOUND';end if;
 if p_count is null or p_count<0 or p_count>total then raise exception 'INVALID_MAP_PIECE_COUNT';end if;
 -- An entered count represents the first N fixed pieces, including resetting to zero.
 delete from app_private.player_fishing_map_pieces where user_id=u and region_id=p_region_id and piece_number>p_count;
 insert into app_private.player_fishing_map_pieces(user_id,region_id,piece_number)
 select u,p_region_id,n from generate_series(1,p_count) n on conflict do nothing;
 if p_count=total then
  insert into public.player_map_fragments(user_id,region_id) values(u,p_region_id) on conflict do nothing;
 else
  delete from public.player_map_fragments where user_id=u and region_id=p_region_id;
  update public.player_navigation set region_id='pongdang' where user_id=u and region_id=p_region_id;
 end if;
 return app_private.region_map();
end $function$

CREATE OR REPLACE FUNCTION app_private.set_player_avatar(p_path text)
 RETURNS player_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_profile public.player_profiles;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  perform app_private.sync_player_profile();
  if p_path is not null then
    if p_path !~ ('^' || v_uid::text || '/[a-f0-9-]{36}\.webp$') then raise exception 'INVALID_AVATAR_PATH'; end if;
    if not exists(select 1 from storage.objects where bucket_id='avatars' and name=p_path and metadata->>'mimetype'='image/webp') then
      raise exception 'AVATAR_NOT_FOUND';
    end if;
  end if;
  update public.player_profiles set avatar_path=p_path where id=v_uid returning * into v_profile;
  return v_profile;
end $function$

CREATE OR REPLACE FUNCTION app_private.set_region_test_lock(p_region_id text, p_locked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_region public.regions;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if not coalesce((select test_lock_controls from app_private.region_settings where id),false) then raise exception 'TEST_CONTROLS_DISABLED'; end if;
 if p_locked is null then raise exception 'INVALID_LOCK_STATE'; end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||v_uid::text,0));
 select * into v_region from public.regions where id=p_region_id;
 if not found then raise exception 'REGION_NOT_FOUND'; end if;
 if not v_region.requires_map_fragment then raise exception 'DEFAULT_REGION_ALWAYS_OPEN'; end if;
 if p_locked then
  delete from public.player_map_fragments where user_id=v_uid and region_id=p_region_id;
  update public.player_navigation set region_id='pongdang' where user_id=v_uid and region_id=p_region_id;
 else
  insert into public.player_map_fragments(user_id,region_id) values(v_uid,p_region_id) on conflict do nothing;
 end if;
 return app_private.region_map();
end $function$

CREATE OR REPLACE FUNCTION app_private.settle_arcade_weeks(p_now timestamp with time zone DEFAULT clock_timestamp())
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 current_week date:=date_trunc('week',p_now at time zone 'Asia/Seoul')::date;
 first_week date;batch record;winner record;gift uuid;reward integer;issued integer:=0;player_name text;
begin
 if p_now is null then raise exception 'INVALID_SETTLEMENT_TIME';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('arcade-weekly-settlement',0)) then return 0;end if;
 select s.first_week into first_week from app_private.arcade_reward_settings s where id;
 -- Persist even empty weeks, catch up missed jobs, never settle the open week.
 for batch in
  select games.game,period.week_start::date week_start
  from generate_series(first_week::timestamp,(current_week-7)::timestamp,interval '7 days') period(week_start)
  cross join (values('shadow'),('memory')) games(game)
  where not exists(select 1 from app_private.arcade_weekly_batches b where b.game=games.game and b.week_start=period.week_start::date)
  and ((period.week_start::date+7)::timestamp at time zone 'Asia/Seoul')<=p_now-interval '1 minute'
  order by period.week_start,games.game limit 16
 loop
  insert into app_private.arcade_weekly_batches(game,week_start) values(batch.game,batch.week_start);
  for winner in select * from app_private.arcade_weekly_rankings(batch.game,batch.week_start) order by rank loop
   select nickname into player_name from public.player_profiles where id=winner.user_id;
   if not found then continue;end if;
   reward:=app_private.arcade_weekly_gold(winner.rank);
   insert into public.collectible_gifts(sender_name,recipient_id,recipient_name,operation_id,collectible_ids,species,quantity,message,source,reward_kind,reward_id)
   values('퐁당섬 운영자',winner.user_id,player_name,gen_random_uuid(),'{}'::uuid[],
    jsonb_build_object('id','arcade-weekly','name','오락실 주간 랭킹 보상','game',batch.game,'week_start',batch.week_start,'rank',winner.rank),
    reward,format('%s 주간 서버 랭킹 %s등 보상이에요. 한 주 동안 함께해 주셔서 고마워요!',case batch.game when 'shadow' then '그림자 맞추기' else '카드 짝맞추기' end,winner.rank),
    'system','gold','arcade-weekly:'||batch.game||':'||batch.week_start) returning id into gift;
   insert into app_private.arcade_weekly_rewards(game,week_start,user_id,rank,run_id,gold,gift_id)
   values(batch.game,batch.week_start,winner.user_id,winner.rank,winner.run_id,reward,gift);
   insert into public.notifications(recipient_id,category,kind,title,body,gift_id)
   values(winner.user_id,'gift','gift_received','오락실 주간 랭킹 보상이 도착했어요!',
    format('%s %s등 · %s골드를 우편함에서 받아주세요.',case batch.game when 'shadow' then '그림자 맞추기' else '카드 짝맞추기' end,winner.rank,reward),gift);
   update app_private.arcade_weekly_batches set players=players+1,total_gold=total_gold+reward where game=batch.game and week_start=batch.week_start;
   issued:=issued+1;
  end loop;
 end loop;
 return issued;
end $function$

CREATE OR REPLACE FUNCTION app_private.settle_legacy_expedition(p_action text, p_operation_id uuid, p_vessel_id text DEFAULT NULL::text, p_region_id text DEFAULT NULL::text, p_cargo jsonb DEFAULT NULL::jsonb, p_expedition_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();v public.fishing_vessels;e public.fishing_expeditions;w public.player_wallets;
 sig jsonb;prev app_private.expedition_operations;receipt jsonb;cargo record;total integer:=0;count integer;sid text;bid text;
 bonus integer;bonus_bait text;draws text[]:=array[]::text[];i integer;item uuid;results jsonb:='[]';refunds jsonb:='{}';local_discovery boolean;failed integer:=0;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in ('buy','depart','claim','instant') or p_operation_id is null then raise exception 'INVALID_EXPEDITION';end if;
 sig:=jsonb_build_object('action',p_action,'vessel',p_vessel_id,'region',p_region_id,'cargo',p_cargo,'expedition',p_expedition_id);
 perform pg_advisory_xact_lock(hashtextextended('expedition:'||u::text,0));
 select * into prev from app_private.expedition_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.expedition_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=u for update;
 if p_action in ('buy','depart') then
  select * into v from public.fishing_vessels where id=p_vessel_id;
  if not found then raise exception 'VESSEL_NOT_FOUND';end if;
 end if;
 if p_action='buy' then
  if v.price>0 and not exists(select 1 from public.player_fishing_vessels where user_id=u and vessel_id=v.id) then
   if w.gold<v.price then raise exception 'INSUFFICIENT_GOLD';end if;
   update public.player_wallets set gold=gold-v.price,updated_at=now() where user_id=u;
   insert into public.player_fishing_vessels(user_id,vessel_id) values(u,v.id);
   insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','vessel:'||v.id,-v.price);
  end if;
  receipt:=jsonb_build_object('action','buy','vesselId',v.id);
 elsif p_action='depart' then
  if v.price>0 and not exists(select 1 from public.player_fishing_vessels where user_id=u and vessel_id=v.id) then raise exception 'VESSEL_NOT_OWNED';end if;
  if exists(select 1 from public.fishing_expeditions where user_id=u and claimed_at is null) then raise exception 'EXPEDITION_ACTIVE';end if;
  if not exists(select 1 from public.regions r where r.id=p_region_id and (not r.requires_map_fragment or exists(select 1 from public.player_map_fragments f where f.user_id=u and f.region_id=r.id))) then raise exception 'REGION_LOCKED';end if;
  if p_cargo is null or jsonb_typeof(p_cargo)<>'object' then raise exception 'INVALID_CARGO';end if;
  for cargo in select key,value from jsonb_each_text(p_cargo) loop
   if not exists(select 1 from public.fishing_baits where id=cargo.key) or cargo.value !~ '^[1-9][0-9]{0,2}$' then raise exception 'INVALID_CARGO';end if;
   count:=cargo.value::integer;total:=total+count;
   if coalesce((w.inventory->>cargo.key)::integer,0)<count then raise exception 'NO_BAIT';end if;
   w.inventory:=jsonb_set(w.inventory,array[cargo.key],to_jsonb((w.inventory->>cargo.key)::integer-count));
  end loop;
  if total<v.min_baits or total>v.max_baits then raise exception 'CARGO_LIMIT';end if;
  update public.player_wallets set inventory=w.inventory,updated_at=now() where user_id=u;
  insert into public.fishing_expeditions(user_id,vessel_id,region_id,cargo,vessel_snapshot,returns_at)
   values(u,v.id,p_region_id,p_cargo,to_jsonb(v),clock_timestamp()+make_interval(mins=>v.duration_minutes)) returning * into e;
  receipt:=jsonb_build_object('action','depart','expeditionId',e.id);
 else
  perform app_private.notify_due_expeditions(p_expedition_id);
  select * into e from public.fishing_expeditions where id=p_expedition_id and user_id=u for update;
  if not found then raise exception 'EXPEDITION_NOT_FOUND';end if;
  if e.claimed_at is not null then
   receipt:=jsonb_build_object('action','claim','expeditionId',e.id,'result',e.result);
  elsif p_action='instant' then
   if not coalesce((select instant_return_enabled from app_private.expedition_settings where id),false) then raise exception 'TEST_DISABLED';end if;
   update public.fishing_expeditions set returns_at=least(returns_at,clock_timestamp()) where id=e.id;
   receipt:=jsonb_build_object('action','instant','expeditionId',e.id);
  else
   if clock_timestamp()<e.returns_at then raise exception 'EXPEDITION_NOT_READY';end if;
   v:=jsonb_populate_record(null::public.fishing_vessels,e.vessel_snapshot);
   for cargo in select key,value from jsonb_each_text(e.cargo) loop
    count:=cargo.value::integer;total:=total+count;
    for i in 1..count loop draws:=array_append(draws,cargo.key);end loop;
   end loop;
   bonus:=case when v.bonus_kind='per_ten' then least(total/10,v.bonus_count) else v.bonus_count end;
   bonus_bait:=case v.bonus_kind when 'special' then 'bait_special' when 'magnet' then 'bait_magnet' when 'candy' then 'bait_forbidden_star' when 'discovery' then 'bait_first_greeting' when 'epic' then 'bait_epic' else 'bait' end;
   if v.bonus_kind='copy' then
    select d into bonus_bait from unnest(draws) d where d not in ('bait_first_greeting','bait_epic','bait_magnet') order by random() limit 1;
    bonus_bait:=coalesce(bonus_bait,'bait');
   end if;
   for i in 1..bonus loop draws:=array_append(draws,bonus_bait);end loop;
   -- Snapshots from older departures have null for newly introduced fields.
   for i in 1..coalesce(v.bonus_basic_count,0) loop draws:=array_append(draws,'bait');end loop;
   for i in 1..cardinality(draws) loop
    bid:=draws[i];local_discovery:=i>total and v.bonus_kind='discovery';
    sid:=app_private.trap_pick(e.region_id,bid,v.bonus_kind='native',local_discovery,e.vessel_snapshot);
    if sid is null and local_discovery then bid:='bait_special';sid:=app_private.trap_pick(e.region_id,bid,false,false,e.vessel_snapshot);end if;
    if sid is null and bid='bait_first_greeting' and i<=total then
     refunds:=jsonb_set(refunds,array[bid],to_jsonb(coalesce((refunds->>bid)::integer,0)+1));
     w.inventory:=jsonb_set(w.inventory,array[bid],to_jsonb(coalesce((w.inventory->>bid)::integer,0)+1));
    elsif sid is not null and random()>=app_private.trap_success_chance_bp(bid,v.failure_reduction_bp,e.vessel_snapshot)::numeric/10000 then
     failed:=failed+1;
    else
     if sid is null then raise exception 'NO_COLLECTIBLE_FOR_REGION';end if;
     insert into public.player_collectibles(user_id,species_id) values(u,sid) returning id into item;
     insert into public.player_discoveries(user_id,species_id) values(u,sid) on conflict do nothing;
     results:=results||jsonb_build_array(jsonb_build_object('id',item,'firstDiscovery',coalesce((select evidence.first_discovery from app_private.title_acquisition_evidence evidence where evidence.collectible_id=item and evidence.user_id=u),false),'species',app_private.species_payload(sid,null),'bonus',i>total,'baitId',bid));
    end if;
   end loop;
   receipt:=jsonb_build_object('action','claim','expeditionId',e.id,'result',jsonb_build_object('items',results,'refunds',refunds,'failed',failed,'attempted',cardinality(draws),'succeeded',jsonb_array_length(results)));
   update public.player_wallets set inventory=w.inventory,updated_at=now() where user_id=u;
   update public.fishing_expeditions set claimed_at=clock_timestamp(),result=receipt->'result' where id=e.id;
  end if;
 end if;
 insert into app_private.expedition_operations values(u,p_operation_id,sig,receipt);
 return app_private.expedition_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.settle_legacy_harbor(p_action text, p_operation_id uuid, p_vessel_id text DEFAULT NULL::text, p_voyage_id uuid DEFAULT NULL::uuid, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();v public.harbor_vessels;w public.player_wallets;trip public.harbor_voyages;
 prev app_private.harbor_operations;sig jsonb;receipt jsonb;fuel integer;cost integer;sid text;item uuid;i integer;purchase_at timestamptz;
 results jsonb:='[]'::jsonb;items jsonb;failed integer;attempts integer;claimed integer:=0;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('buy','fuel','depart','arrive','claim','claim_all') then raise exception 'INVALID_HARBOR_ACTION';end if;
 sig:=jsonb_build_object('action',p_action,'vessel',p_vessel_id,'voyage',p_voyage_id,'quantity',p_quantity);
 perform pg_advisory_xact_lock(hashtextextended('harbor:'||u::text,0));
 select * into prev from app_private.harbor_operations where user_id=u and operation_id=p_operation_id;
 if found then
  if prev.signature<>sig then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.harbor_state()||jsonb_build_object('receipt',prev.receipt,'replayed',true);
 end if;
 perform app_private.get_gold_wallet();
 select * into w from public.player_wallets where user_id=u for update;
 fuel:=coalesce((w.inventory->>'fuel')::integer,0);purchase_at:=clock_timestamp();
 if p_action in ('buy','depart') then
  select * into v from public.harbor_vessels where id=p_vessel_id;
  if not found then raise exception 'VESSEL_NOT_FOUND';end if;
 end if;
 if p_action='buy' then
  if exists(select 1 from public.player_harbor_vessels where user_id=u and vessel_id=v.id) then raise exception 'VESSEL_ALREADY_OWNED';end if;
  if w.gold<v.price then raise exception 'INSUFFICIENT_GOLD';end if;
  insert into public.player_harbor_vessels(user_id,vessel_id) values(u,v.id);
  update public.player_wallets set gold=gold-v.price,updated_at=now() where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','harbor-vessel:'||v.id,-v.price);
  receipt:=jsonb_build_object('action','buy','vesselId',v.id);
 elsif p_action='fuel' then
  if p_quantity is null or p_quantity<1 or p_quantity>5 or fuel>100000-p_quantity then raise exception 'INVALID_QUANTITY';end if;
  if coalesce((select sum((op.receipt->>'quantity')::integer) from app_private.harbor_operations op
   where op.user_id=u and op.receipt->>'action'='fuel' and op.created_at>=((purchase_at at time zone 'Asia/Seoul')::date::timestamp at time zone 'Asia/Seoul')),0)+p_quantity>5 then raise exception 'FUEL_DAILY_LIMIT';end if;
  cost:=p_quantity*57;
  if w.gold<cost then raise exception 'INSUFFICIENT_GOLD';end if;
  update public.player_wallets set gold=gold-cost,inventory=jsonb_set(inventory,'{fuel}',to_jsonb(fuel+p_quantity)),updated_at=now() where user_id=u;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(u,p_operation_id,'buy','fuel:'||p_quantity,-cost);
  receipt:=jsonb_build_object('action','fuel','quantity',p_quantity);
 elsif p_action='depart' then
  if not exists(select 1 from public.player_harbor_vessels where user_id=u and vessel_id=v.id) then raise exception 'VESSEL_NOT_OWNED';end if;
  if exists(select 1 from public.harbor_voyages where user_id=u and vessel_id=v.id and claimed_at is null) then raise exception 'VOYAGE_ACTIVE';end if;
  if fuel<v.fuel_cost then raise exception 'INSUFFICIENT_FUEL';end if;
  update public.player_wallets set inventory=jsonb_set(inventory,'{fuel}',to_jsonb(fuel-v.fuel_cost)),updated_at=now() where user_id=u;
  insert into public.harbor_voyages(user_id,vessel_id,vessel_snapshot,returns_at)
   values(u,v.id,to_jsonb(v),clock_timestamp()+make_interval(mins=>v.duration_minutes)) returning * into trip;
  receipt:=jsonb_build_object('action','depart','voyageId',trip.id,'vesselId',v.id);
 elsif p_action='arrive' then
  select * into trip from public.harbor_voyages where id=p_voyage_id and user_id=u for update;
  if not found then raise exception 'VOYAGE_NOT_FOUND';end if;
  if trip.returns_at>clock_timestamp() then raise exception 'VOYAGE_NOT_READY';end if;
  update public.harbor_voyages set arrival_seen_at=coalesce(arrival_seen_at,clock_timestamp()) where id=trip.id;
  receipt:=jsonb_build_object('action','arrive','voyageId',trip.id);
 else
  if p_action='claim' then
   select * into trip from public.harbor_voyages where id=p_voyage_id and user_id=u;
   if not found then raise exception 'VOYAGE_NOT_FOUND';end if;
   if trip.claimed_at is not null then
    receipt:=jsonb_build_object('action','claim','results',jsonb_build_array(trip.result));
   elsif trip.returns_at>clock_timestamp() then raise exception 'VOYAGE_NOT_READY';end if;
  end if;
  if receipt is null then
   for trip in select * from public.harbor_voyages where user_id=u and claimed_at is null and returns_at<=clock_timestamp()
    and (p_action='claim_all' or id=p_voyage_id) order by id for update loop
    items:='[]'::jsonb;failed:=0;attempts:=(trip.vessel_snapshot->>'fishing_count')::integer;
    for i in 1..attempts loop
     sid:=app_private.harbor_draw(case when trip.vessel_snapshot->>'secondary_region_id' is not null and i>attempts/2 then trip.vessel_snapshot->>'secondary_region_id' else trip.region_id end,trip.vessel_snapshot->'catch_rule');
     if sid is not null then
      insert into public.player_collectibles(user_id,species_id) values(u,sid) returning id into item;
      insert into public.player_discoveries(user_id,species_id) values(u,sid) on conflict do nothing;
      items:=items||jsonb_build_array(jsonb_build_object('id',item,'firstDiscovery',coalesce((select evidence.first_discovery from app_private.title_acquisition_evidence evidence where evidence.collectible_id=item and evidence.user_id=u),false),'species',app_private.species_payload(sid,null),'bonus',false));
     else failed:=failed+1;end if;
    end loop;
    update public.harbor_voyages set claimed_at=clock_timestamp(),arrival_seen_at=coalesce(arrival_seen_at,clock_timestamp()),
     result=jsonb_build_object('voyageId',trip.id,'regionId',trip.region_id,'regionName',(select name from public.regions where id=trip.region_id)||case when trip.vessel_snapshot->>'secondary_region_id' is not null then ' · '||(trip.vessel_snapshot->>'secondary_region_name') else '' end,'vesselName',trip.vessel_snapshot->>'name','items',items,'attempted',attempts,'failed',failed,'succeeded',jsonb_array_length(items)) where id=trip.id returning result into receipt;
    results:=results||jsonb_build_array(receipt);claimed:=claimed+1;
   end loop;
   receipt:=jsonb_build_object('action',p_action,'results',results,'claimed',claimed);
  end if;
 end if;
 insert into app_private.harbor_operations(user_id,operation_id,signature,receipt,created_at) values(u,p_operation_id,sig,receipt,purchase_at);
 return app_private.harbor_state()||jsonb_build_object('receipt',receipt,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION app_private.shadow_game(p_action text, p_operation_id uuid DEFAULT NULL::uuid, p_run_id uuid DEFAULT NULL::uuid, p_round_id uuid DEFAULT NULL::uuid, p_choice_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();r public.shadow_game_runs;q app_private.shadow_game_rounds;v_gold integer;v_correct boolean;v_timeout boolean;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_action is null or p_action not in ('state','start','answer','next') then raise exception 'INVALID_SHADOW_ACTION'; end if;
 if p_action='state' then
  if p_run_id is not null then
   select * into r from public.shadow_game_runs where id=p_run_id and user_id=v_uid;
   if not found then raise exception 'SHADOW_RUN_NOT_FOUND'; end if;
  else select * into r from public.shadow_game_runs where user_id=v_uid and finished_at is null;
  end if;
  return app_private.shadow_run_response(r.id);
 end if;
 perform app_private.get_gold_wallet();
 select gold into v_gold from public.player_wallets where user_id=v_uid for update;
 if p_action='start' then
  if p_operation_id is null then raise exception 'INVALID_OPERATION'; end if;
  select * into r from public.shadow_game_runs where user_id=v_uid and operation_id=p_operation_id;
  if found then return app_private.shadow_run_response(r.id); end if;
  select * into r from public.shadow_game_runs where user_id=v_uid and finished_at is null;
  if found then return app_private.shadow_run_response(r.id); end if;
  if v_gold<10 then raise exception 'INSUFFICIENT_GOLD'; end if;
  insert into public.shadow_game_runs(user_id,operation_id) values(v_uid,p_operation_id) returning * into r;
  perform app_private.shadow_new_round(r.id);
  update public.player_wallets set gold=gold-10,updated_at=clock_timestamp() where user_id=v_uid;
  insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,'buy','arcade:shadow',-10);
  return app_private.shadow_run_response(r.id);
 end if;
 select * into r from public.shadow_game_runs where id=p_run_id and user_id=v_uid for update;
 if not found then raise exception 'SHADOW_RUN_NOT_FOUND'; end if;
 select * into q from app_private.shadow_game_rounds where id=p_round_id and run_id=r.id;
 if not found then raise exception 'SHADOW_ROUND_NOT_FOUND'; end if;
 if r.finished_at is not null then return app_private.shadow_run_response(r.id); end if;
 if r.score>=100 then
  update public.shadow_game_runs set finished_at=clock_timestamp() where id=r.id;
  return app_private.shadow_run_response(r.id);
 end if;
 if p_action='answer' then
  if q.answered_at is not null then return app_private.shadow_run_response(r.id); end if;
  v_timeout:=clock_timestamp()>=q.deadline;
  if p_choice_id is null and not v_timeout then raise exception 'SHADOW_NOT_EXPIRED'; end if;
  if p_choice_id is not null and not exists(select 1 from jsonb_array_elements(q.options) o where o->>'id'=p_choice_id) then raise exception 'INVALID_SHADOW_CHOICE'; end if;
  v_correct:=not v_timeout and coalesce(p_choice_id=q.target_id,false);
  update app_private.shadow_game_rounds set answered_at=clock_timestamp(),correct=v_correct,timed_out=v_timeout where id=q.id;
  update public.shadow_game_runs set score=least(100,score+case when v_correct then 1 else 0 end),
   lives=lives-case when v_correct then 0 else 1 end,
   finished_at=case when (not v_correct and lives=1) or (v_correct and score>=99) then clock_timestamp() else null end where id=r.id;
 else
  if q.answered_at is null then raise exception 'SHADOW_ANSWER_REQUIRED'; end if;
  if q.number=(select max(number) from app_private.shadow_game_rounds where run_id=r.id) then perform app_private.shadow_new_round(r.id); end if;
 end if;
 return app_private.shadow_run_response(r.id);
end $function$

CREATE OR REPLACE FUNCTION app_private.shadow_new_round(p_run uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_options jsonb;v_target jsonb;v_number integer;
begin
 select jsonb_agg(jsonb_build_object('id',id,'name',name,'path',thumbnail_path)) into v_options
 from (select * from (select distinct on(name) id,name,thumbnail_path from public.collectible_species
 where kind<>'map' and thumbnail_path is not null and thumbnail_path<>'' order by name,id) pool order by random() limit 4) chosen;
 if jsonb_array_length(coalesce(v_options,'[]'::jsonb))<>4 then raise exception 'SHADOW_POOL_UNAVAILABLE'; end if;
 v_target:=v_options->floor(random()*4)::integer;
 select coalesce(max(number),0)+1 into v_number from app_private.shadow_game_rounds where run_id=p_run;
 insert into app_private.shadow_game_rounds(run_id,number,target_id,target_name,image_path,options,deadline)
 values(p_run,v_number,v_target->>'id',v_target->>'name',v_target->>'path',
 (select jsonb_agg(jsonb_build_object('id',o->>'id','name',o->>'name')) from jsonb_array_elements(v_options) o),clock_timestamp()+interval '8 seconds');
end $function$

CREATE OR REPLACE FUNCTION app_private.shadow_run_response(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.shadow_game_runs;q app_private.shadow_game_rounds;
begin
 if p_run is null then return jsonb_build_object('run',null,'serverNow',clock_timestamp()); end if;
 select * into strict r from public.shadow_game_runs where id=p_run;
 select * into q from app_private.shadow_game_rounds where run_id=r.id order by number desc limit 1;
 return jsonb_build_object('serverNow',clock_timestamp(),'run',jsonb_build_object(
 'id',r.id,'score',r.score,'lives',r.lives,'finished',r.finished_at is not null,
 'round',jsonb_build_object('id',q.id,'number',q.number,'imagePath',q.image_path,'options',q.options,'deadline',q.deadline,
 'answered',q.answered_at is not null,'correct',q.correct,'timedOut',q.timed_out,
 'answerName',case when q.answered_at is not null then q.target_name else null end)));
end $function$

CREATE OR REPLACE FUNCTION app_private.showcase_feed(p_mine boolean DEFAULT false, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if p_offset is null or p_offset<0 or p_offset>10000 or p_mine is null then raise exception 'INVALID_SHOWCASE';end if;
 select jsonb_build_object('items',coalesce(jsonb_agg(app_private.showcase_post_json(p) order by p.created_at desc,p.id desc),'[]'::jsonb),
 'total',(select count(*) from public.fishing_showcase_posts where not p_mine or author_id=auth.uid())) into result
