CREATE OR REPLACE FUNCTION app_private.start_fishing_fight(p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();p app_private.prepared_fishing_casts;v_started timestamptz;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||v_uid::text,0));
 select * into p from app_private.prepared_fishing_casts where user_id=v_uid and operation_id=p_operation_id for update;
 if not found then raise exception 'CAST_NOT_FOUND';end if;
 if p.finished_at is not null then return app_private.prepared_fishing_payload(p);end if;
 if clock_timestamp()>=p.expires_at then
  perform app_private.finish_fishing(p.operation_id,false);
  select * into p from app_private.prepared_fishing_casts where user_id=v_uid and operation_id=p_operation_id;
  return app_private.prepared_fishing_payload(p);
 end if;
 if not p.confirm_bite or p.fight_started_at is not null then return app_private.prepared_fishing_payload(p);end if;
 if clock_timestamp()<p.created_at+make_interval(secs=>p.wait_seconds::double precision) then raise exception 'CAST_TOO_EARLY';end if;
 v_started:=clock_timestamp();
 update app_private.prepared_fishing_casts set fight_started_at=v_started,expires_at=v_started+interval '3 minutes'
 where user_id=v_uid and operation_id=p_operation_id returning * into p;
 return app_private.prepared_fishing_payload(p);
end $function$

CREATE OR REPLACE FUNCTION app_private.sync_player_profile()
 RETURNS player_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_name text; v_profile public.player_profiles;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select raw_user_meta_data ->> 'game_nickname' into v_name from auth.users where id = v_uid;
  if v_name is null or v_name !~ '^[가-힣a-zA-Z0-9_]{2,12}$' then raise exception 'NICKNAME_REQUIRED'; end if;
  -- Retry only the extraordinarily rare random-code collision.
  for attempt in 1..5 loop
    begin
      insert into public.player_profiles(id, nickname) values (v_uid, v_name)
      on conflict(id) do update set nickname = excluded.nickname
      returning * into v_profile;
      return v_profile;
    exception when unique_violation then
      if attempt = 5 then raise; end if;
    end;
  end loop;
  raise exception 'PROFILE_CREATE_FAILED';
end $function$

CREATE OR REPLACE FUNCTION app_private.sync_player_titles(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare metrics jsonb;t record;
begin
 perform pg_advisory_xact_lock(hashtextextended('titles:'||p_user::text,0));
 metrics:=app_private.title_metrics(p_user)||app_private.rare_title_metrics(p_user)||app_private.challenge_title_metrics(p_user)||app_private.everyday_title_metrics(p_user);
 for t in select * from public.title_catalog c where coalesce((metrics->>c.metric)::bigint,0)>=c.target
 and (c.extra_metric is null or coalesce((metrics->>c.extra_metric)::bigint,0)>=c.extra_target)
 and not exists(select 1 from public.player_titles o where o.user_id=p_user and o.title_id=c.id) order by sort_order
 loop perform app_private.award_title(p_user,t.id);end loop;
 return metrics;
end $function$

CREATE OR REPLACE FUNCTION app_private.sync_titles()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();before_count integer;after_count integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 delete from app_private.title_dirty where user_id=u;
 if not found then return 0;end if;
 select count(*) into before_count from public.player_titles where user_id=u;
 perform app_private.sync_player_titles(u);
 select count(*) into after_count from public.player_titles where user_id=u;
