CREATE OR REPLACE FUNCTION app_private.title_activity_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a uuid;b uuid;
begin
 if tg_table_name in ('aquarium_feedings','aquarium_cleanings') then
  if new.completed_at is null then return new;end if;a:=new.visitor_id;b:=new.owner_id;
 elsif tg_table_name='expedition_boosts' then a:=new.helper_id;
 elsif tg_table_name='exchange_listings' then a:=new.owner_id;b:=new.taker_id;
 elsif tg_table_name in ('collectible_gifts','friend_requests') then a:=new.sender_id;b:=new.recipient_id;
 else a:=new.user_id;
 end if;
 if a is not null then insert into app_private.title_dirty values(a) on conflict do nothing;end if;
 if b is not null then insert into app_private.title_dirty values(b) on conflict do nothing;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.title_board_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous_author uuid;current_author uuid;previous_post uuid;current_post uuid;
begin
 if tg_table_name='board_posts' then
  if tg_op<>'INSERT' then previous_author:=old.author_id;end if;
  if tg_op<>'DELETE' then current_author:=new.author_id;end if;
 else
  if tg_op<>'INSERT' then previous_post:=old.post_id;end if;
  if tg_op<>'DELETE' then current_post:=new.post_id;end if;
  insert into app_private.title_dirty(user_id)
   select distinct author_id from public.board_posts where id in (previous_post,current_post) on conflict do nothing;
 end if;
 if previous_author is not null then insert into app_private.title_dirty values(previous_author) on conflict do nothing;end if;
 if current_author is not null then insert into app_private.title_dirty values(current_author) on conflict do nothing;end if;
 return null;
end $function$

CREATE OR REPLACE FUNCTION app_private.title_catch_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare snapshot jsonb;item jsonb;i integer:=0;last_one boolean:=false;
begin
 if tg_table_name='fishing_attempts' then
  if new.collectible_id is not null then
   select p.snapshot,p.last_bait into snapshot,last_one from app_private.prepared_fishing_casts p where p.user_id=new.user_id and p.operation_id=new.operation_id;
   if snapshot is null then select to_jsonb(s) into snapshot from public.player_collectibles c join public.collectible_species s on s.id=c.species_id where c.id=new.collectible_id;end if;
  end if;
  insert into app_private.title_fishing_log(user_id,event_key,occurred_at,source,kind,rarity,species_id,collectible_id,region_id,bait_id,last_bait)
  values(new.user_id,'cast:'||new.operation_id,new.created_at,'manual',snapshot->>'kind',snapshot->>'rarity',snapshot->>'id',new.collectible_id,new.region_id,new.bait_id,coalesce(last_one,false)) on conflict do nothing;
 else
  if new.claimed_at is null or old.claimed_at is not null then return new;end if;
  for item in select value from jsonb_array_elements(coalesce(new.result->'items','[]'::jsonb)) loop
   i:=i+1;
   insert into app_private.title_fishing_log(user_id,event_key,occurred_at,source,kind,rarity,species_id,collectible_id,region_id,bait_id,vessel_id,batch_id)
   values(new.user_id,'exp:'||new.id||':'||i,new.claimed_at,'expedition',item->'species'->>'kind',item->'species'->>'rarity',item->'species'->>'id',(item->>'id')::uuid,new.region_id,item->>'baitId',new.vessel_id,new.id::text) on conflict do nothing;
  end loop;
 end if;
 insert into app_private.title_dirty values(new.user_id) on conflict do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.title_tank_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare regions integer;trash integer;small integer;
begin
 if new.tank_id is null or new.sold_at is not null or new.escrow_gift_id is not null then return new;end if;
 select count(distinct s.native_region_id) filter(where s.is_native),count(distinct s.id) filter(where s.kind='trash'),count(distinct s.id) filter(where s.kind='fish' and s.size<=45)
 into regions,trash,small from public.player_collectibles c join public.collectible_species s on s.id=c.species_id
 where c.user_id=new.user_id and c.tank_id=new.tank_id and c.sold_at is null and c.escrow_gift_id is null;
 if regions>=5 then perform app_private.award_title(new.user_id,'tank-native');end if;
 if trash>=5 then perform app_private.award_title(new.user_id,'tank-trash');end if;
 if small>=10 then perform app_private.award_title(new.user_id,'tank-small');end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.trade_fishing_rod(p_rod_id text, p_action text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_rod public.fishing_rods;v_wallet public.player_wallets;
 v_previous public.gold_transactions;v_delta integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_operation_id is null or p_action is null or p_action not in ('buy','sell') then raise exception 'INVALID_TRADE'; end if;
 perform app_private.fishing_rod_state();
 select * into v_wallet from public.player_wallets where user_id=v_uid for update;
 select * into v_previous from public.gold_transactions where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if v_previous.action<>p_action or v_previous.item_id is distinct from 'rod:'||p_rod_id then raise exception 'OPERATION_CONFLICT'; end if;
  return app_private.get_gold_wallet()||app_private.fishing_rod_state()||jsonb_build_object('delta',0);
 end if;
 select * into v_rod from public.fishing_rods where id=p_rod_id for share;
 if not found then raise exception 'INVALID_ROD'; end if;
 if p_rod_id='basic' then raise exception 'STARTER_ROD_NOT_TRADEABLE'; end if;
 if p_action='buy' then
  if exists(select 1 from public.player_fishing_rods where user_id=v_uid and rod_id=p_rod_id) then raise exception 'ROD_ALREADY_OWNED'; end if;
  if v_wallet.gold<v_rod.price then raise exception 'INSUFFICIENT_GOLD'; end if;
  insert into public.player_fishing_rods(user_id,rod_id) values(v_uid,p_rod_id);
  v_delta:=-v_rod.price;
 else
  if not exists(select 1 from public.player_fishing_rods where user_id=v_uid and rod_id=p_rod_id) then raise exception 'ROD_NOT_OWNED'; end if;
  v_delta:=v_rod.price/2;
  if v_wallet.gold>1000000000-v_delta then raise exception 'GOLD_LIMIT'; end if;
  update public.player_rod_loadouts set equipped_rod_id='basic' where user_id=v_uid and equipped_rod_id=p_rod_id;
  delete from public.player_fishing_rods where user_id=v_uid and rod_id=p_rod_id;
 end if;
 update public.player_wallets set gold=gold+v_delta,updated_at=now() where user_id=v_uid;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta)
 values(v_uid,p_operation_id,p_action,'rod:'||p_rod_id,v_delta);
 return app_private.get_gold_wallet()||app_private.fishing_rod_state()||jsonb_build_object('delta',v_delta);
end $function$

CREATE OR REPLACE FUNCTION app_private.trade_gold(p_operation_id uuid, p_action text, p_item_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid();v_wallet public.player_wallets;v_previous public.gold_transactions;v_delta integer;v_count integer;v_price integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED';end if;
 if p_operation_id is null or p_action is null or p_action not in ('charge','buy','sell') then raise exception 'INVALID_TRADE';end if;
 insert into public.player_wallets(user_id) values(v_uid) on conflict do nothing;
 select * into v_wallet from public.player_wallets where user_id=v_uid for update;
 select * into v_previous from public.gold_transactions where user_id=v_uid and operation_id=p_operation_id;
 if found then
  if v_previous.action<>p_action or v_previous.item_id is distinct from p_item_id then raise exception 'OPERATION_CONFLICT';end if;
  return app_private.get_gold_wallet()||jsonb_build_object('delta',0);
 end if;
 if p_action='charge' then
  if p_item_id is not null then raise exception 'INVALID_TRADE';end if;
  if not coalesce((select test_charge_enabled from app_private.gold_settings where id),false) then raise exception 'TEST_CHARGE_DISABLED';end if;
  if v_wallet.test_claimed then raise exception 'TEST_CHARGE_ALREADY_CLAIMED';end if;
  v_delta:=1000;
 else
  if p_item_id is null or p_item_id not in ('bait','shell') then raise exception 'INVALID_ITEM';end if;
  v_count:=coalesce((v_wallet.inventory->>p_item_id)::integer,0);
  v_price:=case when p_item_id='bait' then (select price from public.fishing_baits where id='bait') else 300 end;
  if v_price is null then raise exception 'INVALID_ITEM';end if;
  if p_action='buy' then
   if v_wallet.gold<v_price then raise exception 'INSUFFICIENT_GOLD';end if;
   v_delta:=-v_price;v_count:=v_count+1;
  else
   if v_count<1 then raise exception 'INSUFFICIENT_INVENTORY';end if;
   v_delta:=v_price*6/10;v_count:=v_count-1;
  end if;
  v_wallet.inventory:=jsonb_set(v_wallet.inventory,array[p_item_id],to_jsonb(v_count));
 end if;
 if v_wallet.gold+v_delta>1000000000 then raise exception 'GOLD_LIMIT';end if;
 update public.player_wallets set gold=gold+v_delta,inventory=v_wallet.inventory,test_claimed=test_claimed or p_action='charge',updated_at=now() where user_id=v_uid;
 insert into public.gold_transactions(user_id,operation_id,action,item_id,delta) values(v_uid,p_operation_id,p_action,p_item_id,v_delta);
 return app_private.get_gold_wallet()||jsonb_build_object('delta',v_delta);
end $function$

CREATE OR REPLACE FUNCTION app_private.trap_pick(p_region text, p_bait text, p_native boolean, p_local_discovery boolean, p_snapshot jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.fishing_baits;r public.game_rarity;roll integer:=floor(random()*10000);ids text[];fallback boolean;profile jsonb:=p_snapshot->'bait_rules'->p_bait;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;
 if profile is null then raise exception 'INVALID_BAIT_SNAPSHOT';end if;
 if p_snapshot->>'bait_rules_version'='2' then
  r:=app_private.profile_fishing_rarity(profile);
  return app_private.pick_profile_collectible(p_region,r,profile,false,p_native,p_local_discovery);
 end if;
 b:=jsonb_populate_record(null::public.fishing_baits,profile);
 r:=case when b.alternating then app_private.consume_bait_cycle()
 when roll<b.mythic_bp then 'mythic'::public.game_rarity when roll<b.mythic_bp+b.epic_bp then 'epic'::public.game_rarity
 when roll<b.mythic_bp+b.epic_bp+b.rare_bp then 'rare'::public.game_rarity else 'common'::public.game_rarity end;
 if p_bait in ('bait_snowflake_salt','bait_shooting_star_tail') then return app_private.pick_balanced_bait_collectible(p_region,r,p_bait,p_native,false);end if;
 if b.fish_only then return app_private.pick_bait_fish(p_region,r,p_native,false);end if;
 with candidates as materialized (
 select s.id,s.rarity from public.collectible_species s where app_private.collectible_available_at(s.id,statement_timestamp()) and case
 when p_bait='bait_first_greeting' then s.kind in ('fish','trash','decoration') and not exists(select 1 from public.player_discoveries d where d.user_id=auth.uid() and d.species_id=s.id)
 and (not p_local_discovery or exists(select 1 from public.collectible_habitats h where h.species_id=s.id and h.region_id=p_region))
 when p_bait='bait_grubby_magnet' then s.kind='trash'
 when b.effect_kind='decoration' then s.kind='decoration' and s.rarity=r else s.kind in ('fish','trash') and s.rarity=r end
 ),pool as(select * from candidates c where c.rarity=r or not exists(select 1 from candidates c2 where c2.rarity=r))
 select array_agg(id order by id),not coalesce(bool_or(rarity=r),false) into ids,fallback from pool;
 return app_private.pick_habitat_group(ids,p_region,null,(case when p_native then 1.5 else 1 end)*(case when p_bait='bait_sea_memory' then 3 else 1 end),fallback and b.effect_kind<>'decoration');
end $function$

CREATE OR REPLACE FUNCTION app_private.trap_success_chance_bp(p_bait text, p_reduction integer, p_snapshot jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare b jsonb:=p_snapshot->'bait_rules'->p_bait;chance integer;
begin
 if b is null then raise exception 'INVALID_BAIT_SNAPSHOT';end if;
 if p_snapshot->>'bait_rules_version'='2' then return 10000;end if;
 if b->>'success_chance_bp' is not null then return (b->>'success_chance_bp')::integer;end if;
 chance:=case when p_bait='bait_safe' then 10000
 when p_bait in ('bait_grubby_magnet','bait_first_greeting','bait_magnet','bait_forbidden_star','bait_epic','bait_special') then 7000
 when p_bait='bait' then 3500 else 4000 end;
 return least(10000,chance+greatest(0,coalesce(p_reduction,0)));
end $function$

CREATE OR REPLACE FUNCTION app_private.travel_region(p_region_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_region public.regions;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 perform pg_advisory_xact_lock(hashtextextended('region:'||v_uid::text,0));
 select * into v_region from public.regions where id=p_region_id;
 if not found then raise exception 'REGION_NOT_FOUND'; end if;
 if v_region.requires_map_fragment and not exists(select 1 from public.player_map_fragments where user_id=v_uid and region_id=p_region_id) then raise exception 'REGION_LOCKED'; end if;
 insert into public.player_navigation(user_id,region_id) values(v_uid,p_region_id)
 on conflict(user_id) do update set region_id=excluded.region_id;
 return app_private.region_map();
end $function$

CREATE OR REPLACE FUNCTION app_private.validate_fishing_map_blueprint()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from public.region_maps where region_id=new.region_id) then raise exception 'MAP_ALREADY_SOLD';end if;
 if not exists(select 1 from public.regions where id=new.region_id and requires_map_fragment) then raise exception 'MAP_MUST_BE_LOCKED';end if;
 if tg_op='UPDATE' and (new.region_id<>old.region_id or new.piece_count<>old.piece_count) then raise exception 'MAP_PIECES_IMMUTABLE';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION app_private.web_push_device(p_action text, p_subscription jsonb, p_categories text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); e text:=p_subscription->>'endpoint'; s app_private.push_subscriptions; n integer;
begin
 if u is null then raise exception 'AUTH_REQUIRED';end if;
 if p_action is null or p_action not in ('state','save','delete','test') or e is null or length(e)>2048 then raise exception 'INVALID_PUSH_DEVICE';end if;
 select * into s from app_private.push_subscriptions where endpoint=e and user_id=u for update;
 if p_action='state' then return jsonb_build_object('registered',s.id is not null,'categories',coalesce(s.categories,array[]::text[]));end if;
 if p_action='delete' then delete from app_private.push_subscriptions where id=s.id;return jsonb_build_object('registered',false);end if;
 if p_action='test' then
  if s.id is null then raise exception 'PUSH_NOT_REGISTERED';end if;
  if s.last_test_at>clock_timestamp()-interval '1 minute' then raise exception 'PUSH_TEST_RATE_LIMIT';end if;
  update app_private.push_subscriptions set last_test_at=clock_timestamp() where id=s.id;
  insert into app_private.push_deliveries(subscription_id,category,payload,expires_at)
  values(s.id,'test',jsonb_build_object('userId',u,'title','퐁당! 알림이 도착했어요','body','이 기기에서 생산 완료·통발·귀항 소식을 받을 수 있어요.','url','/settings','tag','push-test:'||gen_random_uuid()),clock_timestamp()+interval '5 minutes');
  return jsonb_build_object('queued',true);
 end if;
 if e !~ '^https://(fcm\.googleapis\.com|([a-z0-9-]+\.)*push\.services\.mozilla\.com|([a-z0-9-]+\.)*push\.apple\.com|([a-z0-9-]+\.)*notify\.windows\.com)/[^[:space:]#]+$'
 or coalesce(p_subscription#>>'{keys,p256dh}','') !~ '^[A-Za-z0-9_-]{87}=?$'
 or coalesce(p_subscription#>>'{keys,auth}','') !~ '^[A-Za-z0-9_-]{22}={0,2}$'
 or p_categories is null or not (p_categories <@ array['production','bait-production','expedition','harbor','production-expiring','bait-production-expiring']::text[])
 or cardinality(p_categories)>6 then raise exception 'INVALID_PUSH_DEVICE';end if;
 -- Serialize this user's cap, and never transfer another account's endpoint.
 perform 1 from auth.users where id=u for update;
 if exists(select 1 from app_private.push_subscriptions where endpoint=e and user_id<>u) then raise exception 'PUSH_DEVICE_CONFLICT';end if;
 select count(*) into n from app_private.push_subscriptions where user_id=u;
 if s.id is null and n>=10 then raise exception 'PUSH_DEVICE_LIMIT';end if;
 insert into app_private.push_subscriptions(user_id,endpoint,p256dh,auth,categories)
 values(u,e,p_subscription#>>'{keys,p256dh}',p_subscription#>>'{keys,auth}',p_categories)
 on conflict(endpoint) do update set p256dh=excluded.p256dh,auth=excluded.auth,categories=excluded.categories,updated_at=clock_timestamp()
 where app_private.push_subscriptions.user_id=u;
 get diagnostics n=row_count;
 if n=0 then raise exception 'PUSH_DEVICE_CONFLICT';end if;
 return jsonb_build_object('registered',true,'categories',p_categories);
end $function$

CREATE OR REPLACE FUNCTION app_private.web_push_worker_configuration()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if to_regclass('vault.decrypted_secrets') is null then return '{}'::jsonb;end if;
 execute 'select coalesce(jsonb_object_agg(upper(name),decrypted_secret),''{}''::jsonb) from vault.decrypted_secrets where name in (''web_push_public_key'',''web_push_private_key'',''web_push_subject'',''web_push_cron_secret'')' into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.feedback_reactions(p_kind text, p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_ids is null or cardinality(p_ids)>20 then raise exception 'INVALID_FEEDBACK_IDS'; end if;
 if p_kind='suggestion' then
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'likes',coalesce(v.likes,0),'dislikes',coalesce(v.dislikes,0),'my_reaction',coalesce(v.mine,0))),'[]'::jsonb) into result
 from public.suggestion_posts p left join lateral (
  select count(*) filter(where value=1) likes,count(*) filter(where value=-1) dislikes,
   max(value) filter(where user_id=auth.uid()) mine
  from app_private.feedback_suggestion_votes where post_id=p.id
 ) v on true where p.id=any(p_ids);
 elsif p_kind='bug' then
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'likes',coalesce(v.likes,0),'dislikes',coalesce(v.dislikes,0),'my_reaction',coalesce(v.mine,0))),'[]'::jsonb) into result
 from public.bug_reports p left join lateral (
  select count(*) filter(where value=1) likes,count(*) filter(where value=-1) dislikes,
   max(value) filter(where user_id=auth.uid()) mine
  from app_private.feedback_bug_votes where post_id=p.id
 ) v on true where p.id=any(p_ids);
 else raise exception 'INVALID_FEEDBACK_KIND'; end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.set_feedback_reaction(p_kind text, p_id uuid, p_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_value is null or p_value not in (-1,0,1) then raise exception 'INVALID_FEEDBACK_VALUE'; end if;
 if p_kind='suggestion' then
 if not exists(select 1 from public.suggestion_posts where id=p_id) then raise exception 'FEEDBACK_NOT_FOUND'; end if;
 if p_value=0 then
  delete from app_private.feedback_suggestion_votes where post_id=p_id and user_id=auth.uid();
 else
  insert into app_private.feedback_suggestion_votes(post_id,user_id,value) values(p_id,auth.uid(),p_value)
  on conflict(post_id,user_id) do update set value=excluded.value;
 end if;
 elsif p_kind='bug' then
 if not exists(select 1 from public.bug_reports where id=p_id) then raise exception 'FEEDBACK_NOT_FOUND'; end if;
 if p_value=0 then
  delete from app_private.feedback_bug_votes where post_id=p_id and user_id=auth.uid();
 else
  insert into app_private.feedback_bug_votes(post_id,user_id,value) values(p_id,auth.uid(),p_value)
  on conflict(post_id,user_id) do update set value=excluded.value;
 end if;
 else raise exception 'INVALID_FEEDBACK_KIND'; end if;
 return public.feedback_reactions(p_kind,array[p_id])->0;
end $function$
